insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('theodore-roosevelt-north-dakota', '12A', 'Theodore Roosevelt National Park', 'United States', 'Badlands bison, wild horses and Roosevelt''s cabin', 'future', 'verified', 'mountainValley', 'The Great Plains & Dakotas', '{"wildlife","hiking","culture","family","expedition","senior","parks"}', '{"rugged","wild","historic","remote"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"South Unit Scenic Loop Drive","source":"https://www.nps.gov/thro/planyourvisit/car.htm","accessed":"2026-10-02","si":["wildlife","family","senior"],"booking_route":"none needed - park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"the NPS''s \"36-mile Scenic Loop Drive\" from Medora with \"outstanding views of the badlands, prairie dog towns, and abundant wildlife watching\"; \"Travel time around the loop is about 90 minutes\"; the full loop reopened on November 25, 2025 after a roughly $51 million repair of the section closed since 2019"},{"name":"Bison in both units","source":"https://www.nps.gov/thro/planyourvisit/wildlife-viewing.htm","accessed":"2026-10-02","si":["wildlife","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"bison \"roam throughout the North and South units of the park, and most visitors see them as they drive the park roads\"; NPS: \"They generally appear tranquil, but may attack without warning if they are disturbed\""},{"name":"Wild horses of the South Unit","source":"https://www.nps.gov/thro/learn/nature/horses.htm","accessed":"2026-10-02","si":["wildlife","family","senior"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"about 198 horses in the South Unit, often seen near the Talkington trailhead (I-94 Exit 36), Painted Canyon, Buck Hill and Wind Canyon; they \"are often visible from the Scenic Loop Drive and from I-94\""},{"name":"North Unit Scenic Drive and River Bend Overlook","source":"https://www.nps.gov/thro/planyourvisit/car.htm","accessed":"2026-10-02","si":["wildlife","senior","family"],"booking_route":"none needed - park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"a \"14-mile scenic drive\" off US 85 that \"rolls across the badlands and then climbs up to the historic River Bend Overlook\" and on to Oxbow Overlook; out and back \"generally takes just over one hour\"; River Bend has an accessible viewing deck"},{"name":"Painted Canyon Overlook and Trail","source":"https://www.nps.gov/thro/planyourvisit/hiking-and-trail-information.htm","accessed":"2026-10-02","si":["hiking","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"a 0.9-mile, 45-minute trail that \"Descends into canyon revealing rock layers and junipers\"; the NPS warns \"every step down means a step back up on the return\"; Painted Canyon has its own visitor centre and park store"},{"name":"Maltese Cross Cabin","source":"https://www.nps.gov/thro/learn/historyculture/maltese-cross-cabin.htm","accessed":"2026-10-02","si":["culture","family","senior"],"booking_route":"none needed; tour times not stated on the page","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"Roosevelt''s 1883 ponderosa pine cabin, which he called \"a temporary home\", behind the South Unit Visitor Center; shown at the 1904 St. Louis World''s Fair and holding a trunk marked \"T.R.\"; wheelchair accessible per the NPS"},{"name":"Wind Canyon Trail","source":"https://www.nps.gov/thro/planyourvisit/hiking-and-trail-information.htm","accessed":"2026-10-02","si":["hiking","family","romance"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"0.4 miles, 20 minutes, in the South Unit: \"Canyon-side hiking with river views\" and a named sunset spot; also one of the NPS''s wild-horse viewing locations"},{"name":"Medora Musical, Burning Hills Amphitheatre","source":"https://medora.com/medoramusical/","accessed":"2026-10-02","si":["culture","family","senior","group"],"booking_route":"etix.com, medora.com or 1-800-MEDORA-1; group packages 20+","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":8,"blurb":"\"the ultimate Country Western Music Revue\" in an outdoor amphitheatre of over 2,800 seats, with wheelchair and mobility seating on the mezzanine; 2026 season June 3 to September 12; adults $62.95-$85.95, students $25.95-$45.95, age 6 and under free; 15% senior discount on Tuesdays"},{"name":"Theodore Roosevelt Presidential Library, Medora","source":"https://www.trlibrary.com/visit/hours","accessed":"2026-10-02","si":["culture","senior","family"],"booking_route":"timed tickets at trlibrary.com/tickets; engine not named","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities","shop"],"draw_rank":9,"blurb":"\"open now\" in Medora, with museum, retail store and restaurant; fall hours September 14 to November 30 Tue-Fri 9-4, Sat-Sun 9-6; \"Last timed entry\" 90 minutes before closing; the outdoor boardwalk is \"Accessible outside of Library hours\""},{"name":"Prairie dog towns and the Buckhorn Trail","source":"https://www.nps.gov/thro/planyourvisit/wildlife-viewing.htm","accessed":"2026-10-02","si":["wildlife","family","hiking"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"The park road passes through three large prairie dog towns in the South Unit\"; in the North Unit, Prairie Dog Town via Buckhorn is 1.5 miles and the full Buckhorn 11.4 miles; NPS: \"Rattlesnakes and black widow spiders often live in prairie dog burrows\""},{"name":"Pitchfork Steak Fondue","source":"https://medora.com/pitchforksteakfondue/","accessed":"2026-10-02","si":["culinary","family","group"],"booking_route":"etix.com, medora.com or 1-800-MEDORA-1","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":11,"blurb":"\"we take 12 oz steaks, cooked to medium-well perfection, and give them a western-style fondue twist!\" - New York strips on pitchforks dunked in barrels of oil, with a buffet and live music; 2026 season June 3 to September 12; $54.55 full, $29.35 buffet only, kids'' hotdog meal free for 12 and under"},{"name":"Oxbow Overlook","source":"https://www.nps.gov/places/oxbow-overlook.htm","accessed":"2026-10-02","si":["senior","family","romance"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"at the end of the North Unit Scenic Drive, \"a spectacular scenic vista\" over the meandering Little Missouri, with an accessible sidewalk, interpretive waysides, restrooms and RV parking"},{"name":"Maah Daah Hey Trail","source":"https://medora.com/maahdaahheytrail/","accessed":"2026-10-02","si":["expedition","hiking","adventure","sports"],"booking_route":"none needed; shuttles via Dakota Cycling Adventures","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"per Medora, \"This 144-mile trail traverses the Badlands, Little Missouri National Grasslands, private land, and the North and South Units\" for hiking, biking and horses, managed by the USFS Dakota Prairie Grasslands; the NPS hiking page calls it a \"96-mile trail connecting all three units\""},{"name":"Elkhorn Ranch Unit","source":"https://www.nps.gov/thro/learn/historyculture/elkhorn-ranch.htm","accessed":"2026-10-02","si":["culture","expedition","hiking"],"booking_route":"none needed; ask at a visitor centre about road conditions","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"Roosevelt''s second ranch, \"thirty-five miles north of Medora\"; \"While the Elkhorn Cabin no longer stands, foundation stones indicate where the structure... was once located\"; NPS: \"The last three miles of the route sometimes require 4-wheel drive and/or a high-clearance vehicle\""},{"name":"Petrified Forest Loop","source":"https://www.nps.gov/thingstodo/hike-the-petrified-forest.htm","accessed":"2026-10-02","si":["hiking","expedition","adventure"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":15,"blurb":"\"Theodore Roosevelt National Park is home to the third highest concentration of petrified wood in the United States\"; 3 miles out and back to either section or 10.4 miles for the loop; NPS: \"Directions to the Petrified Forest trailhead have changed. Please use the approved legal route from I-94, Exit 10\""},{"name":"Caprock Coulee Trail","source":"https://www.nps.gov/thro/planyourvisit/hiking-and-trail-information.htm","accessed":"2026-10-02","si":["hiking","adventure"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":16,"blurb":"North Unit: the 1.5-mile nature trail through \"Badlands terrain; diverse habitats and dry washes\", or the full 4.3-mile loop climbing to a butte ridge, 2-3 hours"},{"name":"Cottonwood Campground","source":"https://www.nps.gov/thro/planyourvisit/cottonwood-campground.htm","accessed":"2026-10-02","si":["family","group"],"booking_route":"recreation.gov or 1 (877) 444-6777","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":17,"blurb":"76 sites including one group site in the South Unit, pull-throughs up to 85 ft; \"Beginning May 1, 2026 all sites are by reservation at recreation.gov\"; primitive, no hookups or showers"},{"name":"Juniper Campground","source":"https://www.nps.gov/thro/planyourvisit/juniper-campground.htm","accessed":"2026-10-02","si":["family","hiking"],"booking_route":"recreation.gov","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":18,"blurb":"the North Unit campground; \"Many sites are quite large (over 50 ft)\" and walk-to sites \"can only accomodate passenger vehicles\"; two accessible sites; primitive, no hookups or showers"},{"name":"Medora Campground, cabins and Conestoga wagons","source":"https://medora.com/medoracampground/","accessed":"2026-10-02","si":["glamping","family","group"],"booking_route":"medora.com / 1-800-MEDORA-1; engine not named","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":19,"blurb":"226 tent and RV sites from tent-only to 50-amp full hookups, cabins for 7-8 including the new Rivers Edge Cabins, and Conestoga wagons that sleep 4 with a king bed and air conditioning \"along the Little Missouri River\"; season May 12 to October 4"},{"name":"Rough Riders Hotel, Medora","source":"https://medora.com/roughridershotel/","accessed":"2026-10-02","si":["romance","culture","senior"],"booking_route":"medora.com or 1-800-MEDORA-1","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":20,"blurb":"a former boarding house with \"a grand hearth, tin-tiled ceiling, and one of the largest private libraries of books by and about Theodore Roosevelt\"; historic wing by stairs only, ADA rooms in the standard wing; year-round"},{"name":"Hotel 1883, Medora","source":"https://medora.com/hotel1883/","accessed":"2026-10-02","si":["family","senior","group"],"booking_route":"bookings.medora.com or 1-800-MEDORA-1","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":21,"blurb":"\"Nestled along the west bank of the Little Missouri River\", over 100 rooms in 15 layouts, with an indoor pool and hot tub and continental breakfast; named for the year Medora was founded"},{"name":"Buck Hill","source":"https://www.nps.gov/thro/planyourvisit/hiking-and-trail-information.htm","accessed":"2026-10-02","si":["wildlife","family","senior"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":22,"blurb":"0.2 miles, \"Short but steep\", to the highest accessible point in the park; the NPS names the Buck Hill area for elk \"feeding in early morning or evening\""},{"name":"Boicourt Overlook and Skyline Vista","source":"https://www.nps.gov/thro/planyourvisit/hiking-and-trail-information.htm","accessed":"2026-10-02","si":["senior","romance","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":23,"blurb":"two of the park''s shortest walks: Skyline Vista, 0.1 miles, \"Flat, paved\"; Boicourt Overlook, 0.2 miles, \"ranger-recommended for sunsets\"; both named by the NPS as hard-surfaced"},{"name":"Achenbach Trail and Sperati Point","source":"https://www.nps.gov/thro/planyourvisit/hiking-and-trail-information.htm","accessed":"2026-10-02","si":["expedition","hiking","adventure"],"booking_route":"free backcountry permit at the North or South Unit Visitor Center for overnight","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":24,"blurb":"North Unit, 18 miles, 10-12 hours, with \"Steep climbs and descents and two river crossings\"; the shorter Sperati Point via Achenbach is 1.5 miles from Oxbow Overlook to a river overlook"},{"name":"Little Missouri River float, Medora to Long X Bridge","source":"https://www.nps.gov/thro/planyourvisit/canoeing-kayaking.htm","accessed":"2026-10-02","si":["expedition","adventure"],"booking_route":"free backcountry permit for overnight camping; no outfitter named by the NPS","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":25,"blurb":"107.5 miles, about five days; \"May and June usually being the best months\"; \"A river depth of at least 2.5 feet (699 cfs) at Medora is required for fair boating\"; storms can make it \"a raging torrent carrying large logs and debris\""},{"name":"Medora Trail Rides (Medora Riding Stables)","source":"https://medora.com/trailrides/","accessed":"2026-10-02","si":["adventure","family"],"booking_route":"etix.com","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":26,"blurb":"guided rides run by the Theodore Roosevelt Medora Foundation: 30 minutes $47.95, 1 hour $56.95, 2 hours $113.95; minimum age 7, 250 lb limit; fall season September 28 to October 11, Friday-Sunday only; the NPS says \"Guided trail rides are no longer offered within the park\""},{"name":"Dakota Cycling Adventures, Medora","source":"https://www.dakotacyclingadventures.com/","accessed":"2026-10-02","si":["adventure","sports","expedition"],"booking_route":"phone/website contact; engine not observed","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":27,"blurb":"at 365 Main St, \"the only full service bike shop in the heart of the Badlands\": rentals, Maah Daah Hey shuttles and guided tours; named by Medora as the trail''s outfitter (as Dakota Cyclery)"},{"name":"Water kit for badlands hiking","source":"https://www.nps.gov/thro/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","expedition","family"],"booking_route":"affiliate retail link (REI.com via AvantLink; Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":28,"blurb":"the NPS: \"The most important thing to have with you on a hike in the North Dakota badlands is water\" - \"we recommend around 1 liter of water per person per hour\", and \"Backcountry hikers should plan to carry all the water they will need for their entire itinerary\"; the park has no services inside it"},{"name":"Boots, map and first-aid kit for the trails","source":"https://www.nps.gov/thro/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"affiliate retail link (REI.com via AvantLink; Amazon Associates); maps at the park visitor centers","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":29,"blurb":"the NPS: \"Always wear proper footwear and carry a map and first aid kit\" - \"you shouldn''t just throw on flip-flops and head out on the trail\"; \"Detailed maps are available for sale at the park visitor centers\"; it also warns of \"ticks in late spring and early summer\" and that rattlesnakes \"do not always give a warning before striking\""},{"name":"Bully Pulpit Golf Course","source":"https://medora.com/bullypulpit/","accessed":"2026-10-02","si":["sports","group"],"booking_route":"Quick18 (bullypulpit.quick18.com)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":30,"blurb":"18 holes \"carved into North Dakota''s Badlands\" along the Little Missouri, billed as \"Voted USA Today''s #1 Best Golf Course in 2025\"; April-October, weather dependent; summer from $147, spring and fall from $107, juniors free with a paying adult; shuttle from select Medora lodging"},{"name":"Chateau de Mores State Historic Site, Medora","source":"https://www.history.nd.gov/historicsites/chateau/index.html","accessed":"2026-10-02","si":["culture","senior","family"],"booking_route":"walk-in; group rates available","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":31,"blurb":"\"This 26-room, two-story frame building was built in 1883 as the summer residence of the Marquis''s family\"; the chateau is closed October 1-April 30, the interpretive centre open Tue-Sat 9-5 in that period; adult $10, child 6-17 $5; \"Allow one hour for visit\""},{"name":"North Dakota Cowboy Hall of Fame, Medora","source":"https://www.northdakotacowboy.org/","accessed":"2026-10-02","si":["culture","family","senior"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":32,"blurb":"\"the interpretive center for the history of the northern plains and North Dakota''s western lifestyle\", with galleries on Native Americans, homesteaders, ranchers and rodeo cowboys; children free; year-round with adjusted winter hours"},{"name":"Theodore''s Dining Room and TR''s Tavern","source":"https://medora.com/teddystavern/","accessed":"2026-10-02","si":["culinary","romance","wine"],"booking_route":"not observed","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":33,"blurb":"\"upscale Western cuisine\" in the Rough Riders Hotel; TR''s Tavern pours \"Classic Cocktails with a TR Twist\" with Maple Bourbon Brussel Sprouts, Shrimp and Grits and Bourbon Steak Tips, Wednesday-Sunday 4-8:30 pm, year-round"},{"name":"Medora Gospel Brunch","source":"https://medora.com/gospelbrunch/","accessed":"2026-10-02","si":["culinary","culture","senior","group"],"booking_route":"etix.com or 1-800-MEDORA-1","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","activities"],"draw_rank":34,"blurb":"the 2026 show \"Hope Rising\" with a band and gospel quartet and \"endless helpings of egg bakes, breakfast meats, and more\" at the Town Square Showhall; June 12 to September 13, 2026, Tue, Wed, Fri and Sun at 9 am MDT; adults $59.95-$65.95 with brunch"},{"name":"Rough Rider State Park (formerly Sully Creek), near Medora","source":"https://www.parkrec.nd.gov/sully-creek-state-park","accessed":"2026-10-02","si":["adventure","family","hiking"],"booking_route":"ND Parks online reservations or 800-807-4723","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":35,"blurb":"\"just minutes away from the historic town of Medora\": modern sites $25-30, primitive $15, equestrian camping, a Maah Daah Hey trailhead \"just northwest of the park entrance\", and spring canoeing on the Little Missouri; book up to 95 days ahead"},{"name":"Red Trail Campground, Medora","source":"https://www.redtrailcampground.com/","accessed":"2026-10-02","si":["family"],"booking_route":"Rates & Reservations on its site; (800) 621-4317","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":36,"blurb":"\"family owned and operated campground, providing campers with a second home for over 47 years\"; Good Sam and FMCA discounts; season May 15 to September 30"},{"name":"Boots Campground, Medora","source":"https://www.campspot.com/park/boots-campground","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Campspot","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":37,"blurb":"\"3576 East River Road South, Medora\", \"one mile outside of Historic Medora\": 16 RV sites with \"full electrical and water hookups\" plus sewer, 30/50-amp, rigs to 50 ft, 3 cabins, Wi-Fi and the on-site Boots Bar & Grill; no bathrooms or showers on site; from $45 a night (Campspot listing)"},{"name":"The Crossings Campground, Belfield","source":"https://www.campspot.com/park/thecrossingscampground","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Campspot","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":38,"blurb":"\"301 Highway 10 West, Belfield\": 31 full-hookup RV sites (30/50-amp, sewer, water, Wi-Fi) in \"a clean, no-frills atmosphere\"; \"9.5 miles from Painted Canyon Overlook & Visitor Center\", \"15 miles east of TRNP South Unit & Historic Medora\", \"30 miles south of\" the North Unit; \"we do not have an office or bathroom facilities on site\""},{"name":"TownePlace Suites by Marriott Dickinson","source":"https://hotelguides.com/north-dakota/dickinson-nd-hotels.html","accessed":"2026-10-03","si":["family","senior","motoring"],"booking_route":"marriott.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":39,"blurb":"Listed by HotelGuides at \"240 29th Street West, Dickinson, ND 58601\" among Dickinson, ND hotels; the NPS puts Dickinson 35 miles from the South Unit. The brand''s own page (marriott.com) was not fetched, so nothing else about the property is stated here."},{"name":"Hampton Inn Dickinson","source":"https://hotelguides.com/north-dakota/dickinson-nd-hotels.html","accessed":"2026-10-03","si":["family","senior","motoring"],"booking_route":"hilton.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":40,"blurb":"Listed by HotelGuides at \"100 14th Street West, Dickinson, ND 58601\" among Dickinson, ND hotels; the NPS puts Dickinson 35 miles from the South Unit. The brand''s own page (hilton.com) was not fetched, so nothing else about the property is stated here."},{"name":"Holiday Inn Express & Suites Dickinson","source":"https://hotelguides.com/north-dakota/dickinson-nd-hotels.html","accessed":"2026-10-03","si":["family","senior","motoring"],"booking_route":"ihg.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":41,"blurb":"Listed by HotelGuides at \"103 14th Street West, Dickinson, ND 58601\" among Dickinson, ND hotels; the NPS puts Dickinson 35 miles from the South Unit. The brand''s own page (ihg.com) was not fetched, so nothing else about the property is stated here."},{"name":"Candlewood Suites Dickinson","source":"https://hotelguides.com/north-dakota/dickinson-nd-hotels.html","accessed":"2026-10-03","si":["family","senior","motoring"],"booking_route":"ihg.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":42,"blurb":"Listed by HotelGuides at \"1430 Sims Street, Dickinson, ND 58601\" among Dickinson, ND hotels; the NPS puts Dickinson 35 miles from the South Unit. The brand''s own page (ihg.com) was not fetched, so nothing else about the property is stated here."},{"name":"Little Mo Nature Trail","source":"https://www.nps.gov/thro/planyourvisit/accessibility.htm","accessed":"2026-10-02","si":["senior","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":43,"blurb":"North Unit river-bottom loop, 0.7 miles paved or 1.1 miles unpaved, 30-45 minutes; one of the NPS''s hard-surfaced accessible trails"},{"name":"Lone Tree Loop and the creek loops","source":"https://www.nps.gov/thro/planyourvisit/hiking-and-trail-information.htm","accessed":"2026-10-02","si":["hiking","expedition"],"booking_route":"free backcountry permit for overnight","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":44,"blurb":"South Unit day-long loops: Lone Tree, 9.6 miles with \"Difficult stream crossings\"; Jones/Lower Talkington/Lower Paddock, 11.4 miles; Upper Paddock/Talkington, 15.4-19.4 miles with Painted Canyon access"},{"name":"Ridgeline and Coal Vein trails","source":"https://www.nps.gov/thro/planyourvisit/hiking-and-trail-information.htm","accessed":"2026-10-02","si":["hiking","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":45,"blurb":"South Unit short hikes: Ridgeline, 0.6 miles with stairs and a badlands focus; Coal Vein, 0.6-0.8 miles, a geology trail \"featuring historic coal vein\""},{"name":"North Unit longhorn demonstration herd","source":"https://www.nps.gov/thro/planyourvisit/wildlife-viewing.htm","accessed":"2026-10-02","si":["culture","wildlife","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":46,"blurb":"\"A small demonstration herd is kept in the North Unit as a cultural resource. They may be spotted around mile marker two of the scenic drive\""},{"name":"Dakota Nights Astronomy Festival","source":"https://home.nps.gov/thro/learn/nature/dakota-nights-festival.htm","accessed":"2026-10-02","si":["family","culture","wellness"],"booking_route":"none observed; fee not stated","commission_status":"unknown","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":47,"blurb":"2026 dates were August 14-15 at the South Unit Visitor Center lawn and Peaceful Valley Ranch: solar scopes, stomp rockets, a Night Explorer Junior Ranger and telescope stargazing 8:45-11:30 pm"},{"name":"Point to Point Park, Medora","source":"https://medora.com/pointtopoint/","accessed":"2026-10-02","si":["family"],"booking_route":"medora.com general ticketing","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":48,"blurb":"\"mini golf, perception illusion house, zipline adventures and a lazy river pool modeled after the Little Missouri\"; paid attractions weekends 11 am-7 pm; packages $27.95-$58.95; trails, pickleball and the wooden children''s park free"},{"name":"Medora fall shows and Medora Musical Christmas","source":"https://medora.com/","accessed":"2026-10-02","si":["culture","senior","group"],"booking_route":"etix.com / medora.com/book","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":49,"blurb":"The Everly Brothers Experience (October 7-18) and Figuring It Out (October 21-November 1, 2026) at the Old Town Hall Theater; Beer and Bacon Festival October 3; Medora Musical Christmas at Burning Hills, December 3-20"},{"name":"Salt + Scoria Restaurant, TR Presidential Library","source":"https://www.trlibrary.com/visit/hours","accessed":"2026-10-02","si":["culinary","culture","senior"],"booking_route":"not observed","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":50,"blurb":"the library''s restaurant, \"offering full and lite service menus depending on season\""},{"name":"Badlands Pizza, Medora","source":"https://medora.com/badlandspizza/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"walk-in; carry-out (701) 623-4481","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":51,"blurb":"\"The perfect grub spot for families!\" - specialty pizzas such as the Cowboy Combo, \"Vegan & gluten-free options\", draft beer and live music Thursday-Saturday; seasonal, June 3 to September 19 in 2026, so closed on this build date"},{"name":"Medora Fudge & Ice Cream Depot","source":"https://medora.com/listing/fudge-depot/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":52,"blurb":"\"homemade fudge and ice cream\" with a shaded patio; open May 30 to September 12 and \"Closed Sept 13 - May 29\""},{"name":"Wannagan Creek Cabins, north of Medora","source":"https://www.wannagancreekcabins.com/","accessed":"2026-10-02","si":["glamping","family","romance"],"booking_route":"phone only - Dale, 701.290.7199","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":53,"blurb":"four cabins - \"stay right next to Theodore Roosevelt National Park\" - \"just minutes off Interstate 94\" with a \"two night minimum\"; bath linens supplied, bring your own bedding; no pets"},{"name":"Watford City hotels for the North Unit","source":"https://www.visitwatfordcity.com/","accessed":"2026-10-02","si":["group","family"],"booking_route":"not observed (individual sites not fetched)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":54,"blurb":"the Watford City visitor site lists The Watford, Little Missouri Inn & Suites, Roosevelt Inn & Suites, Teddy''s Residential Suites and Comfort Inn & Suites; the NPS puts Watford City 15 miles from the North Unit"},{"name":"Watford City Basin RV Resort","source":"https://www.campspot.com/park/watford-city-basin-rv-resort","accessed":"2026-10-03","si":["motoring","family","group"],"booking_route":"Campspot","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":55,"blurb":"\"304 16th Ave SW, Watford City\", the North Unit''s gateway town: a 57-acre park billing itself \"the largest full-service RV destination in western North Dakota\" with \"784 full hook-up sites with 50/30/20-amp service\" (the booking panel shows 341 RV sites and 64 cabins), clubhouse, showers and laundry"},{"name":"Stonehome Brewing Company, Watford City","source":"https://www.stonehomebrewing.com/","accessed":"2026-10-02","si":["culinary","group"],"booking_route":"walk-in; events and catering via its site","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":56,"blurb":"\"Real. AuthenTic. Craft.\" - brewery with food at 313 Fox Hills Parkway, Watford City, the North Unit''s gateway town; open daily from 9 or 11 am"},{"name":"Dickinson museum campus","source":"https://visitdickinson.com/p/meetings/itineraries/1-Day-Itinerary","accessed":"2026-10-02","si":["family","culture"],"booking_route":"not observed","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":57,"blurb":"per the Dickinson visitor bureau, the Badlands Dinosaur Museum \"Houses thousands of rock, mineral and fossil specimens including a complete real Triceratops skeleton\", beside the Joachim Regional Museum and the Pioneer Machinery Hall"},{"name":"Theodore Roosevelt Center, Dickinson State University","source":"https://www.theodorerooseveltcenter.org/","accessed":"2026-10-02","si":["culture","senior"],"booking_route":"walk-in, free","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":58,"blurb":"\"a rotating exhibit gallery, research library, reading room, and workspaces\" on the DSU hilltop campus, \"open to the public free of charge year-round (with seasonal hours)\"; home of the TR Digital Library"},{"name":"Dickinson dining: BrickHouse Grille, JD''s BBQ, Phat Fish Brewing","source":"https://visitdickinson.com/p/meetings/itineraries/1-Day-Itinerary","accessed":"2026-10-02","si":["culinary","group","family"],"booking_route":"not observed","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":59,"blurb":"the three restaurants the Dickinson visitor bureau names in its one-day itinerary (their own sites returned 403 this session)"}],"faq":[{"q":"How much is Theodore Roosevelt National Park?","a":"The NPS lists $30 for a private vehicle, $25 for a motorcycle and $15 per person on foot or bicycle (16 and over), each valid for 7 days. A Theodore Roosevelt annual pass is $55, and America the Beautiful passes are accepted.","source":"https://www.nps.gov/thro/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"Is Theodore Roosevelt National Park open?","a":"The NPS says the park is \"open 24 hours a day, year-round\", and the full South Unit Scenic Loop Drive reopened on November 25, 2025, after a section had been closed since 2019. \"Portions of the South Unit Scenic Loop Drive and North Unit Scenic Road may be closed in winter due to snow and ice.\"","source":"https://www.nps.gov/thro/planyourvisit/hours.htm","accessed":"2026-10-02"},{"q":"What time zone is Theodore Roosevelt National Park in?","a":"Two: \"The North Unit operates on Central time, while the South Unit operates on Mountain time.\"","source":"https://www.nps.gov/thro/planyourvisit/hours.htm","accessed":"2026-10-02"},{"q":"Can you stay in Theodore Roosevelt National Park?","a":"Only by camping. The NPS states: \"No lodging is available inside Theodore Roosevelt National Park.\" South Unit lodging is in Medora and in Beach (25 miles), Belfield (15 miles) and Dickinson (35 miles); North Unit lodging is in Watford City (15 miles), Alexander (35 miles) and Killdeer (45 miles).","source":"https://www.nps.gov/thro/planyourvisit/lodging.htm","accessed":"2026-10-02"},{"q":"Can you camp in Theodore Roosevelt National Park?","a":"Yes. Cottonwood (South Unit) and Juniper (North Unit) are primitive campgrounds with \"no hookups or showers\", plus Roundup Group Horse Camp, all reserved on recreation.gov. Backcountry camping needs \"a free Backcountry Permit in the North or South Unit Visitor Centers\".","source":"https://www.nps.gov/thro/planyourvisit/camping.htm","accessed":"2026-10-02"},{"q":"Do you need reservations for Theodore Roosevelt National Park?","a":"Not to enter - one of the entrance passes is required. For Cottonwood Campground the NPS states: \"Beginning May 1, 2026 all sites are by reservation at recreation.gov\".","source":"https://www.nps.gov/thro/planyourvisit/cottonwood-campground.htm","accessed":"2026-10-02"},{"q":"Where can you see bison in Theodore Roosevelt National Park?","a":"Bison \"roam throughout the North and South units of the park, and most visitors see them as they drive the park roads.\" The NPS warns: \"They generally appear tranquil, but may attack without warning if they are disturbed.\"","source":"https://www.nps.gov/thro/planyourvisit/wildlife-viewing.htm","accessed":"2026-10-02"},{"q":"Where can you see horses in Theodore Roosevelt National Park?","a":"The NPS says the horses live in the South Unit only and \"are often visible from the Scenic Loop Drive and from I-94\"; it names the Talkington trailhead area off Exit 36, Painted Canyon, Buck Hill and Wind Canyon.","source":"https://www.nps.gov/thro/learn/nature/horses.htm","accessed":"2026-10-02"},{"q":"Is the Theodore Roosevelt Presidential Library open?","a":"The library in Medora is \"open now\", with a museum, store and the Salt + Scoria restaurant; fall hours run September 14 to November 30, Tuesday-Friday 9-4 and Saturday-Sunday 9-6, with \"Last timed entry\" 90 minutes before closing.","source":"https://www.trlibrary.com/visit/hours","accessed":"2026-10-02"}],"seo":{"meta_title":"Theodore Roosevelt National Park: Badlands, Bison & Medora | TravelWell","meta_description":"North Dakota''s Badlands park in three units: the reopened South Unit loop, bison and wild horses, Roosevelt''s cabin, fees, and where to stay and eat in Medora.","slug":"theodore-roosevelt-national-park-north-dakota","primary_keyword":"Theodore Roosevelt National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Theodore Roosevelt National Park, North Dakota"}}'::jsonb, 59),
  ('wind-cave-south-dakota', '12A', 'Wind Cave National Park', 'United States', 'Boxwork cave beneath a bison prairie', 'future', 'verified', 'mountainValley', 'The Great Plains & Dakotas', '{"adventure","wildlife","hiking","family","glamping","parks"}', '{"wild","rugged","serene","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Natural Entrance Tour","source":"https://www.nps.gov/wica/planyourvisit/guidedtours.htm","accessed":"2026-10-03","si":["adventure","family","culture"],"booking_route":"Recreation.gov (120 days to 2 days ahead) or same-day tickets at the visitor center; \"Roughly half of all tour tickets are held in reserve for same-day sales\"","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":1,"blurb":"1 hour 15 minutes, 2/3 mile, 300 stairs, MODERATE: \"This tour includes a visit to the natural entrance of Wind Cave where visitors can see the largest opening to the cave and learn how we get our name\"; \"Wind Cave''s famous boxwork is abundant throughout this trip\"; exits by elevator. \"This is a great tour for families.\" Adults $16, ages 62+ and 6-15 $8, 5 and under free."},{"name":"Wind Cave boxwork","source":"https://www.nps.gov/wica/learn/nature/speleothems-boxwork.htm","accessed":"2026-10-03","si":["adventure","culture","family"],"booking_route":"seen only on a ranger-guided cave tour (\"All access is by a ranger guided tour\")","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"Boxwork is found in small amounts in other caves, but perhaps in no other cave in the world is boxwork so well-formed and abundant as in Wind Cave. Boxwork is made of thin blades of calcite that project from cave walls and ceilings, forming a honeycomb pattern.\" The park calls Wind Cave \"one of the longest and most complex caves in the world.\""},{"name":"Garden of Eden Tour","source":"https://www.nps.gov/wica/planyourvisit/guidedtours.htm","accessed":"2026-10-03","si":["family","senior","adventure"],"booking_route":"Recreation.gov (120 days to 2 days ahead) or same-day at the visitor center","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":3,"blurb":"1 hour, 1/4 mile, 150 stairs: \"This one-hour tour is our least strenuous tour. It is a wonderful sample of Wind Cave. Small amounts of all of the beautiful cave formations - boxwork, cave popcorn, and flowstone - are seen\"; enters and leaves by elevator. Adults $14, ages 62+ and 6-15 $7. Runs year-round (10:00 am and 3:00 pm, November 1, 2026 to April 24, 2027)."},{"name":"Bison herd on the Wind Cave prairie","source":"https://www.nps.gov/wica/faqs.htm","accessed":"2026-10-03","si":["wildlife","motoring","family"],"booking_route":"none needed - free roadside viewing","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"There are 400-450 bison in Wind Cave National Park\"; good places to see them are \"along U.S. 385, S.D. 87, and primitive roads N.P.S. 5 & 6.\" The herd descends from 14 bison sent by the American Bison Society from the New York Zoological Gardens in 1913 and six from Yellowstone in 1916. Visitors must stay at least 25 yards away; \"Bison are more aggressive during the calving and mating season from May through August.\""},{"name":"Fairgrounds Tour","source":"https://www.nps.gov/wica/planyourvisit/guidedtours.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"Recreation.gov (120 days to 2 days ahead) or same-day at the visitor center","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":5,"blurb":"1 hour 30 minutes, 2/3 mile, 450 stairs, STRENUOUS: \"explores both the upper and middle levels of Wind Cave\" - boxwork in the middle level, popcorn and frostwork in the upper; \"This is our most strenuous walking tour\", with \"one flight of 89 steps going up.\" Adults $16, ages 62+ and 6-15 $8."},{"name":"Wild Cave Tour","source":"https://www.nps.gov/wica/planyourvisit/guidedtours.htm","accessed":"2026-10-03","si":["adventure","sports"],"booking_route":"phone only, 605-745-4600, up to one month ahead during visitor center hours","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":6,"blurb":"Summer only, up to 4 hours, VERY STRENUOUS: \"an introduction to safe caving in an undeveloped part of the cave\"; \"Most of the tour is spent crawling on your hands and knees\"; visitors \"will need to fit through a space that is 10 inches tall and 3 feet wide\". Limited to 6 people, minimum age 16; $45. The park provides helmets, lights, gloves, elbowpads and kneepads."},{"name":"Candlelight Tour","source":"https://www.nps.gov/wica/planyourvisit/guidedtours.htm","accessed":"2026-10-03","si":["adventure","culture","romance"],"booking_route":"phone only, 605-745-4600, up to one month ahead during visitor center hours","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":7,"blurb":"Summer only, 2 hours, 2/3 mile, 424 stairs, STRENUOUS: \"Experience the cave by candlelight the way the earliest explorers of Wind Cave saw it!\" in \"a less developed, unlit section of the cave\"; each participant carries a candle bucket. Limited to 10 people, minimum age 8; $16."},{"name":"Wind Cave Visitor Center","source":"https://www.nps.gov/wica/planyourvisit/placestogo.htm","accessed":"2026-10-03","si":["family","senior","culture"],"booking_route":"none needed - free; 26611 US Highway 385, Hot Springs, SD 57747; 605 745-4600","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"\"opened daily all year except Thanksgiving, Christmas, and New Year''s Day\", 8:00 am - 4:30 pm with expanded summer hours; \"All cave tours leave from the visitor center.\" Exhibit rooms on bison and the cave, the park film One Park, Two Worlds, and a park store run by the Black Hills Parks and Forests Association. \"Do not use your GPS to find the visitor center - you will get lost.\""},{"name":"Elk Mountain Campground","source":"https://www.nps.gov/wica/planyourvisit/campgrounds.htm","accessed":"2026-10-03","si":["hiking","family","motoring"],"booking_route":"Recreation.gov (reservations late May-September; first-come, first-served through Recreation.gov otherwise)","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":9,"blurb":"\"straddles the edge of a ponderosa pine forest and open prairie\"; 75 sites, \"but rarely fills to capacity\"; maximum site length 36 feet. \"$24.00 per site per night regularly, and $12.00 per site per night when the water is turned off (generally October through May)\"; Senior and Access Pass holders pay half. Open year-round; reservable late May through September. Accessible sites B2 and D3."},{"name":"Natural Entrance of Wind Cave","source":"https://www.nps.gov/wica/planyourvisit/accessibility.htm","accessed":"2026-10-03","si":["culture","pilgrimage","senior"],"booking_route":"none needed - free walk from the visitor center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"The cave''s natural opening, \"a deeply spiritual place to many people\"; in Lakota oral tradition Wind Cave (Oniya Oshoka) is where \"not only were the first humans born from the cave, but the first bison came from the cave as well.\" Wheelchair users can reach it \"via a ramp and sidewalk from the visitor center\"."},{"name":"Accessibility Tour","source":"https://www.nps.gov/wica/planyourvisit/guidedtours.htm","accessed":"2026-10-03","si":["senior","family"],"booking_route":"phone 605-745-4600 the day of or up to three days ahead, or ask at the information desk","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":11,"blurb":"30 minutes, 100 feet, 0 stairs, EASY: \"Limited areas of the cave are accessible to wheelchairs and those with limited mobility\"; rides the elevator in and out, from a building \"about 200 yards south of the visitor center\" with accessible parking. Adults $6, 62+ and 6-15 $3. Sign-language interpreters with two weeks'' notice."},{"name":"Kit for the cave tour","source":"https://www.nps.gov/wica/planyourvisit/guidedtours.htm","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"affiliate retail referral (REI.com via AvantLink; Amazon Associates) - nothing is sold by the park","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":12,"blurb":"The park''s own list: \"Long sleeves or jackets. The cave temperature is a constant 54°F (12°C).\" \"Comfortable shoes with non-slip soles. Sandals are not recommended\"; the Candlelight and Wild Cave tours require \"Sturdy, lace-up hiking boots or shoes (designed for trail) with aggressive tread\". Bags, food, water and walking sticks are not allowed in the cave."},{"name":"Kit for the prairie trails","source":"https://www.nps.gov/wica/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"affiliate retail referral (REI.com via AvantLink; Amazon Associates) - topographic maps are sold at the visitor center bookstore","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":13,"blurb":"\"Carry and drink plenty of water. There are few water sources and all water in the backcountry must be boiled, filtered, or treated.\" \"Wear fully enclosed footwear and long pants as poison ivy and ticks may be encountered anywhere in the park. It''s also recommended to bring a wide brimmed hat, sunscreen, and bug spray.\" \"Bring a park map\" and extra layers - summer storms bring \"large hail\"."},{"name":"Rankin Ridge Nature Trail","source":"https://www.nps.gov/wica/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"1 mile round trip, EASY loop: \"Gain spectacular views from the highest point in the park\"; the fire tower is closed, but \"on a clear day, you may be able to see as far as the Badlands from the trail''s eastern edge.\" RVs and trailers are not permitted at the trailhead."},{"name":"Prairie Vista Trail","source":"https://www.nps.gov/wica/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":15,"blurb":"About 1 mile round trip, EASY: \"Stroll the prairie grasslands from the visitor center. Waysides provide information along the way.\" One of the park''s two pet-friendly trails."},{"name":"Elk Mountain Trail and elk bugling","source":"https://www.nps.gov/wica/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["wildlife","hiking","family"],"booking_route":"none needed - free trail and free ranger program","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":16,"blurb":"1 mile round trip, EASY, around the campground: \"During September and October, elk may be heard bugling at dawn and dusk.\" A free ranger Elk Bugling Program runs \"from mid- to late-September\" from the campground amphitheater, then caravans to listen for elk."},{"name":"Prairie dog town on Bison Flats","source":"https://www.nps.gov/wica/faqs.htm","accessed":"2026-10-03","si":["wildlife","family"],"booking_route":"none needed - free roadside viewing","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":17,"blurb":"\"The prairie dog town nearest the visitor center is on Bison Flats, at the south junction of the visitor center road and U.S. 385, about ½ mile (0.8 km) south of the visitor center.\" An interpretive exhibit sits at the junction of U.S. 385 and S.D. 87. \"Do not feed prairie dogs or other wildlife.\""},{"name":"Wind Cave Canyon Trail","source":"https://www.nps.gov/wica/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","wildlife"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":18,"blurb":"1.8 miles one way, EASY: \"This former road follows Wind Cave Canyon to the park boundary. Limestone cliffs provide nesting areas for cliff swallows, canyon wrens, and great horned owls.\" Look for Red-headed and Lewis'' woodpeckers."},{"name":"Centennial Trail (Wind Cave section)","source":"https://www.nps.gov/wica/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":19,"blurb":"6 miles one way, STRENUOUS: \"the southernmost part of a 111-mile trail through the Black Hills, ending at Bear Butte State Park\"; it crosses prairies and ponderosa forest along Beaver Creek. \"Shuttles are available in the Black Hills for through-hikers\"; overnight parking needs a camping permit."},{"name":"Highland Creek Trail","source":"https://www.nps.gov/wica/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","wildlife","adventure"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":20,"blurb":"8.6 miles one way, STRENUOUS: \"the longest and most diverse trail in the park, crossing mixed-grass prairies, ponderosa pine forests, and riparian habitats of Highland Creek, Beaver Creek, and Wind Cave Canyon.\""},{"name":"Boland Ridge Trail","source":"https://www.nps.gov/wica/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","wildlife"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":21,"blurb":"2.6 miles one way, STRENUOUS: \"A series of climbs offer panoramic views of the Black Hills, Red Valley, and the plains beyond. Elk are often seen from this trail in the morning and evening.\" Trailhead on NPS 6."},{"name":"Cold Brook Canyon Trail","source":"https://www.nps.gov/wica/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","wildlife"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":22,"blurb":"1.4 miles, MODERATE: \"a ponderosa forest gives way to the open prairie and crosses a prairie dog town, a good place to see prairie falcons and other raptors.\" Trailhead about 1 mile south of the visitor center on US 385."},{"name":"Backcountry camping and the open-hike policy","source":"https://www.nps.gov/wica/planyourvisit/permitsandreservations.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"free permit at the visitor center information desk","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":23,"blurb":"\"Backcountry camping is allowed in the northern part of the park. A free permit is required\", obtained at the visitor center information desk. \"Wind Cave National Park is an open hike park meaning visitors are welcome to hike off designated trails\" - bring plenty of water and a map; \"cell service within the park is very limited.\""},{"name":"Horseback riding by permit","source":"https://www.nps.gov/wica/planyourvisit/permitsandreservations.htm","accessed":"2026-10-03","si":["adventure","wildlife"],"booking_route":"free day-use permit at the visitor center (bring your own horse)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":24,"blurb":"\"Horses are permitted throughout Wind Cave National park\" with a day-use permit from the visitor center; riding is prohibited \"near water sources, directly on any maintained hiking trail, on park roadways, and in the campground and picnic areas\", and hay must be certified weed free."},{"name":"Custer State Park","source":"https://gfp.sd.gov/parks/detail/custer-state-park/","accessed":"2026-10-03","si":["wildlife","hiking","family","group"],"booking_route":"reservations.gooutdoorssouthdakota.com or 1.800.710.2267","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":25,"blurb":"Borders Wind Cave to the north: \"Encompassing 71,000 acres in the Black Hills, Custer State Park is home to abundant wildlife and adventure\"; \"9 campgrounds including camper cabins, tent campsites, RV campsites with electricity, and horse camp\" (Blue Bell, Center Lake, Game Lodge, Grace Coolidge, Legion Lake, Stockade Lake North and South, Sylvan Lake among them). Entrance $25 per vehicle for 1-7 days. Stay at least 100 yards from bison."},{"name":"Wildlife Loop State Scenic Byway","source":"https://www.custerresorts.com/activities/scenic-drives/wildlife-loop","accessed":"2026-10-03","si":["wildlife","motoring","family"],"booking_route":"self-drive with a state park entrance license","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":26,"blurb":"\"Travel through 18 miles of open grasslands and pine-speckled hills that much of Custer State Park''s wildlife calls home\" - bison, pronghorn, deer, elk, coyotes, burros and prairie dogs; allow \"between 1.5 and 2 hours to complete the loop\". Open year-round with a South Dakota State Park Entrance License."},{"name":"Buffalo Safari Jeep Tour","source":"https://www.custerresorts.com/activities/activities-experiences/buffalo-safari-jeep-tour","accessed":"2026-10-03","si":["wildlife","family","safari"],"booking_route":"own website booking (Custer State Park Resort)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":27,"blurb":"Open-air Jeeps \"off-road to the private, interior dirt roads of the Park\" in search of \"pronghorns, elk, and the noble buffalo\"; 1 1/2 to 2 hours, \"Daily departures from 6am to 6pm during Prime Season\", limited winter departures November through April; departs Creekside Lodge at the State Game Lodge. \"Steps required, assistance available.\""},{"name":"Buffalo Roundup","source":"https://www.custerresorts.com/activities/buffalo-roundup","accessed":"2026-10-03","si":["wildlife","spectator","culture"],"booking_route":"none needed - public viewing areas on the Wildlife Loop (park entrance license applies)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":28,"blurb":"\"As the hooves of more than 1,300 American buffalo thunder through the valley\" riders drive the herd into corrals for sorting; the event \"attracts more than14,000 people each year.\" 2026 edition: roundup Friday September 25, 2026, from 9:30 a.m. MT (lots open 6:15 a.m.); Arts Festival September 24-26, 2026 at the State Game Lodge."},{"name":"State Game Lodge","source":"https://www.custerresorts.com/lodging/lodge-rooms","accessed":"2026-10-03","si":["culture","romance","wildlife"],"booking_route":"own website booking engine (custerresorts.com) or reservations office","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":29,"blurb":"One of four historic lodges of Custer State Park Resort: \"Welcome to the regal State Game Lodge, home to historic lodge rooms\"; its rooms \"have seen a full interior renovation for 2025\". The dining room serves breakfast, lunch and dinner, \"Open seasonally from the end of April through mid-October\"; reservations 605-255-4541. The resort has \"228 fully-modernized sleeping accommodations\" and is \"operated by South Dakota based concessionaire The Ramkota Companies since the contract was awarded in 2007.\""},{"name":"Under Canvas Mount Rushmore","source":"https://www.undercanvas.com/camps/mount-rushmore/","accessed":"2026-10-03","si":["glamping","romance","family"],"booking_route":"own website booking (undercanvas.com) - book direct, not via Hyatt (ledger note)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":30,"blurb":"\"tucked among ponderosa pines and juniper on an original gold mining settlement less than four miles from Mount Rushmore National Monument\"; Deluxe, Stargazer (\"viewing window above the king-size bed\"), Suite, Safari and family tents with wood-burning stoves; dogs welcome for a nightly fee. 2027 dates: April 29 - September 27. The NPS puts Mount Rushmore 41 miles from the Wind Cave visitor center."},{"name":"Allen Ranch","source":"https://www.hotsprings-sd.com/member-directory/allen-ranch/","accessed":"2026-10-03","si":["glamping","family","motoring"],"booking_route":"phone 605-745-1890 (no online booking route on the listing read)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":31,"blurb":"Hot Springs: \"RV sites with electricity, water and a dump station nearby, scenic tent sites next to the river. Tipi and Glamping packages with a full Cowboy Breakfast options are available\"; modern shower building; glamping and tipi check-in 3:00 pm. 13065 Fall River Rd; 605-745-1890."},{"name":"Hot Springs SD / Black Hills KOA Holiday","source":"https://koa.com/campgrounds/hot-springs/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"own online reservations (koa.com)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":32,"blurb":"Off SD Hwy 79 near Hot Springs: \"Pull-thru RV sites (up to 80 feet)\" with full hookups and a KOA Patio, Deluxe Cabins with full baths, camping cabins and tent sites, a heated pool (Memorial Day - Labor Day) and a fenced dog park. Season April 1 - October 31, 2026; hosts Thad and Nicole Weiss."},{"name":"Fall River Ranch RV Resort","source":"https://www.hotsprings-sd.com/member-directory/fall-river-ranch-rv-resort/","accessed":"2026-10-03","si":["motoring"],"booking_route":"phone (605) 745-3080","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":33,"blurb":"Hot Springs: opened July 1, 2021 with 31 sites; \"The finished sites have full hook-ups available (sewer, water, electric, picnic tables, fire rings)\"; 30 and 50 amp, \"Big Rig Friendly\"; \"Your Black Hills RV Base Camp!\" (605) 745-3080."},{"name":"Sunrise Ridge Campground","source":"https://www.hotsprings-sd.com/member-directory/sunrise-ridge-campground-storage/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"phone 605-745-4397","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":34,"blurb":"27288 Wind Cave Rd., Hot Springs: \"Located just north of Hot Springs, we are minutes from Wind Cave National Park and The Mammoth Site\"; 70 acres; \"Whether you have a 45 foot motorhome, tent or anything in between, our newly renovated sites\". 605-745-4397."},{"name":"Hidden Lake Campground and Resort","source":"https://www.hotsprings-sd.com/member-directory/hidden-lake-campground-and-resort/","accessed":"2026-10-03","si":["family","adventure"],"booking_route":"phone 605-745-4042","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":35,"blurb":"27291 Evans Street, Hot Springs: \"23 campsites, 20 cabins, a shower house with laundry facility, store and a private lake for swimming, canoeing, kayaking, fishing\". 605-745-4042."},{"name":"Holiday Inn & Suites, Custer","source":"https://visitcuster.com/stay","accessed":"2026-10-03","si":["family","senior"],"booking_route":"ihg.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":36,"blurb":"Listed by Visit Custer (the Custer tourism improvement district) at \"433 West Mt Rushmore Rd, Custer, SD 57730\". The NPS puts Custer 20 miles north of the Wind Cave visitor center on U.S. 385. IHG''s own page refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"Alex Johnson Hotel, Curio Collection by Hilton","source":"https://www.alexjohnson.com/","accessed":"2026-10-03","si":["culture","romance","senior"],"booking_route":"own website / hilton.com","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":37,"blurb":"523 Sixth St., Rapid City: \"Since opening its doors on July 1, 1928, the hotel has played host to several presidents, countless celebrities, and a few spirits of its own\"; Juniper at Vertex Sky Bar on the roof. 605-342-1210. At the ring''s edge: the NPS gives 56 miles (about 65 minutes) as the fastest drive from the visitor center to Rapid City."},{"name":"South Dakota Outdoor Shop","source":"https://trailaddict.com/business/south-dakota-outdoor-shop/","accessed":"2026-10-03","si":["hiking","adventure","sports"],"booking_route":"walk-in shop, (605) 673-2240","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","shop"],"draw_rank":38,"blurb":"Custer: \"a laid-back, community-minded gear shop\" that \"began in 2019 as a small bike and climbing store\" and \"has grown into a full-service outdoor and lifestyle shop stocked with high-quality gear, apparel, footwear, and accessories for hiking, climbing, camping, and everyday life\"; visitors'' reviews on its own site mention e-bike rentals for the Mickelson Trail. (605) 673-2240."},{"name":"Black Hills Power Bikes","source":"https://www.blackhillspowerbikes.com/","accessed":"2026-10-03","si":["sports","adventure","family"],"booking_route":"own website","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","activities"],"draw_rank":39,"blurb":"Custer, \"located right off the Mickelson Trail\": Vtuvia electric power bikes and Trek Verve 1 pedal bikes, \"3 hour rentals, and all day rental options\". The trail runs 109 miles from Edgemont to Deadwood on the old Burlington Northern line, with 15 trailheads."},{"name":"The Mammoth Site","source":"https://www.hotsprings-sd.com/member-directory/the-mammoth-site/","accessed":"2026-10-03","si":["family","culture","senior"],"booking_route":"admission at the site (ticketing not read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":40,"blurb":"Hot Springs: \"The Mammoth Site boasts the largest concentration of Columbian mammoths in the world. Tour this ancient sinkhole and stand on the edge of discovery\" - an indoor active dig with Ice Age exhibits, \"universally accessible walkways\", and one of four accredited museums in South Dakota. (605) 745-6017."},{"name":"Evans Plunge Mineral Springs","source":"https://evansplunge.com/","accessed":"2026-10-03","si":["wellness","family"],"booking_route":"admission and punch cards at the door","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":41,"blurb":"\"Established in 1890, evans plunge is the oldest tourist attraction in the Black Hills\"; \"Natural spring-fed waters maintain an average POOL TEMPERATURE of 87 degrees fahrenheit\" with \"5,000 gallons of water per minute\" from a thermal spring. Owned by the City of Hot Springs; 1145 North River Street; 605-745-5165."},{"name":"Hot Springs","source":"https://www.hotsprings-sd.com/","accessed":"2026-10-03","si":["culture","wellness","senior"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":42,"blurb":"The gateway town 11 miles south of the visitor center (NPS): \"Called Minnekahta (warm waters) by the original white settlers in 1879, the town''s name was changed to Hot Springs in 1886. Earlier, the Lakota and the Cheyenne Indian tribes fought for control of the natural warm waters.\" Chamber at 801 S. 6th Street, 605-745-4140."},{"name":"Custer","source":"https://visitcuster.com/","accessed":"2026-10-03","si":["culture","family"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":43,"blurb":"The northern gateway, 20 miles from the visitor center (NPS): \"Stay in Custer to savor every minute on your Black Hills vacation. Here, you''re closer to South Dakota''s biggest attractions - Mount Rushmore National Memorial, Custer State Park and Wind Cave National Park.\" Chamber at 615 Washington Street, 605-673-2244."},{"name":"Skogen Kitchen","source":"https://skogenkitchen.com/","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"reservations@skogenkitchen.com","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":44,"blurb":"Custer: \"a chef driven concept, offering innovative dinner options. Owners Joseph Raney (Chef) and Eliza Raney (GM) moved to South Dakota from Southern California\" to \"bring flavors from around the world to Custer\". Dinner Tuesday - Saturday."},{"name":"Whiskey River - Cuisine, Cocktails & Tap Room","source":"https://www.hotsprings-sd.com/member-directory/whiskey-river-cuisine-cocktails-tap-room/","accessed":"2026-10-03","si":["culinary","wine"],"booking_route":"walk-in / phone (605) 745-2739","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":45,"blurb":"Hot Springs: \"a unique taproom experience\" with \"local craft beer and wine selections from South Dakota breweries and wineries\" and \"Audubon Certified Pastures by Evergreen Ranch meats\"; breakfast, lunch and dinner. (605) 745-2739."},{"name":"The Kitchen Ink","source":"https://www.hotsprings-sd.com/member-directory/the-kitchen-ink/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in / phone (605) 515-1440","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":46,"blurb":"741 Jennings Ave, Hot Springs: \"Handcrafted dining, specialty drinks, and scratch desserts\"; \"Seasonally fresh, locally sourced food alchemy. Family Oriented down home dining!\" Mon-Sat 7:30am - 7:30pm, Sun 9:00am - 3pm. (605) 515-1440."},{"name":"The 309 General Bar & Restaurant","source":"https://www.hotsprings-sd.com/member-directory/the-309-general-bar-restaurant/","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in / phone (605) 891-4787","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":47,"blurb":"309 N River St, Hot Springs: \"rustic Wild West atmosphere\" with \"handmade burgers and unique specialties like chislics and onion rings\", gluten-free options and live music; summer hours Wed - Sat 12:00pm - 12:00am. (605) 891-4787."},{"name":"Two Cows Creamery & Bistro","source":"https://www.hotsprings-sd.com/member-directory/two-cows-creamery/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in; pickup and curbside (605) 745-3838","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":48,"blurb":"Hot Springs: \"Every ice cream flavor we sell is hand-crafted and made in-house with milk and cream from our very own dairy cows\"; \"28 flavors\", handmade waffle cones and a build-your-own burger with hand-cut fries. (605) 745-3838."},{"name":"Southern Hills Diner & Bakery","source":"https://www.hotsprings-sd.com/member-directory/southern-hills-diner-bakery/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in / phone 605-745-7203","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":49,"blurb":"12572 Sheps Canyon Road, \"6 miles south of Hot Springs on the way to Cascade Falls. Farm to table experience\"; a full-service diner and bakery with a pastry chef; Thurs - Mon 8:00am - 2:00pm. 605-745-7203."},{"name":"Ruby House Restaurant","source":"https://www.hotsprings-sd.com/member-directory/ruby-house-restaurant-keystone/","accessed":"2026-10-03","si":["culinary","culture","family"],"booking_route":"walk-in / phone 605-666-4404","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":50,"blurb":"124 Winter St, Keystone: \"Step back in time & relax in our 1900''s style dining room\" - prime rib, steaks, seafood, buffalo steaks and ribs, full bar; open April - October. 605-666-4404."},{"name":"State Game Lodge dining room","source":"https://www.custerresorts.com/dining","accessed":"2026-10-03","si":["culinary","romance","culture"],"booking_route":"phone 605-255-4541","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":51,"blurb":"Custer State Park: \"casual yet elegant breakfast and lunch dining with a more formal ambiance for dinner\", open from the end of April through mid-October; reservations 605-255-4541. The resort runs four restaurants plus the Chuckwagon Cookout; Coolidge General Store is \"a leisurely 1/2 mile walk\" from the lodge."}],"faq":[{"q":"Is Wind Cave National Park free?","a":"Yes for the surface: \"An entrance pass is not required to access Wind Cave National Park.\" \"There are no fees to drive through or hike in the park. Fees are only charged for cave tours\" - from $6 (Accessibility Tour) to $45 (Wild Cave Tour) for adults.","source":"https://www.nps.gov/wica/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Do you need reservations for Wind Cave National Park?","a":"Not to enter, but for cave tours they are \"highly recommended as tours often sell out March through October and on holiday weekends throughout winter.\" Garden of Eden, Natural Entrance and Fairgrounds tickets are on Recreation.gov \"from 120 days until two days in advance\"; the Candlelight and Wild Cave tours are reserved by phone. \"Roughly half of all tour tickets are held in reserve for same-day sales.\"","source":"https://www.nps.gov/wica/planyourvisit/guidedtours.htm","accessed":"2026-10-03"},{"q":"Can you camp at Wind Cave National Park?","a":"Yes. \"The Elk Mountain Campground is open year-round and is the only campground in the park. Sites can be reserved at www.recreation.gov late May through September, and are first-come, first-served through www.recreation.gov at all other times.\" The fee is $24 a night, $12 when the water is turned off. Backcountry camping needs a free permit from the visitor center.","source":"https://www.nps.gov/wica/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03"},{"q":"Where can you see bison in Wind Cave National Park?","a":"\"There are 400-450 bison in Wind Cave National Park. They are grazers and usually found on the grasslands. There are several good places to see bison along U.S. 385, S.D. 87, and primitive roads N.P.S. 5 & 6.\" The NPS adds: \"Bison are large, fast, nimble, and very dangerous... Please observe them from a safe distance.\"","source":"https://www.nps.gov/wica/faqs.htm","accessed":"2026-10-03"},{"q":"How far is Wind Cave National Park from Mount Rushmore?","a":"\"The most direct route to Mount Rushmore National Memorial via U.S. Highway 385 and S.D. Highway 244... is 41 miles (66 km) and driving time is approximately one hour.\" The scenic route through Custer State Park and the Iron Mountain Road is \"almost 50 miles (80 km) and takes 1.5 to 2 hours\".","source":"https://www.nps.gov/wica/faqs.htm","accessed":"2026-10-03"},{"q":"How far is Wind Cave National Park from Rapid City?","a":"The fastest route, via the gravel 7-11 Road and S.D. 79, is \"56 miles (90 km) and takes about 65 minutes to drive.\" Avoiding the gravel road through Hot Springs is 68 miles, about 1 hour 15 minutes; the Black Hills route through Custer and Hill City is 59 miles, about 90 minutes.","source":"https://www.nps.gov/wica/faqs.htm","accessed":"2026-10-03"},{"q":"Can you bring dogs to Wind Cave National Park?","a":"Yes, within limits: on a leash no longer than six feet, in \"Grassy areas near the visitor center\", \"The Elk Mountain Campground\" and \"Both the Prairie Vista Trail and Elk Mountain Campground Trail.\" Pets are not allowed on cave tours, ranger programs, in public buildings, \"The backcountry or any trails except those listed above.\"","source":"https://www.nps.gov/wica/planyourvisit/pets.htm","accessed":"2026-10-03"},{"q":"Is Wind Cave National Park wheelchair accessible?","a":"Partly. \"Limited areas of the cave are accessible to wheelchairs and those with limited mobility\" on the half-hour Accessibility Tour, which uses the elevator. \"The visitor center is accessible to wheelchairs\", campsites B2 and D3 are accessible, and the natural entrance is reachable \"via a ramp and sidewalk from the visitor center\".","source":"https://www.nps.gov/wica/planyourvisit/accessibility.htm","accessed":"2026-10-03"},{"q":"What is the closest airport to Wind Cave National Park?","a":"\"Nearest commercial airport is in Rapid City, SD.\" The NPS adds that \"No public transportation serves the park.\"","source":"https://www.nps.gov/wica/planyourvisit/basicinfo.htm","accessed":"2026-10-03"},{"q":"Is Wind Cave National Park open year round?","a":"Yes: \"The park''s surface is open all day, every day for you to explore. However, snow and severe weather can limit access to some remote parts of the park, especially in winter.\" The visitor center is open daily all year except Thanksgiving, Christmas and New Year''s Day, and cave tours run through the winter.","source":"https://www.nps.gov/wica/planyourvisit/hours.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Wind Cave National Park: Cave Tours, Bison & Camping | TravelWell","meta_description":"Free entry, six ranger-led cave tours through rare boxwork, 400-450 bison on the prairie, Elk Mountain Campground, and stays around Hot Springs and Custer.","slug":"wind-cave-national-park-south-dakota","primary_keyword":"Wind Cave National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Wind Cave National Park bison prairie"}}'::jsonb, 60)
