insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('hot-springs-arkansas', '12A', 'Hot Springs National Park', 'United States', 'A national park you walk into from a city street, where the thermal water still runs into two working bathhouses and free jug fountains', 'future', 'verified', 'mountainValley', 'The Ozarks & Mid-South', '{"wellness","culture","hiking","glamping","family","parks"}', '{"historic","serene","refined"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Fordyce Bathhouse Visitor Center","source":"https://www.nps.gov/hosp/planyourvisit/fordyce-bathhouse.htm","accessed":"2026-10-02","si":["culture","senior","family"],"booking_route":"not applicable - free, no reservation (NPS)","tier_absent_reason":"not-sold","blurb":"the park visitor center at 369 Central Avenue: free self-guided tours over four floors - marble bath halls, a music room, a gymnasium with wooden equipment, the historic Fordyce Spring in the basement; in its working years (1915-1962) \"the only bathhouse to have a bowling alley\""},{"name":"Bathhouse Row and the Grand Promenade","source":"https://www.nps.gov/hosp/planyourvisit/accessibility.htm","accessed":"2026-10-02","si":["senior","culture","romance"],"booking_route":"not applicable - free, no reservation (NPS)","tier_absent_reason":"not-sold","blurb":"the row of historic bathhouses on Central Avenue, ringed by a paved four-to-five-foot walkway loop with benches; the Grand Promenade above it is fully paved with multiple access points"},{"name":"Buckstaff Bathhouse","source":"https://www.buckstaffbaths.com/","accessed":"2026-10-02","si":["wellness","senior","culture"],"booking_route":"walk-in - the site states no reservations are required for baths or massages; phone 501-623-2308","tier_absent_reason":"not-sold","blurb":"open since 1912 at 509 Central Avenue and \"the only facility on the Row that has never fully closed\"; the traditional sequence of whirlpool mineral bath, steam cabinet, sitz bath, hot towel packs and Swedish massage"},{"name":"Quapaw Baths & Spa","source":"http://quapawbaths.com/","accessed":"2026-10-02","si":["wellness","romance"],"booking_route":"online through its own website or by phone (booking engine not named on the page as fetched)","tier_absent_reason":"not-sold","blurb":"413 Central Avenue: public thermal pools (\"four large thermal pools ranging in temperature from 95-104 degrees\" per the city''s listing), private baths, a steam cave, massages and the Quapaw Cafe; packages from $150; no services for children under 14; open Wednesday-Monday 10am-6pm"},{"name":"Superior Bathhouse Brewery","source":"https://www.superiorbathhouse.com/","accessed":"2026-10-02","si":["culture","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"a bathhouse turned brewery at 329 Central Avenue, billed as \"the only brewery located in a National Park\" and brewing with thermal spring water; closed Tuesdays"},{"name":"Hotel Hale","source":"http://www.hotelhale.com/","accessed":"2026-10-02","si":["romance","wellness","culture"],"booking_route":"online reservation system on its own site (engine not named as fetched); phone 501-760-9010","tier_absent_reason":"not-sold","blurb":"nine suites in the 1892 Hale Bathhouse at 341 Central Avenue, each with \"a large soaking tub that has hot spring mineral water pumped directly into every room\", and the Eden restaurant"},{"name":"Hot Springs Mountain Tower (park concession)","source":"https://www.hotspringstower.com/","accessed":"2026-10-02","si":["family","senior"],"booking_route":"on-site ticket sales stated (final tickets 30 minutes before closing); no online engine observed","tier_absent_reason":"not-sold","blurb":"216 feet tall at 1,256 feet elevation, overlooking \"140 square miles of surrounding countryside\"; open 9am-6pm daily, adults $13, seniors 55+ $12, National Park Pass holders $11, children 5-11 $6.50"},{"name":"Hot Springs Mountain Drive, the Pagoda and Goat Rock Overlook","source":"https://www.nps.gov/hosp/planyourvisit/scenic-overlooks.htm","accessed":"2026-10-02","si":["senior","family"],"booking_route":"not applicable - free road (NPS)","tier_absent_reason":"not-sold","blurb":"an 1880s carriage road from Fountain Street to the 1911 Pagoda lookout and the tower, continuing to North Mountain''s Goat Rock Overlook facing the Zigzag Mountains - the \"recharge zone for the thermal springs\""},{"name":"West Mountain Drive and trails","source":"https://www.nps.gov/hosp/planyourvisit/trails.htm","accessed":"2026-10-02","si":["wildlife","hiking"],"booking_route":"not applicable - free (NPS)","tier_absent_reason":"not-sold","blurb":"a two-way road to a summit loop with three overlooks, the 1924 picnic shelter and views to Lake Hamilton; the NPS: \"The West Mountain trails are less traveled, providing greater opportunities for wildlife sightings\""},{"name":"Sunset Trail","source":"https://www.nps.gov/hosp/planyourvisit/trails.htm","accessed":"2026-10-02","si":["hiking","adventure","wildlife"],"booking_route":"not applicable - free (NPS)","tier_absent_reason":"not-sold","blurb":"the park''s longest trail, about 10 miles one way or a 15-17 mile loop, in three sections - West Mountain (2.8 mi), Sugarloaf Mountain (2.6 mi, with Balanced Rock Overlook) and Stonebridge Road (3.8 mi)"},{"name":"Hot Water Cascade, Display Spring and the jug fountains","source":"https://www.nps.gov/hosp/planyourvisit/thermal-springs.htm","accessed":"2026-10-02","si":["family","wellness","culture"],"booking_route":"not applicable - free (NPS)","tier_absent_reason":"not-sold","blurb":"the springs emerge at 143°F; the Cascade on Arlington Lawn is the largest visible spring, the Display Spring sits behind the Maurice Bathhouse, and \"Drinking the hot springs water is perfectly normal, even encouraged\" at free jug fountains"},{"name":"Ranger programs and Junior Ranger","source":"https://www.nps.gov/hosp/planyourvisit/guidedtours.htm","accessed":"2026-10-02","si":["family","culture"],"booking_route":"not applicable - free, no reservation (NPS)","tier_absent_reason":"not-sold","blurb":"outdoor walks, Fordyce tours and pop-up programs year-round on a seasonal timetable, Junior Ranger programs on summer Saturdays at 2 pm; no reservations"},{"name":"In the Trees Luxury Treehouses & Cabins","source":"https://inthetrees.com/","accessed":"2026-10-02","si":["glamping","romance","wellness"],"booking_route":"Mews (app.mews.com distributor link on its site)","tier_absent_reason":"not-sold","blurb":"treehouses and cabins with private jacuzzis on a 550-acre property in the Ouachitas at 121 Blowout Mountain Rd; add-on massages, private chef and e-bike rentals near the Northwoods and Cedar Glades trails"},{"name":"Starlight Haven Hot Springs","source":"https://www.hipcamp.com/en-US/land/arkansas-starlight-haven-hot-springs-xryhw6w8","accessed":"2026-10-02","si":["glamping","romance"],"booking_route":"Hipcamp (own website not observed)","tier_absent_reason":"not-sold","blurb":"27 acres with geodesic domes, handcrafted treehouses with fireplaces, and luxury safari tents (ADA accessible), every unit with a private hot tub"},{"name":"Fern Dell: Secluded Woodland Glamp","source":"https://www.hipcamp.com/en-US/p/united-states/arkansas/state-park/lake-ouachita/all","accessed":"2026-10-02","si":["glamping","romance"],"booking_route":"Hipcamp","tier_absent_reason":"not-sold","blurb":"a \"secluded and private glam-camp for two on 16 wooded acres\" - bell tents with queen beds and an outdoor kitchen"},{"name":"DeGray Lake Resort State Park Rent-A-Yurts","source":"https://www.arkansas.com/state-parks/parks/degray-lake-resort-state-park","accessed":"2026-10-02","si":["glamping","family","sports"],"booking_route":"Arkansas State Parks reservation system (reserve.arkansasstateparks.com) or phone","tier_absent_reason":"not-sold","blurb":"three Rent-A-Yurts beside a 90-room lodge, 18-hole championship golf course and full-service marina at Bismarck; free entry to the state park"},{"name":"Lake Catherine State Park Rent-A-Yurt and cabins","source":"https://www.arkansas.com/state-parks/parks/lake-catherine-state-park","accessed":"2026-10-02","si":["glamping","family","hiking"],"booking_route":"Arkansas State Parks reservation system (reserve.arkansasstateparks.com/lake-catherine)","tier_absent_reason":"not-sold","blurb":"one Rent-A-Yurt and 20 cabins (one with a private fishing pier) on 1,900-acre Lake Catherine, with the Falls Branch waterfall trail and seasonal horseback rides ($60-$62 per rider)"},{"name":"Ouachita River Haven, Pencil Bluff","source":"https://www.hipcamp.com/en-US/land/arkansas-ouachita-river-haven-y0zhyxpe","accessed":"2026-10-02","si":["glamping","adventure","family"],"booking_route":"Hipcamp","tier_absent_reason":"not-sold","blurb":"riverside camp with tipi rentals and a bunkhouse plus tent and RV sites, \"1000 ft of river access, with canoe & kayak docks, swimming hole\"; a Hipcamp 2024 Best in Arkansas finalist"},{"name":"Ouachita Campground at Edendell, Oden","source":"https://www.hipcamp.com/en-US/land/arkansas-ouachita-campground-at-edendell-v1qh7ewl","accessed":"2026-10-02","si":["glamping","adventure"],"booking_route":"Hipcamp","tier_absent_reason":"not-sold","blurb":"28 acres off Highway 88 between Mena and Hot Springs with one furnished canvas glamping deck, RV and tent sites, half a mile from the Ouachita River"},{"name":"Gulpha Gorge Campground (NPS)","source":"https://www.nps.gov/hosp/planyourvisit/campground.htm","accessed":"2026-10-02","si":["family","hiking"],"booking_route":"Recreation.gov - all 40 sites require prior reservation, up to 6 months ahead","tier_absent_reason":"not-sold","blurb":"the park''s own campground: 40 tent-and-RV sites, all with full hookups (30/50 amp, water, sewer), not pull-through; $34/night; 14 consecutive days and 30 days a year maximum"},{"name":"Lake Ouachita State Park","source":"https://www.arkansas.com/state-parks/parks/lake-ouachita-state-park","accessed":"2026-10-02","si":["family","group","adventure"],"booking_route":"Arkansas State Parks reservation system (reserve.arkansasstateparks.com/lake-ouachita)","tier_absent_reason":"not-sold","blurb":"on Arkansas'' largest lake (40,000 acres): 93 campsites, 8 cabins, 4 camper cabins, a seasonal marina renting barges, canoes and kayaks, and the Three Sisters'' Springs historic site; free entry"},{"name":"DeGray Lake Resort State Park campground","source":"https://www.arkansas.com/state-parks/parks/degray-lake-resort-state-park","accessed":"2026-10-02","si":["family","sports"],"booking_route":"Arkansas State Parks reservation system or phone","tier_absent_reason":"not-sold","blurb":"113 campsites from basic tent spots to Class AAA full hookups, two swim beaches, five hiking trails and disc golf"},{"name":"Lake Catherine State Park campground","source":"https://www.arkansas.com/state-parks/parks/lake-catherine-state-park","accessed":"2026-10-02","si":["family","hiking"],"booking_route":"Arkansas State Parks reservation system (reserve.arkansasstateparks.com/lake-catherine)","tier_absent_reason":"not-sold","blurb":"70 campsites (47 Class AAA full hookup, 23 Class B) and 6 primitive tent sites, a free swimming beach (no lifeguard) and year-round interpretive programs"},{"name":"Hot Springs National Park KOA Holiday","source":"https://kcncampgrounds.com/campground/hot-springs-national-park/","accessed":"2026-10-02","si":["family","group"],"booking_route":"KOA.com (koa.com/campgrounds/hot-springs-national-park/)","tier_absent_reason":"not-sold","blurb":"RV sites up to 70 feet, tent sites, camping cabins and deluxe cabins at 838 McClendon Road; the city listing notes a complimentary shuttle to Oaklawn during live racing and to Magic Springs"},{"name":"Lake Hamilton Escape RV & Cabin Campground","source":"https://www.lakehamiltonescape.com/","accessed":"2026-10-02","si":["family","group"],"booking_route":"Campspot","tier_absent_reason":"not-sold","blurb":"lakefront RV sites with private layout decks, big-rig hilltop sites and furnished waterfront cabins from $125/night at 200 River Oaks Drive"},{"name":"Finish Line RV Park","source":"https://finishlinervpark.com/","accessed":"2026-10-02","si":["family","sports"],"booking_route":"Staylist (booking.staylist.app/finishline)","tier_absent_reason":"not-sold","blurb":"renovated, gated RV park at 263 Golf Links Rd with paved sites, full hookups and a dog park, from $40/night, near Oaklawn and the Creek Greenway Trail to Bathhouse Row"},{"name":"FHU Resort in Hot Springs Nat Park","source":"https://www.hipcamp.com/en-US/d/united-states/arkansas/hot-springs/camping","accessed":"2026-10-02","si":["family"],"booking_route":"Hipcamp","tier_absent_reason":"not-sold","blurb":"eight full-hookup RV sites listed on Hipcamp beside the Oaklawn district"},{"name":"Charlton Recreation Area (Ouachita National Forest)","source":"https://www.hotsprings.org/places/lodging/ouachita-national-forest-camp-charlton-recreation/","accessed":"2026-10-02","si":["family","hiking","senior"],"booking_route":"not observed (the Forest Service page returned 403)","tier_absent_reason":"not-sold","blurb":"a 1935 Civilian Conservation Corps stone dam forming a swimming area on Walnut Creek, 48 camping units with full or partial hookups, and the Lake Ouachita Vista Trail"},{"name":"Fancy Hill Cabins and RV Park, Caddo Gap","source":"https://www.hipcamp.com/en-US/land/arkansas-fancy-hill-cabins-and-rv-park-llc-dw9hw9re","accessed":"2026-10-02","si":["family","romance"],"booking_route":"Hipcamp","tier_absent_reason":"not-sold","blurb":"12 acres on the South Fork of the Caddo River in the Ouachita National Forest: five RV and tent sites and two handmade cabins, one couples-only with a creekside hot tub"},{"name":"The Arlington Resort Hotel & Spa","source":"https://www.arlingtonhotel.com/","accessed":"2026-10-02","si":["wellness","culture","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"the 1920s twin-towered hotel at 239 Central Avenue with Mineral Water Rooms piped with hot springs water, a historic thermal bathhouse, and rooms from $129"},{"name":"Garvan Woodland Gardens","source":"https://www.garvangardens.org/","accessed":"2026-10-02","si":["senior","romance","family"],"booking_route":"VBO Tickets (garvangardens.vbotickets.com)","tier_absent_reason":"not-sold","blurb":"the University of Arkansas botanical garden on 4½ miles of wooded shoreline at 550 Arkridge Road; adults $22, children 4-12 $10, cart tours $20; seasonal Holiday Lights (2026 dates not confirmed)"},{"name":"Oaklawn Racing Casino Resort","source":"https://www.hotsprings.org/places/activities/oaklawn-hot-springs/","accessed":"2026-10-02","si":["sports","group","wellness"],"booking_route":"not observed (oaklawn.com refused the connection)","tier_absent_reason":"not-sold","blurb":"thoroughbred racing since 1904 at 2705 Central Avenue, with a 24/7 smoke-free casino, trackside suites and the Astral Spa; racing-season dates not confirmed this build"},{"name":"Magic Springs Theme and Water Park","source":"https://www.magicsprings.com/","accessed":"2026-10-02","si":["family","group"],"booking_route":"own online ticket store and group tickets (10+); engine not named as fetched","tier_absent_reason":"not-sold","blurb":"theme park and water park just outside downtown; Magic Screams runs \"9/26-11/1\" with trick-or-treating by day and scare zones by night"},{"name":"National Park Duck Tours","source":"https://www.rideaduck.com/","accessed":"2026-10-02","si":["family","group","culture"],"booking_route":"phone (501) 321-2911, text or contact form","tier_absent_reason":"not-sold","blurb":"a 75-minute land-and-water tour in a WWII-era DUKW from 418 Central Avenue past Bathhouse Row and onto Lake Hamilton; daily 9:30am-6pm, private charters for groups"},{"name":"Fun Day Boat Rentals, Lake Hamilton","source":"https://fundayboatrentals.com","accessed":"2026-10-02","si":["family","group"],"booking_route":"RecreoGo (recreogo.com) or phone 501-494-0255","tier_absent_reason":"not-sold","blurb":"family-owned pontoon rentals \"delivered right to your vacation property\" on Lake Hamilton"},{"name":"Mountain Harbor Resort & Spa, Lake Ouachita","source":"http://mountainharborresort.com/","accessed":"2026-10-02","si":["family","wellness","group"],"booking_route":"phone 870-867-2191 / 800-832-2276 (online engine not observed)","tier_absent_reason":"not-sold","blurb":"family-owned for over 70 years at Mt Ida: lodging, full-service marina, the Turtle Cove Spa, scuba diving, fishing and hiking"},{"name":"Northwoods Trails","source":"https://www.northwoodstrails.org/","accessed":"2026-10-02","si":["adventure","sports","hiking"],"booking_route":"not applicable - public trail system","tier_absent_reason":"not-sold","blurb":"31.5+ miles of green, blue and black singletrack, flow trails and the Lucky 13 expert section, with a skills park at Cedar Glades; the Pullman trailhead links to downtown through the park"},{"name":"Greenway Outfitters","source":"https://greenwayoutfitters.com","accessed":"2026-10-02","si":["adventure","family","senior"],"booking_route":"Booqable on its own site, or phone 501-463-2453","tier_absent_reason":"not-sold","blurb":"Pedego e-bike and Giant/Liv rentals, repairs and craft coffee at 300 Valley Street beside the Hot Springs Greenway; delivery $45 in town, $60 surrounding"},{"name":"Parkside Cycle","source":"https://www.parksidecycle.com/","accessed":"2026-10-02","si":["adventure","group"],"booking_route":"not observed (rentals page referenced)","tier_absent_reason":"not-sold","blurb":"a 30-year Hot Springs bike shop at 719 Whittington Ave with rentals for individuals and groups"},{"name":"Ron Coleman Mining, Jessieville","source":"https://www.colemanquartz.com/","accessed":"2026-10-02","si":["family","adventure","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"public quartz crystal digging, night digs, a zip line over the mine, military-vehicle mine tours, horseback rides and the Crystal Ridge Campground"},{"name":"Mid-America Science Museum","source":"https://www.midamericamuseum.org/","accessed":"2026-10-02","si":["family"],"booking_route":"own online shop (shop.midamericamuseum.org); engine not named","tier_absent_reason":"not-sold","blurb":"hands-on science museum at 500 Mid America Blvd; adults $15, children and seniors $13; closed Mondays"},{"name":"Gangster Museum of America","source":"https://www.tgmoa.com/","accessed":"2026-10-02","si":["culture","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"seven galleries and an antique casino on the 1920s-1940s gangster era of Hot Springs, at 510 Central Avenue"},{"name":"Hot Springs Documentary Film Festival, October 9-17, 2026","source":"https://www.hsdfi.org/","accessed":"2026-10-02","si":["culture"],"booking_route":"Eventive (hsdff2026.eventive.org)","tier_absent_reason":"not-sold","blurb":"the 35th edition of \"the longest running, all-documentary film festival in North America\", opening with a gala at Oaklawn"},{"name":"Central Avenue galleries and studios","source":"https://www.hotsprings.org/places/activities/1","accessed":"2026-10-02","si":["culture","romance"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Visit Hot Springs lists Justus Fine Art Gallery (827 A Central), Artists Workshop Gallery (610A Central), American Art Gallery (724 Central), Emergent Arts and Dryden Pottery (Whittington Ave) and Fox Pass Pottery"},{"name":"Crater of Diamonds State Park, Murfreesboro","source":"https://www.hotsprings.org/explore/crystal-digging/","accessed":"2026-10-02","si":["family","adventure"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"\"One of the only places in the world where the public can search for real diamonds in their original volcanic source\""},{"name":"McClard''s Bar-B-Q","source":"https://www.mcclards.com/","accessed":"2026-10-02","si":["culinary","culture","family"],"booking_route":"walk-in; online store and ordering","tier_absent_reason":"not-sold","blurb":"founded 1928 by Alex and Alice McClard at a tourist court, where a guest paid for lodging with a recipe for \"the world''s greatest hot sauce\"; still family-run, now in its fourth generation"},{"name":"The Ohio Club","source":"https://www.theohioclub.com/","accessed":"2026-10-02","si":["culinary","culture","group"],"booking_route":"not observed (reservations not mentioned); phone (501) 627-0702","tier_absent_reason":"not-sold","blurb":"\"Arkansas'' Oldest Operating Bar\", serving since 1905 at 336 Central Ave, a Prohibition haunt of Al Capone, Bugsy Siegel and Babe Ruth, with live music Thursday to Sunday; closed Wednesdays"},{"name":"Crystal Ridge Distillery","source":"https://www.crystalridgedistillery.com/","accessed":"2026-10-02","si":["culinary","group","culture"],"booking_route":"phone 501-627-0722 or email, by appointment","tier_absent_reason":"not-sold","blurb":"\"Seven generations of Bradley family craft\" at 455 Broadway St, distilling moonshine and Arkansas vodka; tastings and tours by appointment"},{"name":"Mountain Valley Spring Water Visitor Center","source":"https://www.mountainvalleyspring.com/","accessed":"2026-10-02","si":["culinary","culture","wellness"],"booking_route":"not observed (hours not posted; call ahead)","tier_absent_reason":"not-sold","blurb":"the Ouachita spring water bottled in glass since 1871 keeps a public visitor center at 150 Central Ave, on Bathhouse Row''s doorstep"},{"name":"Rolando''s Restaurante","source":"https://rolandosrestaurant.com/","accessed":"2026-10-02","si":["culinary","romance","culture"],"booking_route":"own reservation link on site; online ordering","tier_absent_reason":"not-sold","blurb":"Ecuadorian chef Rolando Cuzco''s Central and South American kitchen at 210 Central Ave, with murals he hand-carved into the plaster walls; handmade tamales and margaritas"},{"name":"DeLuca''s Pizza","source":"https://www.arkansas.com/hot-springs","accessed":"2026-10-02","si":["culinary","family","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"a locally owned pizzeria the state tourism site calls \"the talk of the town\" (per the Arkansas state tourism listing)"},{"name":"Rod''s Pizza Cellar","source":"https://www.hotsprings.org/blog/categories/feast-mode/","accessed":"2026-10-02","si":["culinary","family","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"\"Slinging pizza for nearly 50 years in Hot Springs\", home of the Godfather Pizza (per the city visitor bureau FeastMode listing)"},{"name":"The Porterhouse","source":"https://www.hotsprings.org/blog/categories/feast-mode/","accessed":"2026-10-02","si":["culinary","romance","wine"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"open since 2007 with prime-only steaks, seafood and an extensive wine list (per the city visitor bureau FeastMode listing)"},{"name":"Fisherman''s Wharf, Lake Hamilton","source":"https://www.hotsprings.org/blog/categories/feast-mode/","accessed":"2026-10-02","si":["culinary","family","romance"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"family-owned waterfront surf-and-turf dining on Lake Hamilton (per the city visitor bureau FeastMode listing)"},{"name":"Cajun Boilers, Lake Hamilton","source":"https://www.hotsprings.org/blog/categories/feast-mode/","accessed":"2026-10-02","si":["culinary","group","family"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"\"Hot Springs'' Cajun, lake-side staple\" for Pasta Acadiana and shrimp and grits (per the city visitor bureau FeastMode listing)"},{"name":"Stubby''s BBQ","source":"https://www.hotsprings.org/blog/districts-west/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"phone 501-624-1552","tier_absent_reason":"not-sold","blurb":"a West District barbecue house at 3024 Central Avenue counted among the city''s BBQ spots with \"a rich history\" (per the city visitor bureau listing)"}],"faq":[{"q":"Does Hot Springs National Park charge an entrance fee?","a":"No. The NPS states \"No entrance pass required.\" Camping at Gulpha Gorge carries a fee ($34 per night).","source":"https://www.nps.gov/hosp/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"Can I soak in the hot springs?","a":"Not outdoors. The NPS says there are no outdoor soaking opportunities; Buckstaff Bathhouse (509 Central Avenue) and Quapaw Bathhouse (413 Central Avenue) offer full immersion in the thermal water.","source":"https://www.nps.gov/hosp/planyourvisit/soak-in-the-springs.htm","accessed":"2026-10-02"},{"q":"Can I drink the thermal spring water?","a":"Yes. The NPS states \"Drinking the hot springs water is perfectly normal, even encouraged,\" and provides it free at jug fountains around the park. The springs emerge at 143°F.","source":"https://www.nps.gov/hosp/planyourvisit/thermal-springs.htm","accessed":"2026-10-02"},{"q":"How do I book Gulpha Gorge Campground?","a":"On Recreation.gov. All 40 sites require prior reservation; each has full hookups and costs $34 per night. Accessible sites open one week in advance.","source":"https://www.nps.gov/hosp/planyourvisit/campground.htm","accessed":"2026-10-02"},{"q":"Do I need a reservation at Buckstaff Bathhouse?","a":"No. Buckstaff states that no reservations are required; baths and massages are walk-in.","source":"https://www.buckstaffbaths.com/","accessed":"2026-10-02"},{"q":"Can children use Quapaw Baths & Spa?","a":"Not under 14. Quapaw states \"WE DO NOT OFFER ANY SERVICES FOR CHILDREN UNDER THE AGE OF 14.\"","source":"http://quapawbaths.com/","accessed":"2026-10-02"}],"seo":{"meta_title":"Hot Springs National Park: Bathhouse Row, Thermal Baths & Ouachita Glamping | TravelWell","meta_description":"No entrance fee, two working bathhouses, free thermal water, the Sunset Trail, and where to stay from Gulpha Gorge to treehouses and lake state parks.","slug":"hot-springs-national-park-arkansas","primary_keyword":"Hot Springs National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Hot Springs National Park, Arkansas"}}'::jsonb, 61),
  ('gateway-arch-missouri', '12A', 'Gateway Arch National Park', 'United States', 'A five-person pod up the inside of a 1965 steel arch, a free museum underneath it, and a whole city of free museums, blues rooms and toasted ravioli around it', 'future', 'verified', 'mountainValley', 'The Ozarks & Mid-South', '{"culture","family","senior","romance","parks"}', '{"urban","historic","festive"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Tram Ride to the Top","source":"https://www.gatewayarch.com/gateway-arch-national-park/tram-ride-to-the-top/","accessed":"2026-10-02","si":["family","culture"],"booking_route":"operator''s own ticketing at tickets.gatewayarch.com (Bi-State Development), plus phone (877) 982-1410 and the Visitor Center desk","tier_absent_reason":"not-sold","blurb":"five-person pods that travel up the inside of the Arch; the whole process takes about 45-60 minutes with a maximum of 10 minutes at the top; adult tickets $15-$19 and child from $11, prices varying by date; no wheelchairs, walkers, scooters or strollers in the trams"},{"name":"Museum at the Gateway Arch","source":"https://www.nps.gov/jeff/planyourvisit/museum-at-the-gateway-arch.htm","accessed":"2026-10-02","si":["culture","family","senior"],"booking_route":"no ticket required","tier_absent_reason":"not-sold","blurb":"free, underground beneath the Arch, open daily 9am to 6pm; six galleries from Colonial St. Louis to Building the Dream, telling the city''s story from 1764 to 1965"},{"name":"The Old Courthouse","source":"https://www.nps.gov/jeff/planyourvisit/och.htm","accessed":"2026-10-02","si":["culture","senior"],"booking_route":"no reservation for general visitors; groups over 10 call 314-655-1731 or 314-655-1636","tier_absent_reason":"not-sold","blurb":"site of the first two Dred Scott trials (1847 and 1850) and Virginia Minor''s voting-rights case; four museum galleries opened in May 2025 after a $24.5 million renovation; free, open daily 9am to 5pm, ranger tours daily at 2:15 pm"},{"name":"St. Louis Riverfront Cruise (Tom Sawyer and Becky Thatcher)","source":"https://www.gatewayarch.com/riverfront/riverboat-cruises/","accessed":"2026-10-02","si":["family","senior","culture"],"booking_route":"operator''s own ticketing at tickets.gatewayarch.com","tier_absent_reason":"not-sold","blurb":"a one-hour daytime cruise on a replica 19th-century paddle-wheel riverboat from the cobblestone levee at 50 South Leonor K Sullivan Boulevard, $26 adult; daily March to November"},{"name":"Skyline Dinner Cruise","source":"https://www.gatewayarch.com/buy-tickets/","accessed":"2026-10-02","si":["romance","group"],"booking_route":"operator''s own ticketing at tickets.gatewayarch.com","tier_absent_reason":"not-sold","blurb":"a two-hour evening cruise with \"live music or a DJ, a chef-inspired menu\", $64 adult"},{"name":"Specialty riverboat cruises - Blues Cruise, Lock-N-Dam, Sunday Brunch","source":"https://www.gatewayarch.com/buy-tickets/","accessed":"2026-10-02","si":["culture","group","family"],"booking_route":"operator''s own ticketing at tickets.gatewayarch.com","tier_absent_reason":"not-sold","blurb":"Blues Cruise $35 (21+), Lock-N-Dam Cruise $59 with buffet lunch, Sunday Brunch Cruise $62, Groove & Spin $35 (21+); December holiday cruises including Caroling with Santa ($29) and PJs and Pancakes ($45)"},{"name":"Documentary film, Virtual Reality Theater and combo tickets","source":"https://www.gatewayarch.com/buy-tickets/","accessed":"2026-10-02","si":["family","culture"],"booking_route":"operator''s own ticketing at tickets.gatewayarch.com","tier_absent_reason":"not-sold","blurb":"documentary $7, VR Theater $8 (an immersive 1850s St. Louis Riverfront); combos from Builder''s View ($19-$23) to Ultimate Explorer ($50-$54: tram, film, VR and a riverboat cruise); Gateway to the Stars is free with registration recommended"},{"name":"Gateway Arch park grounds","source":"https://www.gatewayarch.com/","accessed":"2026-10-02","si":["family","wellness"],"booking_route":"no ticket required","tier_absent_reason":"not-sold","blurb":"\"Over 91 acres of urban green space\" with walking paths around the Arch, with the Arch Café and Paddlewheel Café"},{"name":"Winterfest on the Arch grounds, November 21, 2026 - January 3, 2027","source":"https://www.archpark.org/","accessed":"2026-10-02","si":["family","sports","wellness"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"the Gateway Arch Park Foundation''s holiday season on the grounds, opening with the sixth annual Winterfest 5K on November 21; the Foundation also runs free Sunrise Yoga at Kiener Plaza and Picnic in Your Park"},{"name":"Gateway Helicopter Tours","source":"https://www.gatewayhelicoptertours.com/","accessed":"2026-10-02","si":["adventure","romance","family"],"booking_route":"FareHarbor; phone 314-496-4494; walk-ins","tier_absent_reason":"not-sold","blurb":"flights from a floating heliport below the Arch at 50 N Leonor K Sullivan Blvd - Riverfront, Anheuser-Busch, Botanical Gardens and St. Louis Deluxe routes; daily April through November, walk-ins welcome; a separate attraction from the park"},{"name":"Hawks Bluff Farm Campground, Tiff (bell tent glamping)","source":"https://www.hipcamp.com/en-US/land/missouri-hawks-bluff-farm-campground-gwz6h9jn","accessed":"2026-10-02","si":["glamping","family"],"booking_route":"Hipcamp","tier_absent_reason":"not-sold","blurb":"two bell tents sleeping four each on a 420-acre working farm in the Ozarks, with electric hookups, a common kitchen, hot showers, a pond with beach and Mill Creek swimming; rock hunting and farm animals"},{"name":"Cuivre River State Park","source":"https://www.hipcamp.com/en-US/state-park/united-states/missouri/cuivre-river/all","accessed":"2026-10-02","si":["family","hiking"],"booking_route":"Missouri State Parks reservations, 12 months ahead (as reported on the Hipcamp page; mostateparks.com returned 403)","tier_absent_reason":"not-sold","blurb":"Cuivre Campground''s 110 sites - basic, electric, 30 full-hookup, platform tent and walk-in tent sites - around a 55-acre lake, with twelve hiking trails and seasonal kayak and canoe rentals; showers April 15 to October 31"},{"name":"Meramec State Park","source":"https://www.hipcamp.com/en-US/state-park/united-states/missouri/meramec/all","accessed":"2026-10-02","si":["family","hiking"],"booking_route":"Missouri State Parks reservations, 12 months ahead (as reported on the Hipcamp page)","tier_absent_reason":"not-sold","blurb":"179 tent and RV sites, some on the riverfront, plus cabins, a motel, restaurant and visitor center; reservations March through November, first-come first-served outside that season"},{"name":"La Belle Vie, De Soto","source":"https://www.hipcamp.com/en-US/land/missouri-la-belle-vie-the-beautiful-life-xryh5vlj","accessed":"2026-10-02","si":["family","sports"],"booking_route":"Hipcamp","tier_absent_reason":"not-sold","blurb":"33 RV sites on 327 acres - full hookup $50/night, electric $35, primitive $20 - with a 40-acre private lake, pool, sauna, mini golf and tennis; the former Timber Creek Resort"},{"name":"Sudden Valley Ranch, Warrenton","source":"https://www.hipcamp.com/en-US/land/missouri-sudden-valley-ranch-3pw1hkn6","accessed":"2026-10-02","si":["family","wildlife"],"booking_route":"Hipcamp","tier_absent_reason":"not-sold","blurb":"three rustic tent/RV sites for up to 12 each on 138 acres with 1.5 miles of creek and swimming holes, horses and farm dogs; no hookups; a 2026 Best Hipcamp in Missouri"},{"name":"Sundermeier RV Park, St. Charles","source":"https://www.sundermeierrvpark.com/","accessed":"2026-10-02","si":["family","senior"],"booking_route":"reservations page on its own site, platform not named; phone (636) 940-0111","tier_absent_reason":"not-sold","blurb":"full-hookup RV sites, open year-round, beside Katy Trail State Park in Missouri''s former state capital, 111 Transit Street"},{"name":"Pere Marquette Lodge and cabins, Grafton, Illinois","source":"https://www.pmlodge.net/","accessed":"2026-10-02","si":["romance","senior","hiking"],"booking_route":"hotel booking engine at reservations.vmpms.com; phone (618) 786-2331","tier_absent_reason":"not-sold","blurb":"a Civilian Conservation Corps lodge with a 700-ton stone fireplace inside 8,000+ acres of Pere Marquette State Park; lodge rooms from $109 and cabins from $129 plus tax on advertised packages; restaurant, winery, pool"},{"name":"Forest Park","source":"https://explorestlouis.com/neighborhood/forest-park/","accessed":"2026-10-02","si":["family","culture","wellness"],"booking_route":"no ticket required","tier_absent_reason":"not-sold","blurb":"about 1,300 acres, roughly 500 acres larger than Central Park, with 30+ miles of trails, the Boathouse''s seasonal paddle boats and kayaks on the Emerson Grand Basin, and The Muny''s summer Broadway season"},{"name":"Saint Louis Zoo","source":"https://www.stlzoo.org/","accessed":"2026-10-02","si":["family","wildlife","senior"],"booking_route":"not observed (free entry)","tier_absent_reason":"not-sold","blurb":"free admission, open daily 9am to 5pm at 1 Government Drive in Forest Park; paid extras include the Zooline Railroad and behind-the-scenes tours; Boo at the Zoo on select nights October 9-30"},{"name":"Saint Louis Art Museum and Missouri History Museum","source":"https://explorestlouis.com/neighborhood/forest-park/","accessed":"2026-10-02","si":["culture","senior","family"],"booking_route":"not observed (slam.org and mohistory.org returned 403)","tier_absent_reason":"not-sold","blurb":"two of Forest Park''s institutions that the tourism bureau lists with no admission cost"},{"name":"Saint Louis Science Center and McDonnell Planetarium","source":"https://www.slsc.org/","accessed":"2026-10-02","si":["family","culture"],"booking_route":"own events ticketing system","tier_absent_reason":"not-sold","blurb":"\"Entry is always free!\"; paid tickets for OMNIMAX films, planetarium shows and flight simulators; closed Tuesdays"},{"name":"Missouri Botanical Garden and Garden Glow","source":"https://www.missouribotanicalgarden.org/","accessed":"2026-10-02","si":["romance","senior","culture"],"booking_route":"advance e-tickets on its own site (engine not named); walk-up at the gate, cashless","tier_absent_reason":"not-sold","blurb":"the Climatron conservatory, Japanese Garden and Tower Grove House at 4344 Shaw Blvd; $16 general admission (13+), children 12 and under free; Garden Glow November 14 to January 2"},{"name":"City Museum","source":"https://explorestlouis.com/partner/city-museum/","accessed":"2026-10-02","si":["family","adventure"],"booking_route":"not observed (citymuseum.org returned 403)","tier_absent_reason":"not-sold","blurb":"an interactive art installation and playground by artist Bob Cassilly in a 600,000-square-foot former shoe warehouse at 750 N. 16th St. - slides, caves and climbing structures, with roof access as an add-on"},{"name":"Anheuser-Busch St. Louis Brewery tours","source":"https://www.budweisertours.com/","accessed":"2026-10-02","si":["culture","group"],"booking_route":"not observed (tours page did not render its booking detail)","tier_absent_reason":"not-sold","blurb":"five tours at 1200 Lynch St - Day Fresh, Beermaster, Clydesdale VIP Experience, Finisher and King of Beers - with the Clydesdales and the Biergarten; closed November 8 and December 1-2"},{"name":"Soulard and the Soulard Farmers Market","source":"https://explorestlouis.com/neighborhood/soulard-st-louis/","accessed":"2026-10-02","si":["culture","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"red-brick row houses, a market founded circa 1779 with 148 stalls, and \"the nation''s second largest Mardi Gras celebration\"; Hammerstone''s offers \"live music seven nights and three afternoons\""},{"name":"The Hill and toasted ravioli","source":"https://explorestlouis.com/neighborhood/the-hill-st-louis/","accessed":"2026-10-02","si":["culture","family","romance"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"St. Louis'' Little Italy, founded by Italian immigrants, home of \"St. Louis'' quintessential appetizer\" - Rigazzi''s (the oldest restaurant on The Hill), Favazza''s, Gian Tony''s, Zia''s, Anthonino''s and Marconi Mercato, plus bocce"},{"name":"EAT St. Louis Food Tours - The Hill","source":"https://saintlouisfoodtours.com/","accessed":"2026-10-02","si":["culture","group"],"booking_route":"FareHarbor","tier_absent_reason":"not-sold","blurb":"a three-hour walking food tour of The Hill from $79, with at least two sit-down stops; private group tours available"},{"name":"Pappy''s Smokehouse","source":"https://www.pappyssmokehouse.com/","accessed":"2026-10-02","si":["culture","family"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Memphis-style ribs smoked over apple and cherry wood at 3106 Olive St, named \"Best Ribs in America by the Food Network\"; closed Tuesdays"},{"name":"Ted Drewes Frozen Custard on Route 66","source":"https://www.teddrewes.com/","accessed":"2026-10-02","si":["family","culture"],"booking_route":"walk-up","tier_absent_reason":"not-sold","blurb":"the \"Concrete\" custard, thick enough to turn upside down, served since 1929; the Chippewa stand on historic Route 66 is open year-round 11am to 10:30pm"},{"name":"National Blues Museum","source":"https://explorestlouis.com/guide/live-music/","accessed":"2026-10-02","si":["culture","senior"],"booking_route":"not observed (museum''s own visit page returned 404)","tier_absent_reason":"not-sold","blurb":"downtown museum of the blues as the foundation of modern American music, with artifact-driven exhibits and select live performances"},{"name":"Broadway Oyster Bar","source":"https://explorestlouis.com/guide/live-music/","accessed":"2026-10-02","si":["culture","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"a New Orleans-style bar in Soulard with \"live music from local and national acts seven nights a week\" - blues, funk, roots, R&B - most of it free"},{"name":"Jazz St. Louis","source":"https://jazzstl.org/","accessed":"2026-10-02","si":["culture","romance","senior"],"booking_route":"MetroTix digital box office; box office three hours before shows","tier_absent_reason":"not-sold","blurb":"jazz venue and education centre at 3536 Washington Ave presenting national and local touring musicians; named one of the world''s top jazz venues by DownBeat in 2026; 26-27 single tickets on sale from October"},{"name":"Blueberry Hill and the Duck Room, Delmar Loop","source":"https://www.blueberryhill.com/","accessed":"2026-10-02","si":["culture","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"a Loop institution since 1972 where Chuck Berry played the Duck Room stage over 200 times; pop-culture memorabilia, live music several nights a week"},{"name":"The Delmar Loop","source":"https://explorestlouis.com/neighborhood/the-delmar-loop/","accessed":"2026-10-02","si":["culture","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"the St. Louis Walk of Fame''s 150+ brass stars, the Chuck Berry statue, The Pageant and Delmar Hall, and Vintage Vinyl; named \"one of 10 Great Streets in America\" by the American Planning Association"},{"name":"Central West End and the Cathedral Basilica","source":"https://explorestlouis.com/neighborhood/central-west-end/","accessed":"2026-10-02","si":["culture","romance","senior"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"\"millions of mosaics\" inside the Cathedral Basilica, open daily 7am to 5pm, and restaurants including Brasserie by Niche"},{"name":"Busch Stadium and the St. Louis Cardinals","source":"https://www.mlb.com/cardinals","accessed":"2026-10-02","si":["sports","family","group"],"booking_route":"MLB.com ticketing","tier_absent_reason":"not-sold","blurb":"the Cardinals'' ballpark, with single-game tickets, stadium tours and the Cardinals Hall of Fame and Museum listed by the club"},{"name":"St. Louis Union Station - Aquarium and the St. Louis Wheel","source":"https://www.stlouisunionstation.com/","accessed":"2026-10-02","si":["family","romance"],"booking_route":"own site (hotel booking interface and attraction tickets)","tier_absent_reason":"not-sold","blurb":"the St. Louis Aquarium, a 200-foot wheel with climate-controlled gondolas, a Grand Hall Light Show on a 65-foot ceiling, ropes course and mini golf, plus a historic hotel, at 1820 Market Street"},{"name":"St. Louis Fun Tours trolley","source":"https://stltrolley.com/","accessed":"2026-10-02","si":["senior","family","group"],"booking_route":"Bookeo (bookeo.com/stlouisfuntours); phone (314) 241-1400","tier_absent_reason":"not-sold","blurb":"a 23-mile, roughly 80-minute narrated trolley loop from Horseshoe Casino past Union Station, both cathedrals, the Old Courthouse, the Arch and Forest Park"},{"name":"Big Muddy Adventures","source":"https://www.2muddy.com/","accessed":"2026-10-02","si":["adventure","expedition","romance"],"booking_route":"online booking platform linked from its site (engine not named); reservations@2muddy.com","tier_absent_reason":"not-sold","blurb":"canoe and kayak trips on the Mississippi and Missouri rivers from hour-long paddles to multi-day expeditions, sunset private island dinners, and an Arch Riverfront location with bike rentals"},{"name":"Guided city walks - Landmarks, 4theVille, TourCWE","source":"https://explorestlouis.com/plan-your-trip/guided-tours/","accessed":"2026-10-02","si":["culture","senior","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Landmarks Association''s downtown architecture walks, 4theVille''s storyteller tours of Black history in The Ville, and TourCWE''s two-mile Central West End route, all listed by the tourism bureau"},{"name":"Cahokia Mounds","source":"https://explorestlouis.com/day-trip/cahokia-mounds/","accessed":"2026-10-02","si":["culture","hiking","family"],"booking_route":"not observed (cahokiamounds.org timed out)","tier_absent_reason":"not-sold","blurb":"\"larger than London in 1250 AD\" - a 2,200-acre site of an ancient indigenous city with 800 acres open, the climbable 100-foot Monks Mound and a reconstructed Woodhenge"},{"name":"Missouri wine country - Augusta and Hermann","source":"https://explorestlouis.com/day-trip/missouri-wine-country/","accessed":"2026-10-02","si":["romance","culture","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Augusta holds the nation''s oldest American Viticultural Area; Hermann, an 1837 German settlement, has Adam Puchta Winery and Stone Hill Winery"},{"name":"Crown Candy Kitchen, Old North St. Louis","source":"https://www.crowncandykitchen.net/","accessed":"2026-10-02","si":["culinary","family","culture"],"booking_route":"walk-in; online takeout menu","tier_absent_reason":"not-sold","blurb":"vintage soda fountain and candy shop at 1401 St. Louis Ave, known for malts and shakes and its 5 Malt Challenge; Monday-Saturday 10:30am-5pm"},{"name":"Gioia''s Deli, The Hill","source":"https://www.gioiasdeli.com/","accessed":"2026-10-02","si":["culinary","culture","family"],"booking_route":"walk-in; online ordering for pickup and delivery","tier_absent_reason":"not-sold","blurb":"since 1918, home of the Hot Salami sandwich - \"Fresh sausage, Sliced Fresh To Order\" - and cited on its site for a James Beard Foundation award; The Hill shop open Monday-Saturday 10am-4pm"},{"name":"Gus'' Pretzels, Soulard/Benton Park","source":"https://www.guspretzels.com/","accessed":"2026-10-02","si":["culinary","family","culture"],"booking_route":"walk-in","tier_absent_reason":"not-sold","blurb":"hand-twisted pretzels baked fresh daily at 1820 Arsenal Street since 1920, now under third-generation baker Gus Jr.; Tuesday-Saturday 7am-4pm"},{"name":"Park Avenue Coffee gooey butter cake","source":"https://www.parkavenuecoffee.com/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"walk-in; online orders and bake-at-home mixes","tier_absent_reason":"not-sold","blurb":"St. Louis'' signature gooey butter cake starting with \"Mom''s Traditional, where it all started\", plus Triple Chocolate and White Chocolate Raspberry, at cafes in Lafayette Square, The Hill, Cortex and 6th & Olive"},{"name":"Schlafly Tap Room, downtown","source":"https://www.schlafly.com/","accessed":"2026-10-02","si":["culinary","group"],"booking_route":"reservations at both brewpubs (platform not observed); Bottleworks online ordering via Toast","tier_absent_reason":"not-sold","blurb":"\"St. Louis'' Original Craft Brewery\" since 1991, brewing 70+ styles; Tap Room downtown and Bottleworks in Maplewood"},{"name":"Urban Chestnut Brewing and Oktoberfest St. Louis","source":"https://www.urbanchestnut.com/","accessed":"2026-10-02","si":["culinary","group","culture"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"German-style lagers at the Grove Bierhall and Midtown Biergarten, with $12 brewery tours; Urban Chestnut produces Oktoberfest St. Louis, scheduled October 2-4, 2026"},{"name":"Kitchen Conservatory cooking classes","source":"https://www.kitchenconservatory.com/","accessed":"2026-10-02","si":["culinary","romance","group"],"booking_route":"own site (Buy button per class); phone 314-862-2665","tier_absent_reason":"not-sold","blurb":"\"more than 1500 different cooking classes every year\" at 9011 Manchester Road - hands-on and demonstration, couples'' date nights and seasonal menus from about $25 to $60 for demonstrations"},{"name":"Mount Pleasant Estates, Augusta","source":"https://www.mountpleasant.com/","accessed":"2026-10-02","si":["wine","romance","culture"],"booking_route":"walk-in (early closings for weddings/events)","tier_absent_reason":"not-sold","blurb":"\"The Oldest Winery In Augusta\", founded 1859 by brothers George and Frederick Muench in the nation''s first government-appointed wine district, with the Appellation Cafe; open daily 11am-5pm"},{"name":"Montelle Winery, Augusta","source":"https://www.montelle.com/","accessed":"2026-10-02","si":["wine","romance","group"],"booking_route":"walk-in; phone (636) 228-4464","tier_absent_reason":"not-sold","blurb":"founded 1970 above the Missouri River Valley and nicknamed \"Halfway To Heaven\" for its view; Norton, Chambourcin and Vidal Blanc Icewine, the Klondike Cafe and weekend live music in season"},{"name":"Hermannhof Winery, Hermann","source":"https://www.hermannhof.com/","accessed":"2026-10-02","si":["wine","culture","romance"],"booking_route":"walk-in tasting room; phone (573) 486-5959","tier_absent_reason":"not-sold","blurb":"built 1848-1852 with ten stone cellars on the National Register, \"America''s only two-time winner of the Brown Forman Trophy\", with the Tin Mill Restaurant and Brewery alongside"}],"faq":[{"q":"Do I need a ticket to visit Gateway Arch National Park?","a":"Not for the museum, gift store or cafe, which the NPS says are always free. You need a ticket for the Tram Ride to the Top, the documentary film, the VR theater and the riverboats.","source":"https://www.nps.gov/jeff/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"How much does the tram to the top of the Gateway Arch cost?","a":"The NPS lists adults (16+) starting at $15 and children (3-15) starting at $11, with infants free and prices varying by date. $3 of the adult ticket is the NPS entrance fee. Tickets are sold at gatewayarch.com, by phone at (877) 982-1410 and at the park entrance.","source":"https://www.nps.gov/jeff/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"Can I ride the Arch tram in a wheelchair?","a":"No. The operator states no wheelchairs, walkers, scooters or strollers are permitted in the trams or on the Observation Deck, and visitors must walk at least 96 steps. The museum has free wheelchairs and a replica arch section with livestream video.","source":"https://www.gatewayarch.com/gateway-arch-national-park/tram-ride-to-the-top/","accessed":"2026-10-02"},{"q":"How long does the Tram Ride to the Top take?","a":"About 45-60 minutes in all, including pre-boarding exhibits, the ride up and down, and a maximum of 10 minutes at the top.","source":"https://www.gatewayarch.com/gateway-arch-national-park/tram-ride-to-the-top/","accessed":"2026-10-02"},{"q":"When do the Gateway Arch riverboats run?","a":"Daily sightseeing cruises run March to November from the cobblestone levee; in December the boats run holiday-themed cruises.","source":"https://www.gatewayarch.com/riverfront/riverboat-cruises/","accessed":"2026-10-02"},{"q":"Is the Old Courthouse open?","a":"Yes. It reopened in May 2025 after renovation and is open daily 9am to 5pm, free, closed on Christmas, Thanksgiving and New Year''s Day, with ranger tours daily at 2:15 pm.","source":"https://www.nps.gov/jeff/planyourvisit/och.htm","accessed":"2026-10-02"}],"seo":{"meta_title":"Gateway Arch National Park: Tram, Museum, Riverboats & St. Louis | TravelWell","meta_description":"How tram tickets are sold, what is free, when the riverboats run, and the St. Louis ring around the Arch from Forest Park to The Hill.","slug":"gateway-arch-national-park-missouri","primary_keyword":"Gateway Arch National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Gateway Arch National Park, St. Louis, Missouri"}}'::jsonb, 62),
  ('lake-of-the-ozarks-missouri', '12A', 'Lake of the Ozarks State Park', 'United States', 'Two lake beaches, Ozark Caverns and thirteen trails', 'future', 'verified', 'mountainValley', 'The Ozarks & Mid-South', '{"family","hiking","adventure","motoring","wildlife","parks"}', '{"family-friendly","serene","adventurous","pastoral"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Public Beach 1 and Grand Glaize Beach","source":"https://web.archive.org/web/20260908031345/https://mostateparks.com/park/lake-ozarks/swimming","accessed":"2026-10-03","si":["family","tropical"],"booking_route":"none needed - public swimming beaches","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"the park''s two sandy beaches - Public Beach 1, located off Highway 134, and Public Beach 2, in the Grand Glaize area of the park off Highway 54 west of the Grand Glaize bridge\", with restroom and change-house facilities, shady picnic areas, reservable shelters and playground equipment. \"Lifeguards are not provided. No pets are allowed on the beaches. Swim at your own risk.\""},{"name":"Ozark Caverns","source":"https://web.archive.org/web/20260611105517/https://mostateparks.com/park/lake-ozarks/cave-tours","accessed":"2026-10-03","si":["family","wildlife","adventure"],"booking_route":"Missouri State Parks reservation website, or at the park; 573-346-2500","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":2,"blurb":"A guided interpretive tour that \"lasts approximately one hour and is a half-mile round trip\"; \"Angel Showers, an unusual cave phenomenon, is a featured part of the Ozark Caverns tour. The never-ending shower of water seems to come out of the solid ceiling of rock.\" Adult $13, teen $10, child (6-12) $8, under 6 free, plus tax. Traditional tours run mid-May to mid-September and are \"Closed to traditional tours\" Sept. 16 through May 14. 573-346-2500."},{"name":"Park marinas and boat rentals","source":"https://web.archive.org/web/20260416171555/https://mostateparks.com/park/lake-ozarks/boating","accessed":"2026-10-03","si":["adventure","family","sailing"],"booking_route":"phone the marina, 573-348-1233 (Grand Glaize) or 573-302-1044 (Public Beach 1)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":3,"blurb":"\"You can also rent a boat or boat slip at one of two marinas in Lake of the Ozarks State Park, located at both public beaches\"; three paved ramps (four-lane at Grand Glaize Beach and Pa He Tsi, two-lane at Public Beach #1); launch $5 for vessels up to 30 feet, $10 over; \"There are no motor restrictions.\" Marina (GGB) 573-348-1233; Marina (PB1) 573-302-1044."},{"name":"Lake of the Ozarks State Park Campground","source":"https://web.archive.org/web/20260618084038/https://mostateparks.com/park/lake-ozarks/camping","accessed":"2026-10-03","si":["motoring","family","hiking","group"],"booking_route":"Missouri State Parks reservation website or 877-ICampMO (877-422-6766)","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":4,"blurb":"\"basic, electric and sewer/electric/water campsites, as well as three organized group camps and Pin Oak Facility\" in four year-round sections, \"50-amp electric sites available\"; showers Apr 1-Oct 31; a Camper Store near the entrance. \"You are now able to reserve your Missouri State Parks campsite up to 12 months in advance\"; weekend stays need a two-night minimum."},{"name":"The Outpost cabins","source":"https://web.archive.org/web/20260813113911/https://mostateparks.com/park/lake-ozarks/lodging","accessed":"2026-10-03","si":["family","hiking","wildlife"],"booking_route":"Missouri State Parks centralized reservation system or 1-877-422-6766","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":5,"blurb":"\"eight rustic log cabins for campers who want to experience the outdoors without pitching a tent\", built 1993 and upgraded 2011, each with a wood-burning stove, electricity, air conditioning, a dorm-size refrigerator and microwave, sleeping six; \"The rustic cabins do not have running water\". Weeknights $50 plus tax, weekends $55; \"No same-day registration is allowed\"."},{"name":"Lake of the Ozarks State Park yurts","source":"https://web.archive.org/web/20260813113911/https://mostateparks.com/park/lake-ozarks/lodging","accessed":"2026-10-03","si":["glamping","family"],"booking_route":"Missouri State Parks centralized reservation system or 1-877-422-6766","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":6,"blurb":"\"A yurt is a circular structure with a fabric cover, much like a tent, and a wooden frame making it strong and weathertight\", on a wooden platform with \"three large windows and a dome skylight\"; in campground sections 1 and 2, with a futon, bunk bed, refrigerator, microwave, air conditioner and heater; sleeps five, maximum six; available year-round; weeknights $50 plus tax, weekends $55."},{"name":"Coakley Hollow Trail","source":"https://web.archive.org/web/20260611105517/https://mostateparks.com/park/lake-ozarks/cave-tours","accessed":"2026-10-03","si":["hiking","family","wildlife"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"a 1-mile, self-guiding interpretive trail\" that \"begins and ends at the caverns parking lot\" and \"crosses a variety of habitats including a glade, fen and an Ozark spring branch. It is also a good place to see spring wildflowers.\" Trail booklets at the visitor center."},{"name":"The park''s thirteen trails","source":"https://web.archive.org/web/20260514011940/https://mostateparks.com/park/lake-ozarks/trails","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"none needed - free park trails","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"The state lists Aquatic Trail, Bluestem Knoll, Coakley Hollow, Fawns Ridge, Hidden Springs, Honey Run, Lake Trail, Lake View Bend, Rocky Top, Shady Ridge, Trail of Four Winds, White Oak and Woodland Trail; \"only certain activities are permitted on each trail\". The park also lists equestrian rental and stables, and ran Thursday Night Hikes on Rocky Top, Coakley Hollow, Lake and Lake View Bend in April 2026."},{"name":"Aquatic Trail","source":"https://web.archive.org/web/20260416171555/https://mostateparks.com/park/lake-ozarks/boating","accessed":"2026-10-03","si":["adventure","family"],"booking_route":"none needed - free; your own boat or a marina rental","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"Named on the park''s boating page - \"There is also an aquatic trail\" - and first on the state''s list of the park''s designated trails."},{"name":"Ozark Caverns wildlife","source":"https://web.archive.org/web/20260611105517/https://mostateparks.com/park/lake-ozarks/cave-tours","accessed":"2026-10-03","si":["wildlife","family"],"booking_route":"seen on the Ozark Caverns tour (see that jewel)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"Four species of salamanders, four species of bats, and 16 species of invertebrates live in Ozark Caverns\"; it \"is home to many small, secretive cave animals, such as the blind grotto salamander, which sometimes can be seen on cave tours.\" Visitors can also see claw marks \"left in the sediment fills by animals that sought shelter here thousand of years ago.\""},{"name":"Light jacket for 56-degree Ozark Caverns","source":"https://web.archive.org/web/20260611105517/https://mostateparks.com/park/lake-ozarks/cave-tours","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":4,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":11,"blurb":"The state''s own kit advice for the cave tour: \"The cave is 56 degrees Fahrenheit. A light jacket is recommended.\" Bags are not: \"accessories (purses, backpacks, strollers, etc.) are not allowed in the cave.\""},{"name":"Camping kit for the Outpost cabins","source":"https://web.archive.org/web/20260813113911/https://mostateparks.com/park/lake-ozarks/lodging","accessed":"2026-10-03","si":["family","hiking"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":12,"blurb":"The state tells cabin guests: \"bring your camping gear such as sleeping bags, pillows, cooking and eating utensils, water containers, and additional light sources such as lanterns. The rustic cabins do not have running water, so plan accordingly.\" \"Cooking and smoking are not allowed inside the cabins.\""},{"name":"Linens, sleeping bags and lanterns for the yurts","source":"https://web.archive.org/web/20260813113911/https://mostateparks.com/park/lake-ozarks/lodging","accessed":"2026-10-03","si":["glamping","family"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":13,"blurb":"For the yurts: \"bring your camping gear such as lanterns, cooking and eating utensils and water containers. The yurts do not have running water, so plan accordingly. Guests must bring their own linens and sleeping bags. Open-flame cooking is not allowed in the units.\" Griddles and Crock-Pots are allowed."},{"name":"Ha Ha Tonka State Park","source":"https://web.archive.org/web/20260926215832/https://mostateparks.com/park/ha-ha-tonka-state-park","accessed":"2026-10-03","si":["hiking","culture","family","adventure"],"booking_route":"none needed - state park","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"\"a geologic wonderland featuring sinkholes, caves, a huge natural bridge, sheer bluffs and Missouri''s 12th-largest spring. The ruins of a turn-of-the-century stone castle overlook these wonders and offer impressive views of the Lake of the Ozarks and Ha Ha Tonka Spring.\" \"A series of trails and boardwalks makes it easy for visitors to experience all the park has to offer\"."},{"name":"Bridal Cave","source":"https://bridalcave.com/","accessed":"2026-10-03","si":["family","romance","adventure"],"booking_route":"own website online tickets or (573) 346-2676","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":15,"blurb":"526 Bridal Cave Rd, Camdenton: \"Lake of the Ozarks'' Longest-Running Attraction\" and \"the ONLY cave in Missouri accessible by water\"; weddings and vow renewals in \"Nature''s Cathedral\"; \"The cave stays 60 degrees year-round.\" Adults (13+) $30, children (5-12) $16; lantern tours $39.95. Open year-round. (573) 346-2676."},{"name":"Lake Ozarks RV Resort","source":"https://www.lakeozarksrvresort.com/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"ResNexus booking engine from the own site","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":16,"blurb":"1726 State Hwy KK, Osage Beach: an \"All New RV Park\", pet- and family-friendly, with a pool and private showers, AT&T fiber wifi, golf cart rentals, an espresso bar and a pet park; it names the \"neighboring state park on the lake\". \"Stay a while or stay forever - long-term guests and travelers are welcome.\""},{"name":"Ozarks Landing RV Resort","source":"https://ozarkslanding.com/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"phone (573) 365-1122 - \"You cannot make or change any current, or future reservations through the contact form\"","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":17,"blurb":"398 Wood River Rd, Lake Ozark: \"RV sites with both 30 amp and 50 amp hookups\" and \"multiple tent sites\"; \"River Front RV Sites, Stocked Fishing Pond, Swimming Pool, Free Wi-fi\"; \"easy access off Hwy 54.\" (573) 365-1122."},{"name":"Lake of the Ozarks Linn Creek KOA","source":"https://funlake.com/places-to-stay/rvcampgrounds","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"KOA reservations 800-562-4786 (koa.com not fetched - HTTP 403)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":18,"blurb":"4171 US 54, Linn Creek - listed by the Lake of the Ozarks Convention & Visitor Bureau among the lake''s RV parks and campgrounds; 573-346-5490, reservations 800-562-4786. koa.com returned 403, so nothing else about the campground is stated here."},{"name":"Holiday Inn Express Osage Beach","source":"https://hotelguides.com/attraction-maps/missouri/map-hotels-near-lake-of-the-ozarks-state-park-mo.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"ihg.com (brand booking; not fetched)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":19,"blurb":"Listed by HotelGuides at \"4533 Osage Beach Parkway, US 54, Osage Beach, MO 65065\", 3.7 miles from Lake of the Ozarks State Park; the county tourism board lists it as \"Holiday Inn Express Osage Beach - Lake of the Ozarks\", 573-302-0330. IHG''s own page was not fetched, so nothing else about the property is stated here."},{"name":"The Lodge of Four Seasons","source":"https://4seasonsresort.com/","accessed":"2026-10-03","si":["golf","wellness","family","romance"],"booking_route":"own website (TravelClick booking engine) or 888-265-5500","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":20,"blurb":"315 Four Seasons Drive, Lake Ozark: \"A premier lakefront resort\" with indoor and outdoor pools, Spa Kyoto, \"Five on-site dining options\", a 250-seat theatre, marina access and two championship golf courses (The Cove and The Ridge) managed by Troon Golf. HotelGuides lists it 8 miles from the park. 888-265-5500. Not part of the Four Seasons hotel brand."},{"name":"Margaritaville Lake Resort Ozarks","source":"https://hotelguides.com/attraction-maps/missouri/map-hotels-near-lake-of-the-ozarks-state-park-mo.html","accessed":"2026-10-03","si":["family","romance"],"booking_route":"own website (not fetched)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":21,"blurb":"Listed by HotelGuides at \"494 Tan-Tar-A Drive, Osage Beach, MO 65065\", 8 miles from the park; the county tourism board lists its Windrose Marker 26 Lakeside Dining at the same address (573-348-3131). The resort''s own page was not fetched, so nothing else is stated here."},{"name":"Inn at Grand Glaize","source":"https://hotelguides.com/attraction-maps/missouri/map-hotels-near-lake-of-the-ozarks-state-park-mo.html","accessed":"2026-10-03","si":["family"],"booking_route":"phone 573-348-4731","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":22,"blurb":"5142 Osage Beach Parkway, Osage Beach, 573-348-4731 (county tourism board); HotelGuides lists it 4.8 miles from the park. No own page was fetched."},{"name":"Jeffrey''s Prime Rib & Lobster House","source":"https://funlake.com/dining/upscale-dining","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"phone 573-348-3463","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":23,"blurb":"1252 Hwy KK, Osage Beach, 573-348-3463 - listed under Upscale Dining by the Lake of the Ozarks Convention & Visitor Bureau."},{"name":"Michael''s Steak Chalet","source":"https://funlake.com/dining/upscale-dining","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"phone 573-348-3611","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":24,"blurb":"1440 Swiss Village, Osage Beach, 573-348-3611 - listed under Upscale Dining by the Lake of the Ozarks Convention & Visitor Bureau."},{"name":"Domenico''s Italian Restaurant","source":"https://funlake.com/dining/upscale-dining","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"phone 573-348-5335","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":25,"blurb":"4737 Osage Beach Pkwy, Osage Beach, 573-348-5335 - listed under Upscale Dining by the Lake of the Ozarks Convention & Visitor Bureau."},{"name":"Bentley''s Restaurant","source":"https://funlake.com/dining/upscale-dining","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"phone 573-365-5301","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":26,"blurb":"3100 Bagnell Dam Blvd., Lake Ozark, 573-365-5301 - listed under Upscale Dining by the Lake of the Ozarks Convention & Visitor Bureau."},{"name":"JB Hooks Restaurant & Lounge","source":"https://funlake.com/dining/upscale-dining","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"phone 573-365-3255","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":27,"blurb":"2260 Bagnell Dam Blvd., Lake Ozark, 573-365-3255 - listed under Upscale Dining by the Lake of the Ozarks Convention & Visitor Bureau."},{"name":"RedHead Lakeside Grill","source":"https://funlake.com/dining/casual-dining","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"phone 573-693-1525","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":28,"blurb":"1700 Yacht Club Drive, Osage Beach, 573-693-1525 - listed under Casual Dining by the Lake of the Ozarks Convention & Visitor Bureau."},{"name":"Tucker''s Shuckers Oyster & Tap","source":"https://funlake.com/dining/casual-dining","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"phone 573-365-9769","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":29,"blurb":"1339 Bagnell Dam Blvd, Lake Ozark, 573-365-9769 - listed under Casual Dining by the Lake of the Ozarks Convention & Visitor Bureau."},{"name":"Dog Days","source":"https://funlake.com/dining/casual-dining","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"phone 573-348-9797","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":30,"blurb":"1232 Jeffries Road, Osage Beach, 573-348-9797 - listed under Casual Dining by the Lake of the Ozarks Convention & Visitor Bureau."}],"faq":[{"q":"Can you camp at Lake of the Ozarks State Park?","a":"Yes: the park \"offers basic, electric and sewer/electric/water campsites, as well as three organized group camps and Pin Oak Facility\", in four year-round sections with \"50-amp electric sites available\". \"You are now able to reserve your Missouri State Parks campsite up to 12 months in advance\", online or at 877-ICampMO (877-422-6766).","source":"https://web.archive.org/web/20260618084038/https://mostateparks.com/park/lake-ozarks/camping","accessed":"2026-10-03"},{"q":"Are there cabins at Lake of the Ozarks State Park?","a":"Yes. The Outpost \"offers eight rustic log cabins for campers who want to experience the outdoors without pitching a tent\", each sleeping six, with electricity and air conditioning but no running water. \"The weeknight rate (Sunday* through Thursday) is $50 plus tax and the weekend rate is $55 plus tax.\" The park also rents yurts at the same rates.","source":"https://web.archive.org/web/20260813113911/https://mostateparks.com/park/lake-ozarks/lodging","accessed":"2026-10-03"},{"q":"Can you swim at Lake of the Ozarks State Park?","a":"Yes, at \"the park''s two sandy beaches - Public Beach 1, located off Highway 134, and Public Beach 2, in the Grand Glaize area of the park off Highway 54\". \"Lifeguards are not provided. No pets are allowed on the beaches. Swim at your own risk.\"","source":"https://web.archive.org/web/20260908031345/https://mostateparks.com/park/lake-ozarks/swimming","accessed":"2026-10-03"},{"q":"Is there a marina at Lake of the Ozarks State Park?","a":"Two: \"You can also rent a boat or boat slip at one of two marinas in Lake of the Ozarks State Park, located at both public beaches. Contact the marina at 573-348-1233\". The park also has three paved ramps; daily launch fees are \"$5 for vessels up to 30 feet in length and $10 for vessels over 30 feet\".","source":"https://web.archive.org/web/20260416171555/https://mostateparks.com/park/lake-ozarks/boating","accessed":"2026-10-03"},{"q":"What trails are at Lake of the Ozarks State Park?","a":"The state lists thirteen: Aquatic Trail, Bluestem Knoll, Coakley Hollow, Fawns Ridge, Hidden Springs, Honey Run, Lake Trail, Lake View Bend, Rocky Top, Shady Ridge, Trail of Four Winds, White Oak and Woodland Trail, noting that \"only certain activities are permitted on each trail.\"","source":"https://web.archive.org/web/20260514011940/https://mostateparks.com/park/lake-ozarks/trails","accessed":"2026-10-03"},{"q":"What is there to do at Lake of the Ozarks State Park?","a":"\"Swim, fish, boat or simply take in the view from a shady campsite or picnic area overlooking the Lake of the Ozarks.\" On shore, \"hikers, backpackers, equestrians and bicyclists can wind through open woodlands, sunny glades, small springs and streams to blufftop views\"; \"Water enthusiasts can make use of the park''s two swimming beaches, boat rentals and paved boat ramps.\" Ozark Caverns tours run in summer.","source":"https://web.archive.org/web/20260317054822/https://mostateparks.com/park/lake-ozarks-state-park","accessed":"2026-10-03"},{"q":"Where is Lake of the Ozarks State Park?","a":"The park office is at \"403 Highway 134, Brumley, MO 65017\" (573-348-2694). Its two beaches are off Highway 134 and off Highway 54 \"west of the Grand Glaize bridge\".","source":"https://web.archive.org/web/20260317054822/https://mostateparks.com/park/lake-ozarks-state-park","accessed":"2026-10-03"},{"q":"How big is Lake of the Ozarks State Park?","a":"\"it is the largest state park in Missouri\", covering \"17,666.18 acres (7,149.25 ha)\" with \"85 miles (137 km) of shoreline on the lake\".","source":"https://en.wikipedia.org/wiki/Lake_of_the_Ozarks_State_Park","accessed":"2026-10-03"},{"q":"Is Lake of the Ozarks State Park dog friendly?","a":"Leashed dogs are welcome in the campground: \"We recommend no more than two dogs per campsite. Pets must be supervised and kept on leashes no longer than 10 feet at all times.\" They are not allowed \"in public swimming areas\", and the beach page says \"No pets are allowed on the beaches.\" Outpost Cabins 2, 4 and 7 and Yurts A and B take up to two dogs under Cabins for Canines.","source":"https://web.archive.org/web/20260618084038/https://mostateparks.com/park/lake-ozarks/camping","accessed":"2026-10-03"}],"seo":{"meta_title":"Lake of the Ozarks State Park: Beaches, Caverns & Camping | TravelWell","meta_description":"Missouri''s largest state park: two lake beaches, two marinas, Ozark Caverns, 13 trails, campsites booked 12 months ahead, cabins, yurts and stays nearby.","slug":"lake-of-the-ozarks-state-park-missouri","primary_keyword":"Lake of the Ozarks State Park","jsonld_type":"TouristDestination"},"hero":{"query":"Lake of the Ozarks State Park beach cove"}}'::jsonb, 63)
