insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('big-bend-texas', '12A', 'Big Bend National Park', 'United States', 'Chisos peaks above Rio Grande canyons', 'future', 'verified', 'mountainValley', 'Texas', '{"hiking","adventure","glamping","wildlife","culture","parks"}', '{"remote","rugged","wild","dramatic"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Santa Elena Canyon Trail","source":"https://www.nps.gov/bibe/planyourvisit/river_hikes.htm","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"none needed - park trail (park entrance fee applies)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"1.7 miles round trip, MODERATE: \"This trail leads into the mouth of stunning Santa Elena Canyon.\" It crosses Terlingua Creek, climbs a steep sandy bank and paved steps to a vista point, then descends to the water''s edge inside the canyon."},{"name":"Lost Mine Trail","source":"https://www.nps.gov/bibe/planyourvisit/mountain_hikes.htm","accessed":"2026-10-03","si":["hiking","adventure","wildlife"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"4.8 miles round trip, MODERATE, in the Chisos Mountains: \"This trail serves as an outstanding introduction the flora and fauna of the Chisos Mountains.\""},{"name":"Window Trail","source":"https://www.nps.gov/bibe/planyourvisit/mountain_hikes.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"5.6 miles round trip, MODERATE, from the Chisos Basin: \"This trail descends through Oak Creek Canyon to the Window pour-off which frames panoramic desert vistas.\""},{"name":"Hot Springs Historic Trail","source":"https://www.nps.gov/bibe/planyourvisit/river_hikes.htm","accessed":"2026-10-03","si":["culture","wellness","hiking","family"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"1 mile round trip, EASY: the path passes \"remains of a resort, pictographs, homestead, and hot springs\"; the spring water reaches 105°F and is popular for soaking. It may be inaccessible when the river runs high."},{"name":"Emory Peak","source":"https://www.nps.gov/bibe/planyourvisit/mountain_hikes.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"10.0 miles round trip, STRENUOUS: \"The 360° view from Emory Peak, the highest point in the park, is superb.\""},{"name":"Night skies of Big Bend","source":"https://www.nps.gov/bibe/planyourvisit/stargazing.htm","accessed":"2026-10-03","si":["adventure","romance","family"],"booking_route":"none needed - free ranger programs; check the weekly Ranger Program Schedule","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"\"Big Bend is one of the best places in North America to enjoy a truly dark sky\"; International Dark Sky Park since 2012, with \"the least light pollution of any other national park unit in the lower 48 states.\" Rangers and volunteers run free night-sky programs, star parties and moonlight walks on the weekly schedule."},{"name":"South Rim","source":"https://www.nps.gov/bibe/planyourvisit/mountain_hikes.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed for a day hike; overnight needs a backcountry permit","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"12-14.5 miles round trip, STRENUOUS: \"This challenging trail is well worth the 2,000 foot gain, as midway are the stunning vistas from the South Rim.\""},{"name":"Boquillas Crossing Port of Entry","source":"https://www.nps.gov/bibe/planyourvisit/border_travel.htm","accessed":"2026-10-03","si":["culture","adventure"],"booking_route":"none needed - walk-up port of entry; passport required (\"A passport is required for entry into Mexico\" - nps.gov/bibe basicinfo)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"A pedestrian-only port of entry into Mexico: \"As of 11/1/25: Until further notice, the Boquillas Crossing Port of Entry will be open Friday through Monday, 9:00 am through 4:00 pm.\" Visitors check in with Mexican immigration on arrival; handcrafted purchases are processed at the port, but rocks, minerals, archaeological items and food cannot be brought back. \"Pets are not allowed to go into Mexico at the Boquillas Port of Entry.\""},{"name":"Boquillas Canyon Trail","source":"https://www.nps.gov/bibe/planyourvisit/river_hikes.htm","accessed":"2026-10-03","si":["hiking","culture"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"1.4 miles round trip, MODERATE: \"The Boquillas Canyon trail climbs from the parking to the top of a cliff overlooking the Rio Grande\", past mortar holes left by early inhabitants, then down to where the canyon walls meet the river."},{"name":"Chisos Mountains Lodge","source":"https://www.nps.gov/bibe/planyourvisit/lodging.htm","accessed":"2026-10-03","si":["hiking","senior","family"],"booking_route":"own website booking (chisosmountainslodge.com) or phone (855) 765-1324","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":10,"blurb":"\"The lodge is open year-round, and is the only lodging available within Big Bend National Park\"; it \"offers a variety of rooms and cottages, plus a gift shop, camper store, and food truck\", operated by Aramark. Reservations (855) 765-1324 or chisosmountainslodge.com."},{"name":"Chisos Basin Campground","source":"https://www.nps.gov/bibe/planyourvisit/camping.htm","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"Recreation.gov or 1-877-444-6777","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":11,"blurb":"In the centre of the park in the Chisos Mountains: \"Open. Reservations REQUIRED.\" NPS-operated, with drinking water and restrooms. $16 per night per site ($8 with a Senior or Access pass); most sites \"reservable up to 6 months in advance, and 1/3 up to 14 days in advance.\" \"Wood fires and ground fires are NOT allowed anywhere in the park.\""},{"name":"Rio Grande Village Campground","source":"https://www.nps.gov/bibe/planyourvisit/camping.htm","accessed":"2026-10-03","si":["wildlife","family","motoring"],"booking_route":"Recreation.gov or 1-877-444-6777","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":12,"blurb":"On the east side near the Rio Grande: \"OPEN. Reservations REQUIRED.\" NPS-operated, with drinking water and restrooms; $16 per night per site ($8 with a Senior or Access pass). Gasoline and a camp store are at Rio Grande Village."},{"name":"Rio Grande Village RV Park","source":"https://www.nps.gov/bibe/planyourvisit/camping.htm","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"phone 855-765-1324 (Aramark)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":13,"blurb":"The park''s only hookup sites: operated by Aramark, \"25 with full hookups\", maximum length 38 feet; reservations 855-765-1324. The lodge site describes it as a place to \"Stay under the clear night skies at the East most side of the park by the Rio Grande River.\""},{"name":"Cottonwood Campground","source":"https://www.nps.gov/bibe/planyourvisit/camping.htm","accessed":"2026-10-03","si":["wildlife","hiking"],"booking_route":"Recreation.gov or 1-877-444-6777 when open","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":14,"blurb":"On the west side near the Rio Grande, NPS-operated with drinking water and restrooms; status \"Closed for summer\" on the read date. $16 per night per site ($8 with a Senior or Access pass)."},{"name":"Backcountry permits and river trips","source":"https://www.nps.gov/bibe/planyourvisit/camping.htm","accessed":"2026-10-03","si":["adventure","hiking","motoring"],"booking_route":"in person at Panther Junction Visitor Center","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":15,"blurb":"\"A backcountry permit is required for all backcountry camping and river trips\" - $10 per night ($5 with a Senior or Access pass). On the read date, \"until further notice all backcountry campsites can only be obtained in person at Panther Junction Visitor Center\", including the Old Maverick, River Road and Old Ore Road sites. Group limit 15."},{"name":"Grapevine Hills Trail to Balanced Rock","source":"https://www.nps.gov/bibe/planyourvisit/desert_hikes.htm","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":16,"blurb":"2.2 miles round trip, MODERATE: \"This trail leads to a group of balanced rocks in the heart of the Grapevine Hills.\" \"The road is very rough and REQUIRES a sturdy High Clearance Vehicle.\""},{"name":"Boot Canyon Trail","source":"https://www.nps.gov/bibe/planyourvisit/mountain_hikes.htm","accessed":"2026-10-03","si":["wildlife","hiking"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":17,"blurb":"3.5 miles round trip (6 miles to the South Rim), STRENUOUS: \"Boot Canyon is a great place to look for Colima Warblers.\""},{"name":"Window View Trail","source":"https://www.nps.gov/bibe/planyourvisit/mountain_hikes.htm","accessed":"2026-10-03","si":["senior","family","hiking"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":18,"blurb":"0.3 miles round trip, EASY: \"This easy, paved wheelchair accessible trail circles a low hill with excellent views of the mountain peaks surrounding the Chisos Basin.\""},{"name":"Rio Grande Village Nature Trail","source":"https://www.nps.gov/bibe/planyourvisit/river_hikes.htm","accessed":"2026-10-03","si":["wildlife","family","senior"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":19,"blurb":"0.75 mile loop, EASY: \"The first 100 yards is wheelchair accessible and crosses a boardwalk through a spring-fed wetland\"; it then climbs a limestone hill with panoramic views of the Rio Grande - a sunset and wildlife-watching walk."},{"name":"Lower Burro Mesa Pour-off Trail","source":"https://www.nps.gov/bibe/planyourvisit/desert_hikes.htm","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":20,"blurb":"1 mile round trip, EASY: \"This trail leads through a gravel drainage, and ends in a narrow box canyon.\""},{"name":"Kit for desert heat and sun","source":"https://www.nps.gov/bibe/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"affiliate retail referral (REI.com via AvantLink; Amazon Associates) - nothing is sold by the park","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":21,"blurb":"The park''s own list: \"Carry plenty of water (at least one gallon per person, per day)\"; \"Wear a hat, long pants, long-sleeved shirt, and sun screen when hiking\"; \"A packable shade umbrella can provide welcome shade during the day.\" The NPS warns \"Fluid/electrolyte loss can exceed 2 quarts per hour if you hike uphill in direct sunlight\" and treats heat illness with \"salty foods\" and \"sports drinks with electrolytes\"."},{"name":"Kit for navigation and emergencies","source":"https://www.nps.gov/bibe/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","adventure","motoring"],"booking_route":"affiliate retail referral (REI.com via AvantLink; Amazon Associates) - nothing is sold by the park","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":22,"blurb":"The park''s own carry list: a \"Flashlight\", \"First aid kit\", \"Map and compass\" and a \"Signaling device (mirror and whistle)\". It warns that \"many GPS and app mapping services do not work well within this remote area\" and recommends paper maps."},{"name":"Big Bend Chuck Wagon","source":"https://visitbigbend.com/places/big-bend-chuck-wagon/","accessed":"2026-10-03","si":["culinary","family","hiking"],"booking_route":"walk-up food truck","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":23,"blurb":"\"The food truck at Chisos Mountains Lodge in the Chisos Basin of Big Bend National Park\" that \"serves Americana flavors for breakfast, lunch, and dinner while visitors are in the park.\" Daily 7:00 AM to 3:00 PM; hours may vary."},{"name":"Big Bend Ranch State Park","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch","accessed":"2026-10-03","si":["adventure","hiking","glamping"],"booking_route":"texasstateparks.reserveamerica.com or (512) 389-8900","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":24,"blurb":"\"Texas'' biggest state park\" along the Rio Grande, with an east entrance near Terlingua and a west entrance near Presidio: \"rugged mountains, steep canyons, amazing views, unparalleled night skies, and solitude in a high desert setting.\" Drive-up and hike-in primitive sites, equestrian sites and the Sauceda Bunkhouse; \"We often reach capacity; reservations are highly recommended.\" Entry $5 daily for ages 13+."},{"name":"Camp Elena","source":"https://visitbigbend.com/places/camp-elena/","accessed":"2026-10-03","si":["glamping","romance","wellness"],"booking_route":"own website booking (ResNexus portal on campelena.com)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":25,"blurb":"\"Camp Elena offers back-to-the-wild luxury glamping in the heart of Big Bend, located just 9.5 miles from Big Bend National Park\": 5 studio tents and 3 suite tents, safari-style, each with en suite kitchen, full bathroom, fire pit and private deck, with views of the Chisos and Christmas Mountains. 40 ET Rd, Terlingua."},{"name":"Lajitas Golf Resort and Spa","source":"https://visitbigbend.com/places/lajitas-golf-resort-and-spa/","accessed":"2026-10-03","si":["golf","romance","wellness"],"booking_route":"own website (lajitasgolfresort.com) or 1-877-525-4827","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":26,"blurb":"A 27,000-acre resort \"positioned between Big Bend National Park and Big Bend State Park\": 126 rooms across the Badlands Hotel, Cavalry Post, La Cuesta, Officers Quarters, cottages, condos and villas; Black Jack''s Crossing golf course; Agave Spa; an equestrian center, shooting sports and the Maverick Ranch RV Park. 21701 FM 170, Lajitas; 432-424-5000."},{"name":"Far Flung Outdoor Center","source":"https://www.bigbendfarflung.com/","accessed":"2026-10-03","si":["adventure","family","hiking"],"booking_route":"own website BOOK NOW portal or phone 432-371-2633","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear","stay"],"draw_rank":27,"blurb":"Terlingua river and Jeep outfitter: Half-Day Float, One-Day Canyon Float, Boquillas River Trip and 3- and 4-day float trips; guided Jeep and ATV tours; canoe rentals and gear for self-guided river trips, with shuttles; the Big Bend Casitas with pool and hot tub. 23310 FM 170; 432-371-2633."},{"name":"Desert Sports","source":"https://www.desertsportstx.com/","accessed":"2026-10-03","si":["sports","adventure","hiking"],"booking_route":"walk-in shop / phone 1-432-371-2727","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","shop","activities"],"draw_rank":28,"blurb":"Terlingua bike shop and gear store, 29 years in business: \"Desert Sports rents quality mountain bikes\" with shuttle options, and stocks \"cycling and outdoor essentials. Maps, trail info and experienced mechanics\" plus expanded outdoor gear. Guided river tours and boat rentals ended May 31, 2025 - river customers are referred to Far Flung''s outpost. 22937 FM 170; 1-432-371-2727."},{"name":"Starstruck Glamping","source":"https://visitbigbend.com/places/starstruck-glamping/","accessed":"2026-10-03","si":["glamping","romance"],"booking_route":"own website (starstruckglamping.com) or phone 432-300-6623","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":29,"blurb":"\"Luxury glamping experience near Big Bend National Park, featuring geodesic dome accommodations on 80 private acres\": 4 off-grid, solar-powered domes, each with en suite bathroom, kitchen, outdoor grill, fire pit and telescope, and \"Cold air conditioning and mini-split heating and cooling for year-round comfort.\" 1601 Loma Prieta Rd; 432-300-6623."},{"name":"Paisano Village RV Park & Inn","source":"https://visitbigbend.com/places/paisano-village-rv-park-inn/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"own website (paisanovillagervparkandinn.com) or phone 432-371-2057","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":30,"blurb":"\"Study Butte''s newest RV park and inn, offering a laid-back and quiet experience for travelers visiting Big Bend National Park\": full-hookup sites with electricity, water and sewer, inn rooms, free WiFi and EV charging. 53690 TX-118, Study Butte; 432-371-2057."},{"name":"Terlingua Ranch Lodge","source":"https://visitbigbend.com/places/terlingua-ranch-lodge/","accessed":"2026-10-03","si":["adventure","motoring","family"],"booking_route":"own website (terlinguaranch.com) or phone 432-371-3146","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":31,"blurb":"\"Terlingua Ranch Lodge offers a uniquely remote Far West Texas vacation experience, providing rustic yet comfortable accommodations in one of the most scenic and least crowded corners\": cabin rooms, full-hookup RV sites (pull-through and back-in), tent campgrounds, a horse corral, and the Bad Rabbit Cafe. 16000 Terlingua Ranch Rd; 432-371-3146."},{"name":"Marathon Motel & RV Park","source":"https://visitbigbend.com/places/marathon-motel-rv-park/","accessed":"2026-10-03","si":["motoring","adventure"],"booking_route":"own website (marathonmotel.com) or phone 432-386-4241","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":32,"blurb":"\"Historic accommodation destination established in 1940 and recently renovated\", known as the Astronomy Motel, on 10 acres: 10 motel rooms in four duplex cabins, 29 full-hookup RV sites with 30/50 amp, water, sewer and cable, tent sites and a dump station. 701 Hwy 90, Marathon; 432-386-4241."},{"name":"The Gage Hotel","source":"https://gagehotel.com/","accessed":"2026-10-03","si":["culture","romance","culinary","wellness"],"booking_route":"own website (gagehotel.com) or 1 (800) 884-GAGE","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":33,"blurb":"Marathon, built 1927: \"Surrounded by the pristine beauty of Big Bend country, the Gage offers unique accommodations with laid-back luxury, gracious hospitality, superior dining, and one of the most iconic bars in Texas\" - the Historic Hotel, Los Portales, Captain Shepard House and Casitas; 12 Gage restaurant, White Buffalo Bar, V6 Coffee Bar, Brick Vault Brewery & Barbecue and Gage Spa. Listed in the National Register of Historic Places. 1 (800) 884-GAGE."},{"name":"Terlingua","source":"https://visitbigbend.com/terlingua/","accessed":"2026-10-03","si":["culture","adventure"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":34,"blurb":"\"One of the most iconic communities in the Big Bend region\", \"Known for its ghost town history, dramatic desert setting, and unmistakable personality\"; its identity is \"closely tied to the mining era that once shaped this region\". It sits near Study Butte \"just outside Big Bend National Park\", on the scenic drive to Lajitas."},{"name":"Study Butte","source":"https://visitbigbend.com/terlingua/","accessed":"2026-10-03","si":["motoring","adventure"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":35,"blurb":"The \"practical basecamp for exploring the Big Bend region\", \"at the junction of TX 118 and FM 170, just outside the western entrance area of Big Bend National Park\", adding \"practical conveniences, travel basics, and additional lodging options.\""},{"name":"Marathon","source":"https://visitbigbend.com/marathon/","accessed":"2026-10-03","si":["culture","wildlife","senior"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":36,"blurb":"\"Marathon sits along the eastern approach to Big Bend and serves as a peaceful gateway town for travelers heading deeper into far West Texas\"; \"known for its historic charm, wide-open scenery, and slower pace\", with \"exceptional night skies\" and birding around Marathon Post Park. The Gage Hotel''s 1980 restoration reshaped the town."},{"name":"Starlight Theatre Restaurant and Saloon","source":"https://www.thestarlighttheatre.com/","accessed":"2026-10-03","si":["culinary","culture","entertainment","group"],"booking_route":"walk-in; group reservations 432.371.3400","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":37,"blurb":"631 Ivey Road in the Terlingua Ghost Town: \"The finest dining establishment in the entire Terlingua Ghost Town, offering a fine selection of gourmet dishes and rollicking drinks, plus the best in live entertainment.\" Sunday-Friday 5:00 pm - 12:00 am, Saturday to 1:00 am; group reservations for 10 or more. 432.371.3400."},{"name":"DB''s Rustic Iron BBQ","source":"https://visitbigbend.com/places/dbs-rustic-iron-bbq/","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in / phone 432-371-3939","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":38,"blurb":"\"Award-winning Central Texas-style barbecue\" serving the Terlingua Ghost Town area since 1993, slow-smoked on offset smokers with post oak. 10 Terlingua Ghost Town Rd; Wednesday through Monday, 11 AM until sellout. 432-371-3939."},{"name":"Long Draw Pizza","source":"https://visitbigbend.com/places/long-draw-pizza/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in / phone (432) 371-2608","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":39,"blurb":"Terlingua, family-owned since 2003, \"serving what many consider the best pizza in the Big Bend region\" - handcrafted pizzas, wings, salads and calzones with an outdoor patio. 22720 FM 170; Wednesday-Monday 4 PM-9 PM, Friday-Saturday to 10 PM. (432) 371-2608."},{"name":"Chili Pepper Cafe","source":"https://visitbigbend.com/places/chili-pepper-cafe/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in / phone 432-371-2233","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":40,"blurb":"\"Chili Pepper Cafe is a Tex-Mex restaurant\" at 100 S Hwy 118, Study Butte; \"Typically open daily from about 8:00 AM to 9:00 PM. Call 432-371-2233 to confirm\"."},{"name":"Espresso y Poco Mas","source":"https://visitbigbend.com/places/espresso-y-poco-mas/","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":41,"blurb":"\"Espresso and a Little Bit More\": Terlingua''s breakfast and brunch stop at La Posada Milagro Guesthouse, 45 Milagro Way; daily 7:30 AM to 2 PM. 432-371-3044."},{"name":"Candelilla Cafe","source":"https://visitbigbend.com/places/candelilla-cafe/","accessed":"2026-10-03","si":["culinary","romance","golf"],"booking_route":"phone 432-424-5032 (dinner reservations required)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":42,"blurb":"\"Fine-dining restaurant at Lajitas Golf Resort\" serving \"breakfast, lunch, and dinner\" with \"panoramic views\" and locally sourced ingredients when available. Open to the public until 5:00 PM; after 5:00 PM resort members and registered guests only, and \"Dinner reservations are required after 5:00 PM\" with a $50 per-person late-cancellation fee. 432-424-5032."},{"name":"12 Gage Restaurant","source":"https://gagehotel.com/","accessed":"2026-10-03","si":["culinary","romance","wine"],"booking_route":"via The Gage Hotel, 1 (800) 884-GAGE","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":43,"blurb":"At The Gage Hotel in Marathon: \"award-winning, authentic Texas cuisine\", beside the White Buffalo Bar, which Texas Monthly placed among its \"Top Hotel Bars\"."}],"faq":[{"q":"Can you camp at Big Bend National Park?","a":"Yes. Chisos Basin and Rio Grande Village campgrounds are open with \"Reservations REQUIRED\" (Cottonwood was \"Closed for summer\" on the read date), at \"$16 per night per site ($8 per night with Senior or Access pass)\", booked at www.recreation.gov or 1-877-444-6777. The Aramark-run Rio Grande Village RV Park has 25 full-hookup sites, and \"A backcountry permit is required for all backcountry camping and river trips.\"","source":"https://www.nps.gov/bibe/planyourvisit/camping.htm","accessed":"2026-10-03"},{"q":"What is the Big Bend National Park entrance fee?","a":"$30 per private vehicle, $25 per motorcycle and $15 per individual on foot or bicycle, each \"valid for 7 days\"; the Big Bend Annual Pass is $55 and is \"Good for one year from purchase date.\"","source":"https://www.nps.gov/bibe/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Do you need reservations for Big Bend National Park?","a":"Not to enter, but developed campground reservations are \"required\" through www.recreation.gov or 1-877-444-6777; most sites at Rio Grande Village and Chisos Basin are \"reservable up to 6 months in advance, and 1/3 up to 14 days in advance.\"","source":"https://www.nps.gov/bibe/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Do you need a passport for Big Bend National Park?","a":"Not for the park itself - only to cross into Mexico: \"A passport is required for entry into Mexico.\" The Boquillas Crossing Port of Entry is pedestrian only, and \"A valid passport is required for everyone to cross.\"","source":"https://www.nps.gov/bibe/planyourvisit/basicinfo.htm","accessed":"2026-10-03"},{"q":"Can you take dogs to Big Bend National Park?","a":"Only where a car can go: \"Your pet can only go where your car can go.\" \"Pets are not allowed on trails, off roads, or on the river\", must be on a leash no longer than six feet (or caged) at all times, and \"Pets are not allowed to go into Mexico at the Boquillas Port of Entry.\"","source":"https://www.nps.gov/bibe/planyourvisit/pets.htm","accessed":"2026-10-03"},{"q":"What is the nearest airport to Big Bend National Park?","a":"\"The nearest airports served by major airlines are located in Midland/Odessa, Texas (235 miles from park headquarters) and El Paso, Texas (330 miles from park headquarters).\" The nearest Amtrak station and Greyhound stop are in Alpine, 100 miles from park headquarters, and \"There is no public transportation in the immediate vicinity of the park.\"","source":"https://www.nps.gov/bibe/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"Can you swim at Big Bend National Park?","a":"Not in the river: \"Actual swimming in the Rio Grande is NOT recommended, as undercurrents, deep holes, sharp objects, micro-organisms, and other hazards exist.\"","source":"https://www.nps.gov/bibe/faqs.htm","accessed":"2026-10-03"},{"q":"When is the best time to visit Big Bend National Park?","a":"The NPS does not name a best month; it says \"Big Bend''s busy season is generally November through April\", with peaks during holidays and \"mid-January through mid-April\", and advises planning ahead for those times.","source":"https://www.nps.gov/bibe/planyourvisit/basicinfo.htm","accessed":"2026-10-03"},{"q":"What should I bring to Big Bend National Park?","a":"\"Carry plenty of water (at least one gallon per person, per day)\"; \"Wear a hat, long pants, long-sleeved shirt, and sun screen when hiking\"; and carry a flashlight, first aid kit, map and compass, and a signaling device (mirror and whistle). \"A packable shade umbrella can provide welcome shade during the day.\"","source":"https://www.nps.gov/bibe/planyourvisit/safety.htm","accessed":"2026-10-03"},{"q":"Can you fish at Big Bend National Park?","a":"\"Fishing is allowed in the Rio Grande with a free permit issued from a visitor center.\"","source":"https://www.nps.gov/bibe/faqs.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Big Bend National Park: Trails, Camping & Where to Stay | TravelWell","meta_description":"Santa Elena Canyon, the Chisos Mountains, Hot Springs and dark skies, with park campgrounds, Terlingua glamping, RV parks and desert kit the NPS says to bring.","slug":"big-bend-national-park-texas","primary_keyword":"Big Bend National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Big Bend National Park Santa Elena Canyon"}}'::jsonb, 64),
  ('guadalupe-mountains-texas', '12A', 'Guadalupe Mountains National Park', 'United States', 'Top of Texas and McKittrick Canyon', 'future', 'verified', 'mountainValley', 'Texas', '{"hiking","adventure","wildlife","culture","motoring","parks"}', '{"remote","rugged","wild","dramatic"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Guadalupe Peak Trail","source":"https://www.nps.gov/thingstodo/gumo_hike_guadalupe_peak.htm","accessed":"2026-10-03","si":["hiking","adventure","expedition"],"booking_route":"none needed - park entrance pass ($10 per person 16+) at the visitor center or trailhead self-pay station","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"Climb to the \\\"Top of Texas\\\"\": 8.4 miles round trip, 3,000 feet of gain, six to eight hours, to \"the highest point in the state of Texas (8,751 feet / 2,667 meters)\". \"This is the most popular hike in the park and is often crowded on the weekends.\" Starts at the Pine Springs Trailhead; a backcountry campsite sits on the false summit (permit required). \"Winds in excess of 40 miles per hour are not uncommon\" on top."},{"name":"McKittrick Canyon","source":"https://www.nps.gov/gumo/planyourvisit/mckittrick.htm","accessed":"2026-10-03","si":["hiking","wildlife","family"],"booking_route":"none needed - day use with a park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"Described as the \"most beautiful spot in Texas\"; \"Thousands of visitors come... especially during the latter part of October or early November for the sensational fall colors\" - \"brilliant reds, subtle yellows, and deep browns\" against century plants and prickly pear. Day-use only, \"8:00 a.m. - 5:00 p.m. Mountain Time\"; the highway gate \"is locked each evening.\""},{"name":"Fall colors in the Guadalupes","source":"https://home.nps.gov/thingstodo/gumo-fall-colors.htm","accessed":"2026-10-03","si":["hiking","wildlife","senior"],"booking_route":"none needed - park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"Bright fall colors of deciduous trees are not common in the southwest\", but maples thrive at elevation, \"usually from mid-October to Mid-November\"; the best viewing is \"the last week of October and the first week of November.\" \"All significant fall colors displays in the park require hiking in and out\"; \"Little to no fall colors are visible on the Guadalupe Peak Trail.\""},{"name":"Devil''s Hall","source":"https://www.nps.gov/thingstodo/gumo_hike_devils_hall_trail.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"4.2 miles round trip, 548 feet, 3-5 hours, STRENUOUS: a rocky wash leads to \"an impressive natural rock staircase leading to a \\\"hallway\\\" formed by steep canyon walls.\" \"The wash portion of the route requires the hiker to scramble over large boulders\"; \"Do not attempt to climb in the wash or canyon walls in wet or rainy conditions.\" A fall-colors hike \"from mid-October to mid-November\"."},{"name":"Pine Springs Campground","source":"https://www.nps.gov/gumo/planyourvisit/camping.htm","accessed":"2026-10-03","si":["hiking","motoring","family"],"booking_route":"Recreation.gov - \"reservable up to six months in advance\"","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":5,"blurb":"\"a simple, desert camping area situated in Pine Springs Canyon near the base of Guadalupe Peak\": 20 gravel walk-in tent sites and 13 paved RV sites; \"RVs and trailers 55 feet in length or longer are prohibited. ... There are no hook-ups and there is no dump station.\" Potable water and flush toilets; \"There are no showers available in the campground.\" Wood and charcoal fires prohibited; quiet hours 8:00 PM to 8:00 AM."},{"name":"Dog Canyon","source":"https://www.nps.gov/gumo/planyourvisit/dogcanyon.htm","accessed":"2026-10-03","si":["hiking","wildlife","adventure"],"booking_route":"Recreation.gov - campsites \"reservable up to six months in advance\"","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":6,"blurb":"\"a secluded, forested canyon on the north end of the park at an elevation of 6,300 feet\"; \"a 70-mile drive from the nearest town of Carlsbad, New Mexico and is 110 miles from the Pine Spring Visitor Center\" (allow two hours). Campground: 9 tent sites and 4 RV sites, \"no hookups, no dump station, no RV''s longer than 23 feet\", flush toilets, no showers; trails with \"relatively easy grades\" into the high country."},{"name":"Salt Basin Dunes","source":"https://www.nps.gov/gumo/planyourvisit/dunes.htm","accessed":"2026-10-03","si":["adventure","hiking","motoring"],"booking_route":"none needed - park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"On the remote west side: \"Gypsum grains form the bright-white dunes that cover about 2,000 acres and range from three feet high, heavily vegetated dunes at the south end of the area, to sixty feet high, largely non-vegetated dunes at the north end.\" Reached by the Dell City Agricultural Loop (FM 1437 and 1576) and the Williams Road."},{"name":"Pratt Cabin hike","source":"https://www.nps.gov/thingstodo/gumo_hiketoprattcabin.htm","accessed":"2026-10-03","si":["hiking","culture","family"],"booking_route":"none needed - park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"\"the shortest distance into the heart of the canyon\": 4.8 miles round trip, 2-4 hours, moderate, crossing the stream twice to the historic stone cabin, with picnic tables and a porch. \"Volunteers staff Pratt Cabin on occasion\"; the canyon gate \"closes daily at 5:00 p.m.\""},{"name":"The Notch","source":"https://www.nps.gov/thingstodo/gumo_hike_the_notch.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"9.0 miles round trip, 1,092 feet, 5-7 hours: past Pratt Cabin to the Grotto, \"an excellent picnic spot\", and Hunter Line Shack, then \"steep grades, and several switchbacks\" to a viewpoint with \"outstanding views of South McKittrick Canyon in both directions.\""},{"name":"McKittrick Ridge","source":"https://www.nps.gov/thingstodo/gumo_hike_mckittrick_ridge.htm","accessed":"2026-10-03","si":["adventure","hiking","expedition"],"booking_route":"none for a day hike; a Wilderness Use Permit for the overnight","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"the toughest hike in Texas\": 15.2 miles round trip and 2,700 feet from the McKittrick Canyon Trailhead (14.8 miles and 1,900 feet from Dog Canyon), \"two days and one night recommended\" at the McKittrick Ridge Wilderness Campground; \"No shuttle service runs between the two trailheads.\""},{"name":"Smith Spring Trail Loop","source":"https://www.nps.gov/thingstodo/gumo_hike_smith_springs_trail.htm","accessed":"2026-10-03","si":["wildlife","hiking","family"],"booking_route":"none needed - park entrance pass","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"2.3-mile loop, 402 feet, 1-2 hours, easy-moderate, from Frijole Ranch: paved to Manzanita Spring, then up to \"the heavily vegetated Smith Spring\" and its tiny waterfall - \"Look for birds, mule deer, and elk.\" \"The water sources along this trail provide excellent opportunities for bird watching throughout the year.\""},{"name":"Frijole Ranch History Museum","source":"https://www.nps.gov/gumo/planyourvisit/frijolerancharea.htm","accessed":"2026-10-03","si":["culture","family","wildlife","senior"],"booking_route":"none needed - free with park entry","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"\"a delightful oasis on the edge of the dry, lower slopes of the Guadalupe escarpment\": the old ranch headquarters \"displays the human history of the Guadalupes from Native Americans and the early ranching community to the establishment of a national park\", beside a one-room schoolhouse and spring house. 1½ miles northeast of the Pine Springs Visitor Center; picnic tables under large shade trees. \"Bring your binoculars.\""},{"name":"Pinery Trail and Butterfield Stage Station","source":"https://www.nps.gov/gumo/planyourvisit/accessibility.htm","accessed":"2026-10-03","si":["culture","senior","family"],"booking_route":"none needed - free paved trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"\"This 0.75 mile (1.2 km) round-trip paved trail leads to the ruins of a mid-1800s Butterfield Stagecoach Station\" from the Pine Springs Visitor Center; the ruins can also be reached off US 62/180. One of only two trails where leashed pets may walk."},{"name":"Williams Ranch Road","source":"https://www.nps.gov/thingstodo/gumo_drive_to_williams_ranch.htm","accessed":"2026-10-03","si":["motoring","adventure","culture"],"booking_route":"free permit and gate key at the Pine Springs Visitor Center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"High-clearance 4WD only: \"A no-fee permit and a gate key is required\" from the Pine Springs Visitor Center; the gate is 8.3 miles west on US 62/180, then 7.3 miles one way, about an hour, to \"a single, well-preserved house, long since abandoned\". \"Be prepared with plenty of water, a jack, and good spare tire\"; day use only; \"OFF ROAD DRIVING IS PROHIBITED\"."},{"name":"Wilderness backpacking permits","source":"https://www.nps.gov/gumo/planyourvisit/backcountry-use-permits.htm","accessed":"2026-10-03","si":["adventure","hiking","expedition"],"booking_route":"Recreation.gov reservation up to three months ahead, converted to a permit in person; or walk-up","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":15,"blurb":"\"A permit is required year-round for all overnight stays in the Wilderness\", issued in person at the Pine Springs Visitor Center: \"$6.00 non refundable reservation fee\" per permit plus \"$6 per person per night\". Walk-up permits 8:00 a.m. to noon daily; hikers must show \"a minimum of one landfill-safe commercial toilet bag system per person per night\". Interagency passes do not apply."},{"name":"Frijole Horse Corral Campground","source":"https://www.nps.gov/gumo/planyourvisit/camping.htm","accessed":"2026-10-03","si":["adventure","group"],"booking_route":"Recreation.gov (\"Reservations can be made for camping and use of the horse corral campsites\")","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":16,"blurb":"\"located near the beginning of the Frijole Ranch Road, one mile north of Pine Springs\": \"corrals, tent pads, pit toilet, and trailer parking for group campers and horse users.\" Reservable with the park''s campsites."},{"name":"Pine Springs Visitor Center","source":"https://www.nps.gov/gumo/planyourvisit/visitorcenters.htm","accessed":"2026-10-03","si":["family","senior","culture"],"booking_route":"none needed - free","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":17,"blurb":"\"The Pine Springs area is the primary hub for most visits to the park\"; the visitor center \"is open daily\". Entrance passes are sold here by credit card, Wilderness permits are issued here, and the Guadalupe Peak trailhead is half a mile away. Mailing address 400 Pine Canyon, Salt Flat, TX 79847; 915-828-3251."},{"name":"Kit for Guadalupe Peak","source":"https://www.nps.gov/thingstodo/gumo_hike_guadalupe_peak.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"affiliate retail referral (REI.com via AvantLink; Amazon Associates) - nothing is sold by the park","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":18,"blurb":"The park''s own list for the peak: \"Bring plenty of water, at least one gallon per person, per day. Also come prepared with sunscreen, a hat, and protective clothing.\" \"Hikers should wear comfortable hiking boots with good traction\"; \"Trekking poles aid in stability\"; \"Bring enough warm clothing\"; for sunrise or sunset \"a head lamp or a flashlight\". \"When you consume half of the water you are carrying, turn around.\""},{"name":"The Eleven Essentials kit","source":"https://www.nps.gov/articles/000/gumo_11essentials.htm","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"affiliate retail referral (REI.com via AvantLink; Amazon Associates) - nothing is sold by the park","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":19,"blurb":"The park''s \"10 Essentials (plus one)\": navigation (\"Map, compass, and GPS system\"), sun protection (\"Sunglasses, sunscreen, and hat\"; \"Sun-protection clothing such as pants and long sleeve shirts\"), insulation (\"Jacket, hat, gloves, rain shell, and thermal underwear\"), illumination (\"Headlamps are the preferred light source\"), a first-aid kit, fire for a stove - and an eleventh, toiletries, to pack out waste."},{"name":"Commercial toilet bag kit","source":"https://www.nps.gov/thingstodo/gumo_human_waste_wilderness.htm","accessed":"2026-10-03","si":["hiking","adventure","expedition"],"booking_route":"affiliate retail referral (REI.com via AvantLink; Amazon Associates) - nothing is sold by the park","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":20,"blurb":"Required gear: \"The use of a landfill-safe commercial toilet bag system (such as Wag Bag, Restop II, etc.) is required for all overnight Wilderness permit holders\" - \"a minimum of one bag per person per night\", shown before the permit is issued. \"Due to the rocky nature of the soils and dry environment in the park, the digging and use of \\\"catholes\\\" for human waste is prohibited.\""},{"name":"Desert sun and wind kit","source":"https://www.nps.gov/gumo/planyourvisit/weather.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"affiliate retail referral (REI.com via AvantLink; Amazon Associates) - nothing is sold by the park","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":21,"blurb":"\"No matter the time of year, a wide-brimmed hat, comfortable clothing and sturdy walking shoes or boots are necessary for anyone planning to explore outdoors. Sunscreen is a must and hikers should always carry plenty of water; one gallon per person per day is recommended.\" Summer: \"clothing that protects from the sun\"; winter: \"temperatures vary from below freezing to above 80 degrees\", with gusts of 50-80 mph November-March."},{"name":"White''s City","source":"https://whitescitynm.com/attractions/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":22,"blurb":"The New Mexico gateway: \"located 4 miles or 6.4 km east of Carlsbad Caverns National Park\" and, by its own attractions page, \"31 Mi to Visitor''s Center & Entrance\" of Guadalupe Mountains. The NPS calls it the last place from New Mexico \"that offers gas, diesel, food and ice.\" Cavern Inn, RV park and campground, Cactus Cafe, grocery and post office, and the Walnut Canyon Water Park."},{"name":"White''s City RV Park","source":"https://whitescitynm.com/rv-campground/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"phone (575) 361-3665 or infowhitescity@gmail.com","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":23,"blurb":"19 Carlsbad Caverns Highway: \"water, sewer, and electric hookups as well as free Wi-Fi\", \"both pull-thru and back-in spots\" that \"can accommodate most any size RV or trailer\"; remodeled showers, laundry, covered picnic tables and fire rings. \"Calling ahead to reserve your spot is strongly encouraged.\" Accepts Good Sam, AARP and AAA. (575) 361-3665."},{"name":"White''s City Campground","source":"https://whitescitynm.com/rv-campground/","accessed":"2026-10-03","si":["family","hiking"],"booking_route":"phone (575) 361-3665","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":24,"blurb":"The tent side of the same park: \"a soft grassy area for each tent\", BBQ grills, a playground, showers and coin laundry, \"within walking distance of the shopping plaza at White''s City\"; it calls itself \"the closest campground to the Carlsbad Caverns.\""},{"name":"White''s City Cavern Inn","source":"https://whitescitynm.com/rooms-and-amenities/","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"own website rates and availability; phone (855) 516-1090","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":25,"blurb":"17 Carlsbad Cavern Hwy: King and Queen rooms with microwave, mini fridge and satellite TV; \"Handicap Accessible room available on Ground floor\"; pet-friendly rooms at \"$15 fee, per pet, per night\"; \"Grab n Go\" breakfast; the Pirate Ship Splash Pad and Walnut Canyon Water Park. It notes other hotels in Carlsbad \"are 25+ miles away from the park entrance\" (Carlsbad Caverns). (855) 516-1090 (Carlsbad Chamber listing)."},{"name":"Cactus Cafe","source":"https://whitescitynm.com/restaurant/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in / phone (575) 200-6774","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":26,"blurb":"White''s City: \"Delicious Southwestern American Cuisine\" - \"Our favorites include the menudo and the green chile enchiladas!\" Breakfast and lunch 7-3, \"unique, delicious, gourmet burgers\" and \"Ice Cold Beer\". (575) 200-6774."},{"name":"Carlsbad Caverns National Park","source":"https://whitescitynm.com/attractions/","accessed":"2026-10-03","si":["adventure","family","wildlife"],"booking_route":"Recreation.gov timed entry, 877-444-6777, plus an entrance pass at the park (nps.gov/cave, read 2026-10-03)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":27,"blurb":"White''s City''s neighbour, \"7 Mi to Visitor''s Center & Entrance\": \"Will Rogers called it the \\\"Grand Canyon with a roof on it\\\"\", with \"the amazing bat colony swarm leaving the cavern entrance every evening.\" The NPS: \"Timed Entry Tickets Required. Reservations strongly recommended\"; cavern entrance hours 9:30am - 2:30pm."},{"name":"Sitting Bull Falls","source":"https://whitescitynm.com/attractions/","accessed":"2026-10-03","si":["hiking","family","wellness"],"booking_route":"none needed - national forest day-use area (forest page returned 403)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":28,"blurb":"\"Fed by an underground spring, this oasis offers cool pools of water and the awesome Sitting Bull Falls\"; \"Day-use area only. Pavilions, picnic tables, water, and restrooms are available.\" The Carlsbad Chamber: \"a series of spring-fed waterfalls that fall 150 feet (45.7 m) to a large pool of water below.\""},{"name":"Guadalupe Ridge Trail","source":"https://www.carlsbadchamber.com/adventure","accessed":"2026-10-03","si":["adventure","hiking","expedition"],"booking_route":"none needed - permits per land agency (nps.gov/thingstodo/grt.htm, read 2026-10-03)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":29,"blurb":"The Carlsbad Chamber: \"a designated National Recreation Trail and at 100 miles (161 km) long, provides hikers and backpackers with a true wilderness experience in the Chihuahuan Desert and Guadalupe Mountains.\" It starts on Guadalupe Peak and ends in White''s City; 5-8 days to thru-hike, and part of the Carlsbad Caverns section is \"closed due to flood damage\" (NPS)."},{"name":"Living Desert Zoo and Gardens State Park","source":"https://www.carlsbadchamber.com/adventure","accessed":"2026-10-03","si":["wildlife","family"],"booking_route":"admission at the park (state parks page did not render its ticketing)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":30,"blurb":"Carlsbad: \"Visit this unique zoo dedicated to the wildllife of the Chihuahuan Desert\" - a New Mexico state park listed by the Carlsbad Chamber alongside the Pecos River beach area and The Flume, the river \"That Crosses Itself\"."},{"name":"Carlsbad, New Mexico","source":"https://www.carlsbadchamber.com/adventure","accessed":"2026-10-03","si":["motoring","family","culture"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":31,"blurb":"The nearest full-service city, 56 miles northeast by US 62/180 (NPS). Its chamber lists the Pecos River beach area (\"canoes, kayaks, and paddle boats are available for rental\"), Brantley Lake \"twelve miles North of Carlsbad\", the Carlsbad Museum and Art Center, and the closest free RV dump station the park names, \"off Canyon Street\". Chamber 575-887-6516."},{"name":"Carlsbad RV Park & Campground","source":"https://www.carlsbadrvpark.com/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"own website \"Book Now\" or phone 575-885-6333","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":32,"blurb":"4301 National Parks Highway, Carlsbad: \"RV sites, tent sites, and rustic cabins\", a gated park (\"Gates close at 6pm MST\"), store, pool, 24-hour laundry, restrooms and showers, four off-leash dog areas; \"No pets allowed in cabins.\" \"Reservations are Suggested.\" 1-575-885-6333."},{"name":"Bud''s Place RV Park","source":"https://www.carlsbadchamber.com/lodging","accessed":"2026-10-03","si":["motoring"],"booking_route":"phone (888) 204-4470 (clearskiesrvparks.com, not read)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":33,"blurb":"Listed by the Carlsbad Chamber at \"900 Standpipe Rd\", (888) 204-4470, linked to its operator Clear Skies RV Parks. Nothing else about the park is stated here; the operator page was not read."},{"name":"TownePlace Suites by Marriott Carlsbad","source":"https://web.archive.org/web/20260609210406/https://www.marriott.com/en-us/hotels/cnmts-towneplace-suites-carlsbad/overview/","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"marriott.com (brand booking)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":34,"blurb":"311 Pompa St., Carlsbad: all-suites, \"pet-friendly\", \"spacious suites with fully equipped kitchens\", complimentary hot breakfast and an outdoor pool; its own page names \"Carlsbad Caverns National Park, the Guadalupe Mountains, or Sitting Bull Falls\". Pets: 2 per room, 50 lb max, $100 per stay. +1 575-689-8850. Read from a web.archive.org snapshot of 9 June 2026 because marriott.com returns 403."},{"name":"Fairfield Inn & Suites by Marriott Carlsbad","source":"https://www.carlsbadchamber.com/lodging","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"marriott.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":35,"blurb":"Listed by the Carlsbad Chamber at \"2525 S. Canal St.\", (575) 887-8000, linked to marriott.com (property code cnmfi). marriott.com returned 403 and no archive snapshot exists, so nothing else about the property is stated here."},{"name":"Hampton Inn & Suites by Hilton Carlsbad","source":"https://www.carlsbadchamber.com/lodging","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"hilton.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":36,"blurb":"Listed by the Carlsbad Chamber at \"120 Esperanza Circle\", (575) 725-5700, linked to hilton.com (cnmnmhx). hilton.com returned 403 and its archive snapshot rendered no text, so nothing else about the property is stated here."},{"name":"Holiday Inn Express Carlsbad","source":"https://www.carlsbadchamber.com/lodging","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"ihg.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":37,"blurb":"Listed by the Carlsbad Chamber at \"2210 W Pierce St\", (575) 234-1252, linked to ihg.com (cnmex). ihg.com returned 403 and no archive snapshot exists, so nothing else about the property is stated here."},{"name":"Candlewood Suites Carlsbad","source":"https://www.carlsbadchamber.com/lodging","accessed":"2026-10-03","si":["family"],"booking_route":"ihg.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":38,"blurb":"Listed by the Carlsbad Chamber at \"3711 San Jose Blvd\", (575) 941-3711, linked to ihg.com (cnmcw). ihg.com returned 403, so nothing else about the property is stated here."},{"name":"Trinity Hotel","source":"https://www.thetrinityhotel.com/","accessed":"2026-10-03","si":["culture","romance","wine"],"booking_route":"own website / phone (575) 234-9891","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":39,"blurb":"201 S Canal St, Carlsbad: \"built in 1892 as the First National Bank\", restored after 2007 and \"now the home to Carlsbad''s finest dining establishment and nine luxurious hotel suites.\" Free New Mexico wine tasting Tuesday-Saturday 4-6pm. (575) 234-9891 (Chamber listing)."},{"name":"Hotel El Capitan","source":"https://www.thehotelelcapitan.com/","accessed":"2026-10-03","si":["culture","romance","motoring"],"booking_route":"own website \"Book Now\"","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":40,"blurb":"Van Horn: \"Designed by Henry Trost in 1930\" - \"Where deco meets desert\"; renovated rooms \"filled with the spirit of the 1930s along with free breakfast– and plenty of love for your pets\"; \"We''re at the crossroads of Guadalupe National Park and Big Bend National Park.\" Part of the 223 Collection."},{"name":"Van Horn, Texas","source":"https://www.thehotelelcapitan.com/","accessed":"2026-10-03","si":["motoring","culture"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":41,"blurb":"The Texas gateway, 62 miles south of the park on Hwy 54 (NPS), where the NPS places the nearest full services in Texas. Hotel El Capitan calls it \"a hub for space travel\" - \"watching a launch at Blue Origin\" - and a stop between Guadalupe Mountains, Big Bend, Marfa and the Chinati Foundation."},{"name":"Hotel El Capitan restaurant and Gopher Hole Bar","source":"https://www.thehotelelcapitan.com/","accessed":"2026-10-03","si":["culinary","wine","romance"],"booking_route":"walk-in / hotel","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":42,"blurb":"\"Pistachio fried steak, local pecan pie, and a 14-ounce, hand-cut ribeye that rivals the best\"; \"creative cocktails in the courtyard or pair Texas wines with a little history at The Gopher Hole Bar. (Just don''t forget to ask about the vault.)\""},{"name":"Chuy''s Restaurant","source":"https://www.chuysrestaurant.com/","accessed":"2026-10-03","si":["culinary","motoring"],"booking_route":"walk-in / phone 915-283-2066","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":43,"blurb":"\"Since 1959 in Van Horn, Texas\": 1200 West Broadway, Van Horn, Texas 79855; phone 915-283-2066. Its own page states nothing more."},{"name":"Trinity Hotel dining room","source":"https://www.thetrinityhotel.com/","accessed":"2026-10-03","si":["culinary","romance","wine"],"booking_route":"\"Book a table\" on its site / phone (575) 234-9891","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":44,"blurb":"\"Carlsbad''s finest dining establishment\": breakfast and lunch Tuesday-Saturday 7am-1:30pm with \"our amazing green chile cheeseburger\"; dinner 5pm-9pm of \"traditional American Italian dishes like lasagna, chicken parmigiana\" and steaks; Sunday brunch; \"CLOSED SUNDAY NIGHTS & ALL DAY MONDAY\"."},{"name":"Lucky Bull Grill","source":"https://www.luckybullcarlsbad.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in / online ordering","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":45,"blurb":"220 W Fox St, Carlsbad: \"classic American favorites with vibrant New Mexico flair\" - \"green chile grits, top-rated NM Fish N Chips with house made tartar sauce, and perfectly grilled steaks\"; the El Jefe Burger. Mon-Sat 11 AM - 9 PM, Sun 11 AM - 2 PM; 575-725-5444."},{"name":"YellowBrix","source":"https://yellowbrixrestaurant.com/","accessed":"2026-10-03","si":["culinary","entertainment"],"booking_route":"\"Reserve a Table\" on its site, or walk in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":46,"blurb":"201 N. Canal St, Carlsbad: \"Real food made from scratch every day, craft cocktails, live music most nights\"; full bar; breakfast, brunch, lunch and dinner with vegan and gluten-free menus; Mon-Fri 7am-9pm, Sat-Sun 8am-9pm."},{"name":"Guadalupe Mountain Brewing Co.","source":"https://www.carlsbadchamber.com/dining","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":47,"blurb":"Listed by the Carlsbad Chamber among its dining members at \"3324 National Parks Hwy\", Carlsbad. Only a Facebook page is linked; nothing else about it is stated here."},{"name":"Nurvis Purvis Brewing Company","source":"https://www.carlsbadchamber.com/dining","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":48,"blurb":"Listed by the Carlsbad Chamber among its dining members at \"610 W. Church St.\", Carlsbad; its own site (nurvispurvisbrewing.com) carries only \"VIEW THE BREW\". Nothing else about it is stated here."}],"faq":[{"q":"How much does it cost to go to Guadalupe Mountains National Park?","a":"The Standard Pass is \"$10.00\" per person aged 16 and over, valid for 1-7 consecutive days; the park''s Annual Pass is \"$35.00\", and children under 16 are free. You can pay by credit card at the Pine Springs Visitor Center or at \"self-pay stations located at any trailhead\".","source":"https://www.nps.gov/gumo/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Can you camp in Guadalupe Mountains National Park?","a":"Yes. \"Guadalupe Mountains has three developed campgrounds open year round which are open to tent or vehicle camping (RVs, etc.) one of which can only be used by groups with horses. All campsites in the Pine Springs and Dog Canyon Campgrounds are reservable up to six months in advance through recreation.gov.\" Backpackers need a Wilderness Use Permit for any overnight stay.","source":"https://www.nps.gov/gumo/planyourvisit/camping.htm","accessed":"2026-10-03"},{"q":"Does Guadalupe Mountains National Park have showers?","a":"No. At Pine Springs \"There are no showers available in the campground\", and at Dog Canyon \"Restrooms have sinks and flush toilets, but no showers.\" Neither campground has hookups or a dump station; \"The closest free RV dump station is off Canyon Street in Carlsbad, NM.\"","source":"https://www.nps.gov/gumo/planyourvisit/camping.htm","accessed":"2026-10-03"},{"q":"Can you take dogs to Guadalupe Mountains National Park?","a":"Only in limited places: leashed pets are allowed \"only in areas accessed by vehicles, including established roadsides, parking areas, developed picnic areas and campgrounds\", and may walk the Pine Springs Campground connector or the Pinery Trail. \"Pets are allowed on less than a mile of trails park-wide.\" The nearest kennel is at Carlsbad Caverns National Park.","source":"https://www.nps.gov/gumo/planyourvisit/pets.htm","accessed":"2026-10-03"},{"q":"Where should you stay when visiting Guadalupe Mountains National Park?","a":"Inside the park only campgrounds: \"There is no lodging (hotel, lodge, cabin) or dining inside the park\"; Pine Springs and Dog Canyon take tents and RVs. For services, the NPS points to Carlsbad, New Mexico to the north, Van Horn, Texas to the south and Dell City, Texas to the southwest.","source":"https://www.nps.gov/gumo/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03"},{"q":"How far is Guadalupe Mountains National Park from Carlsbad, NM?","a":"\"The driving distance is 110 miles east of El Paso, Texas, 56 miles southwest of Carlsbad, New Mexico or 62 miles north of Van Horn on Hwy 54.\" From Carlsbad, \"travel on US Hwy 62/180 South and cross into Texas. Follow signs to the park.\"","source":"https://www.nps.gov/gumo/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"What is the closest major airport to Guadalupe Mountains National Park?","a":"\"The closest large commercial airline service is El Paso, Texas. Other airlines serve Albuquerque, New Mexico, Lubbock and Midland, Texas and Mesa Airlines offers passenger service between Albuquerque and Carlsbad, New Mexico.\" The park is 110 miles east of El Paso, and \"There is no public transportation or shuttle service available in the park.\"","source":"https://www.nps.gov/gumo/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"What time zone is Guadalupe Mountains National Park in?","a":"Mountain Time: \"Guadalupe Mountains is in the Mountain Time Zone; it is likely that your smart phone will display the time incorrectly during your visit.\" McKittrick Canyon''s hours, 8:00 a.m. - 5:00 p.m., are Mountain Time.","source":"https://www.nps.gov/gumo/planyourvisit/hours.htm","accessed":"2026-10-03"},{"q":"What is the best time to visit Guadalupe Mountains National Park?","a":"\"Spring and Fall are typically warm and pleasant and are the parks busiest seasons.\" \"June-August are the hottest months\"; \"November through March is the windy season... with winds above 30MPH often, and gusts ranging from 50-80MPH.\" For fall colors, \"the best time of the year... is the last week of October and the first week of November\" (Hike to Fall Colors page).","source":"https://www.nps.gov/gumo/planyourvisit/weather.htm","accessed":"2026-10-03"},{"q":"Do you need reservations for Guadalupe Mountains National Park?","a":"Not to enter - you buy an entrance pass on arrival. \"Reservations can be made for camping and use of the horse corral campsites\", and \"Wilderness use permits are required for all overnight backpacking in the park\"; Wilderness reservations \"are encouraged but not required\" and open up to three months ahead.","source":"https://www.nps.gov/gumo/planyourvisit/permitsandreservations.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Guadalupe Mountains National Park: Guadalupe Peak & Camping | TravelWell","meta_description":"Hike Guadalupe Peak, the 8,751-ft Top of Texas, see McKittrick Canyon''s fall colors, camp at Pine Springs or Dog Canyon, and stay in White''s City or Carlsbad.","slug":"guadalupe-mountains-national-park-texas","primary_keyword":"Guadalupe Mountains National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Guadalupe Peak El Capitan West Texas"}}'::jsonb, 65),
  ('big-bend-ranch-texas', '12A', 'Big Bend Ranch State Park', 'United States', 'Texas'' largest state park on the Rio Grande', 'future', 'verified', 'mountainValley', 'Texas', '{"hiking","adventure","river","wildlife","glamping","parks"}', '{"remote","rugged","wild","dramatic","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Closed Canyon Trail","source":"https://tpwd.texas.gov/publications/pwdpubs/media/pwd_br_p4501_0152z.pdf","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"none needed - self-pay station at the trailhead for the park entrance fee","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"a short hike through a narrow slot canyon\", trailhead \"approximately 22 miles west of the Barton Warnock Visitor Center and 26 miles east of Fort Leaton State Historic Site on River Road, FM 170\"; \"approximately 1.4 miles long, round-trip\"; \"the temperature in the canyon is substantially cooler than out in the exposed desert for most of the day.\" One of only two trails where pets are allowed. \"Do not enter the canyon if there is a chance for rain.\""},{"name":"River Road (FM 170) through the park","source":"https://tpwd.texas.gov/publications/pwdpubs/media/pwd_br_p4501_0152x.pdf","accessed":"2026-10-03","si":["motoring","culture","river"],"booking_route":"none needed - public highway","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"Both park entrances sit on FM 170, the \"River Road\" between Lajitas and Presidio; TPWD''s Hoodoos guide records that the modern road \"was completed in 1961\" over a pack trail \"locally referred to as Muerte del Burro, meaning ''the death of the donkey''\" that \"once connected the communities of Lajitas and Redford\"."},{"name":"Hoodoos Trail","source":"https://tpwd.texas.gov/publications/pwdpubs/media/pwd_br_p4501_0152x.pdf","accessed":"2026-10-03","si":["hiking","family","river"],"booking_route":"none needed - self-pay station at the trailhead for the park entrance fee","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"approximately 26 miles west of the Barton Warnock Visitor Center and 22 miles east of Fort Leaton State Historic Site on FM 170\": \"a short 1.1-mile loop trail\" down past the hoodoos, \"along the bank of the Rio Grande, up an old historic road to an overlook\"; \"The hoodoos, Rio Grande River and Mexico are all visible from the parking area.\" Leashed pets allowed."},{"name":"Rio Grande and Colorado Canyon","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/activities","accessed":"2026-10-03","si":["river","adventure","wildlife"],"booking_route":"river-use permit at either entrance; guided trips through the TPWD-listed guide services","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"TPWD: \"Raft or paddle the Rio Grande on the border between Texas and Mexico\"; the activities page lists \"Raft, canoe, picnic and fish\" and notes \"Colorado Canyon includes Class II and III rapids\". River-use permits are sold at Barton Warnock and Fort Leaton."},{"name":"Gold-tier Dark Sky Park","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/dark-skies","accessed":"2026-10-03","si":["wildlife","romance","glamping","family"],"booking_route":"none needed - free with park entry","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"The International Dark-Sky Association designated Big Bend Ranch State Park a gold tier Dark Sky Park in 2018.\" A Dark Sky Steward volunteer programme logs sky quality - \"We may waive camp or park entrance fees for volunteers who sign up and provide observations and/or images\" - and star parties are posted on the events page."},{"name":"Sauceda and the park interior","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/history","accessed":"2026-10-03","si":["adventure","culture","overland","hiking"],"booking_route":"none needed - check in first at the east or west entrance","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"The Bogel brothers'' 1910s ranch headquarters: \"The buildings and corrals of their headquarters, Saucita, endure today at the heart of Big Bend Ranch State Park.\" Today''s Sauceda Ranger Station \"is 27 miles of rugged, dirt road from FM 170\"; the park has \"238 miles of multiuse trails\" and \"70 miles of unmaintained dirt roads\"."},{"name":"Sauceda Bunkhouse","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/fees-facilities/lodging","accessed":"2026-10-03","si":["group","family","adventure"],"booking_route":"Texas State Parks reservations (texasstateparks.reserveamerica.com) or (512) 389-8900","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":7,"blurb":"Sleeps 30 (\"People per Site: 30\") with kitchen, fireplace, showers and outdoor grill; \"$35 Per Person Plus daily entrance fee\"; \"Bed & bath linens are not provided\". ⚠️ TPWD notice: \"Dec. 10, 2024 - The Sauceda Bunkhouse is closed due to wastewater repairs.\""},{"name":"Drive-in primitive campsites","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/fees-facilities/campsites","accessed":"2026-10-03","si":["adventure","hiking","overland","river"],"booking_route":"Texas State Parks reservations (texasstateparks.reserveamerica.com) or (512) 389-8900","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":8,"blurb":"Four TPWD site types: Interior District 8-person and River District 8-person \"$12 Nightly\", Interior District 12-person \"$16 Nightly\", each \"plus daily entrance fee\"; drive-in sites have picnic tables and fire rings. \"Some roads require four-wheel-drive or high clearance.\""},{"name":"Backcountry hike-in camping","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/fees-facilities/campsites","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"backcountry permit at the east or west entrance","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":9,"blurb":"Hike-in Backcountry (6-person) \"$10 Nightly\" plus entrance fee; permits from Barton Warnock or Fort Leaton. Sites \"must be at least 1/4 mile from any other existing campsite\", \"at least 300 feet from water sources and prehistoric or historic cultural sites\" and \"at least 3/4 mile from trailheads or roads\"; ground fires are prohibited."},{"name":"Cinco Tinajas Trail","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/activities","accessed":"2026-10-03","si":["hiking","family","wildlife"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"A \"¾ mile\" trail that \"offers views into a deep canyon with a series of tinajas, or rock pools\" (TPWD activities page)."},{"name":"Puerta Chilicote trail system","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/activities","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"A \"5-mile rim trail\" and a \"3.2-mile loop\" on TPWD''s hiking and mountain-biking list; TPWD: \"When biking, always wear a helmet and carry two spare tubes.\""},{"name":"Ojito Adentro Trail","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/activities","accessed":"2026-10-03","si":["hiking","wildlife"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"A one-mile trail on TPWD''s list (\"Ojito Adentro Trail: one mile\"); \"Trails provide the easiest access to many areas of Big Bend Ranch State Park.\""},{"name":"Barton Warnock Visitor Center","source":"https://tpwd.texas.gov/state-parks/barton-warnock","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"walk-in","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"The park''s eastern entrance in Terlingua: the bilingual exhibit \"Una Tierra - One Land\" on the region''s natural history and \"a two-acre garden showcasing the plants of the Chihuahuan Desert\"; \"a one-stop shop for information\" to \"pick up permits for backpacking and camping, purchase river-use permits and licenses.\" \"8 a.m. to 4:30 p.m. daily\"."},{"name":"Fort Leaton State Historic Site","source":"https://tpwd.texas.gov/state-parks/fort-leaton","accessed":"2026-10-03","si":["culture","senior","family"],"booking_route":"walk-in; daily entrance fee","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":14,"blurb":"The park''s western entrance at 16952 FM 170 East, Presidio: \"Travelers in far West Texas stopped at Fort Leaton to buy supplies and fortify themselves\"; a restored 1800s adobe fort whose \"walls at the fort range from 18 to 22 feet tall\". \"13 years and older: $5 Daily\"; open daily except Christmas, 8 a.m. to 4:30 p.m."},{"name":"Big Bend Ranch airstrip","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch","accessed":"2026-10-03","si":["privatejet","adventure"],"booking_route":"not read - contact the park","commission_status":"none","tier_absent_reason":"not-sold","wells":["fly"],"draw_rank":15,"blurb":"\"The park also has a 5,500-foot paved airstrip.\""},{"name":"Extra water for desert heat","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":16,"blurb":"TPWD''s own kit advice: temperatures \"can reach as high as 130 degrees in the sun\" and \"remain at dangerous levels even after sunset. Carry plenty of extra water on the trails, and stay off trails in the afternoon.\" The trail guides add \"always bring water!\" - and water for your dog."},{"name":"Sun-protective clothing and a trail map","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/activities","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":4,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":17,"blurb":"TPWD: \"Always carry a map when hiking and biking\" and \"Carry plenty of water and wear appropriate protective clothing.\""},{"name":"Bike helmet and two spare tubes","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/activities","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":18,"blurb":"TPWD on the park''s mountain-bike trails: \"When biking, always wear a helmet and carry two spare tubes.\""},{"name":"Lajitas Golf Resort and Spa","source":"https://www.lajitasgolfresort.com/","accessed":"2026-10-03","si":["golf","romance","wellness","family"],"booking_route":"own website","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":19,"blurb":"A \"27,000 acre Texas resort\" at the park''s eastern end: Cavalry Post, La Cuesta, Badlands Hotel, Officer''s Quarters, Lakeside Cottages, Boardwalk Condos and private homes totalling 126 rooms, with spa, equestrian centre and the Black Jack''s Crossing golf course. No brand affiliation is stated on the site."},{"name":"Black Jack''s Crossing","source":"https://www.lajitasgolfresort.com/","accessed":"2026-10-03","si":["golf","senior"],"booking_route":"own website","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":20,"blurb":"Lajitas Golf Resort''s 18-hole championship course \"designed by PGA Hall of Fame golfer, Lanny Wadkins\", which the resort says ranks \"#1 Best Course You Can Play in Texas\" per Golfweek and the Dallas Morning News."},{"name":"Maverick Ranch RV Park","source":"https://www.lajitasgolfresort.com/rv-park/","accessed":"2026-10-03","si":["motoring","golf","family"],"booking_route":"own booking engine, 432-424-5182 or maverickranchrvpark@lajitasgolfresort.com","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":21,"blurb":"At Lajitas Golf Resort: \"100 Sites\" with \"60 Pull Throughs\", \"Hookups (sewer, 30/50 amp, water)\", \"Big Rig Capable\"; showers, laundry, outdoor pool, dog park and clubhouse, with access to the resort''s spa, golf and horseback riding. 432-424-5182."},{"name":"Lajitas Stables","source":"https://lajitasstables.com/","accessed":"2026-10-03","si":["adventure","family","overland"],"booking_route":"FareHarbor from the own site","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":22,"blurb":"\"2.5 miles west of Lajitas Resort on HWY 170\"; rides \"at a walking pace on rugged, rocky terrain\" with a 250 lb rider limit: Adventurous & Rugged Trails, Big Bend Ranch State Park Rides (\"we... also ride in Big Bend Ranch State Park (Lajitas Stables)\") and Rios Ranch multi-day trips. Listed by TPWD as a park guide service provider. 432-371-3064."},{"name":"Far Flung Outdoor Center","source":"https://www.bigbendfarflung.com/","accessed":"2026-10-03","si":["river","adventure","overland","family"],"booking_route":"own website \"BOOK NOW\"","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","move"],"draw_rank":23,"blurb":"Terlingua, \"Big Bend''s Adventure Resort Since 1976\": Half-Day and One-Day Canyon floats, multi-day river trips, Jeep and ATV tours, casitas, shuttles and the Bella Bean Coffee Shop. TPWD lists it as a Big Bend Ranch guide service provider. 432-371-2633."},{"name":"Desert Sports","source":"https://desertsportstx.com/","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"phone - \"Call for reservations\"","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","shop"],"draw_rank":24,"blurb":"22937 FM 170, Terlingua: a bike shop with \"bicycle supplies, repairs and mtb rentals\". ⚠️ \"As of May 31, 2025, we are suspending all of our Guided Tours in Big Bend\" and \"we will no longer offer boating rentals or shuttles.\" October-April hours 9 am-6 pm Tuesday-Sunday. 1-432-371-2727."},{"name":"Angell Expeditions","source":"https://www.angellexpeditions.com/","accessed":"2026-10-03","si":["overland","adventure","river","hiking"],"booking_route":"email/phone enquiry - charles@angellexpeditions.com, 432-384-2008","commission_status":"unknown","commission":"guide","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":25,"blurb":"Based in Redford on FM 170: \"Four wheel drive vehicle tours down forgotten trails in the Chihuahan desert around the Chinati Mountains, Big Bend National Park, and Big Bend Ranch State Park\", plus mountain biking, hiking and backpacking and Rio Grande river trips; \"All activities require a 2 person minimum.\" TPWD-listed guide service provider."},{"name":"The Summit at Big Bend","source":"https://visitbigbend.com/places/the-summit-at-big-bend/","accessed":"2026-10-03","si":["glamping","romance","wildlife"],"booking_route":"own website summitbigbend.com","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":26,"blurb":"2500 N Lone Star Mine, Terlingua: \"the only cave hotel rooms in Texas\" on over 1,000 acres \"between Big Bend National Park and Big Bend State Park\" - luxury cave suites, Stargazer Deluxe Suites, Super and Classic Stargazing Domes and casitas, all with air conditioning, heating, WiFi and fire pits (Visit Big Bend listing). 432-777-7866."},{"name":"Basecamp Terlingua","source":"https://www.basecampterlingua.com/","accessed":"2026-10-03","si":["glamping","romance","family"],"booking_route":"own website \"Book Now\" per property","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":27,"blurb":"Terlingua: \"Casitas,\" \"Bubbles,\" \"Tipis,\" \"Lotus Tents\" and campsites at an \"Arroyo Campground\", with \"Venga Cafe and Private Event Space\"; sister brands Bubble Terlingua, Adventure Terlingua, Agave Terlingua, Luna Nova and Vida Terlingua."},{"name":"Terlingua Ranch Lodge","source":"https://www.terlinguaranch.com/","accessed":"2026-10-03","si":["motoring","family","adventure"],"booking_route":"own website \"Book Now\" (terlinguaranch.com/terlingua-texas-hotels-motels-lodging/)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":28,"blurb":"16000 Terlingua Ranch Rd: \"Cabin guest rooms, RV sites, campgrounds, horse corral and stable\", with the Bad Rabbit Café on site. 432-371-3146."},{"name":"Willow House","source":"https://visitbigbend.com/places/willow-house/","accessed":"2026-10-03","si":["romance","group","wellness"],"booking_route":"own website willowhouse.co","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":29,"blurb":"23112 FM 170, Terlingua: \"a unique blend of communal hospitality and private accommodations\" - a communal Main House and private rooms with Chisos Mountain views, for groups up to 30 (Visit Big Bend listing)."},{"name":"Starlight Theatre Restaurant and Saloon","source":"https://www.thestarlighttheatre.com/","accessed":"2026-10-03","si":["culinary","entertainment","culture"],"booking_route":"walk-in; reservations for groups of 10 or more","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":30,"blurb":"631 Ivey Road, Terlingua Ghost Town: \"the finest dining establishment in the entire Terlingua Ghost Town, offering a fine selection of gourmet dishes and rollicking drinks, plus the best in live entertainment.\" Sun-Fri 5 pm-midnight, Sat to 1 am; \"Reservations available for groups of 10 or more.\" 432.371.3400."},{"name":"High Sierra Bar & Grill","source":"https://visitbigbend.com/places/high-sierra-bar-grill/","accessed":"2026-10-03","si":["culinary","entertainment"],"booking_route":"walk-in (no booking method read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":31,"blurb":"100 Ghost Town Rd, Terlingua: \"the restaurant and bar at the El Dorado Hotel in Terlingua Ghost Town, offering casual dining and entertainment\"; daily 12 PM-2 AM, live music typically Friday and Saturday (Visit Big Bend listing). 432-371-3282."},{"name":"DB''s Rustic Iron BBQ","source":"https://visitbigbend.com/places/dbs-rustic-iron-bbq/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in (no booking method read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":32,"blurb":"10 Terlingua Ghost Town Rd: \"Award-winning Central Texas-style barbecue\" serving the region since 1993; Wednesday-Monday, 11 AM \"until sellout\" (Visit Big Bend listing). 432-371-3939."},{"name":"Espresso y Poco Mas","source":"https://visitbigbend.com/places/espresso-y-poco-mas/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in (no booking method read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":33,"blurb":"45 Milagro Way, Terlingua: \"Terlingua''s premier breakfast and brunch destination, offering quality coffee and creative morning dishes\" at La Posada Milagro Guesthouse; daily 7:30 AM-2 PM (Visit Big Bend listing). 432-371-3044."},{"name":"Chili Pepper Cafe","source":"https://visitbigbend.com/places/chili-pepper-cafe/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in (no booking method read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":34,"blurb":"100 S Hwy 118, Study Butte: \"a Tex-Mex restaurant\", \"Typically open daily from about 8:00 AM to 9:00 PM\" - the listing recommends calling ahead (Visit Big Bend listing). 432-371-2233."},{"name":"Taqueria El Milagro","source":"https://visitbigbend.com/places/taqueria-el-milagro/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in, cash only","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":35,"blurb":"210 Ivey Rd, Terlingua: \"traditional Mexican dishes prepared with family recipes passed down through generations\" since 2008; Wednesday-Monday 3-9 PM, cash only, to-go available (Visit Big Bend listing). 432-371-2060."},{"name":"Candelilla Café","source":"https://www.lajitasgolfresort.com/dining/","accessed":"2026-10-03","si":["culinary","romance","golf"],"booking_route":"walk-in (no booking method read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":36,"blurb":"Lajitas Golf Resort: \"Offering fine dining in the heart of Big Bend\", open daily for breakfast, lunch and dinner; public access until 5pm, after 5pm members and registered guests only."},{"name":"Thirsty Goat Saloon","source":"https://www.lajitasgolfresort.com/dining/","accessed":"2026-10-03","si":["culinary","entertainment"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":37,"blurb":"Lajitas Golf Resort: \"Perfect spot to sit, relax and enjoy the beauty of the Big Bend\"; Sunday-Thursday 11am-12am, Friday-Saturday to 2am, last food orders 9pm; 21+ inside, outdoor seating for younger guests."},{"name":"Lajitas General Store and Deli","source":"https://www.lajitasgolfresort.com/dining/","accessed":"2026-10-03","si":["culinary","hiking","family"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":38,"blurb":"\"Prepare for your day in the Big Bend!\" - store 8am-7pm daily, deli counter 8am-6:30pm, with box lunches, wine and cheese baskets and limited groceries; the last provisions stop before the park''s eastern entrance on the resort''s own listing."}],"faq":[{"q":"What camping is there at Big Bend Ranch State Park?","a":"Primitive camping only, per TPWD: drive-in sites in the Interior District (8-person \"$12 Nightly\", 12-person \"$16 Nightly\") and River District (8-person \"$12 Nightly\"), and hike-in backcountry sites (6-person \"$10 Nightly\"), each \"plus daily entrance fee\". Backcountry permits come from Barton Warnock or Fort Leaton, and ground fires are prohibited.","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/fees-facilities/campsites","accessed":"2026-10-03"},{"q":"Does Big Bend Ranch State Park allow dogs?","a":"In a few places only: \"Dogs are only allowed to be ¼ mile from campsites or designated roads, and only on the Closed Canyon Trail and the Hoodoos Trail on FM 170.\" \"Dogs are not allowed on any other hiking trails, in the backcountry, or more than ¼ mile from campsites or designated roads.\"","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/dog-policies","accessed":"2026-10-03"},{"q":"How many acres is Big Bend Ranch State Park?","a":"TPWD gives \"over 300,000 acres\", making it \"Texas'' largest state park.\"","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/history","accessed":"2026-10-03"},{"q":"When did Big Bend Ranch State Park open?","a":"\"TPWD purchased the ranch in 1988. The park opened on a limited basis in 1991. It opened fully to the public in 2007.\"","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/history","accessed":"2026-10-03"},{"q":"What county is Big Bend Ranch State Park in?","a":"Two: the park lies \"along the Rio Grande from southeast of Presidio to near Lajitas, in both Brewster and Presidio counties.\"","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/history","accessed":"2026-10-03"},{"q":"How do I get to Big Bend Ranch State Park?","a":"By FM 170, the River Road: the east entrance is \"21800 FM 170, Terlingua, TX 79852\" and the west entrance \"16952 FM 170 East, Presidio\". The interior headquarters at Sauceda is \"27 miles of rugged, dirt road from FM 170\" - check in first at the east or west entrance. \"The park also has a 5,500-foot paved airstrip.\"","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch","accessed":"2026-10-03"},{"q":"Does Big Bend Ranch State Park have an airstrip?","a":"Yes: \"The park also has a 5,500-foot paved airstrip.\"","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch","accessed":"2026-10-03"},{"q":"What trails are at Big Bend Ranch State Park?","a":"\"The park has 238 miles of multiuse trails (for hiking, biking and riding horses).\" TPWD''s activities page names Cinco Tinajas (\"¾ mile\"), Ojito Adentro (one mile) and the Puerta Chilicote system (a 5-mile rim trail and a 3.2-mile loop); on FM 170 the Closed Canyon Trail is \"approximately 1.4 miles long, round-trip\".","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/activities","accessed":"2026-10-03"},{"q":"Does Big Bend Ranch State Park have RV sites?","a":"TPWD lists primitive drive-in sites with picnic tables and fire rings and mentions no hookups; \"All sites (except backcountry) can be reached by vehicle. Some roads require four-wheel-drive or high clearance.\" Full hookups are outside the park, e.g. Maverick Ranch RV Park in Lajitas: \"Hookups (sewer, 30/50 amp, water)\", \"Big Rig Capable\".","source":"https://tpwd.texas.gov/state-parks/big-bend-ranch/fees-facilities/campsites","accessed":"2026-10-03"}],"seo":{"meta_title":"Big Bend Ranch State Park: River Road, Trails & Camping | TravelWell","meta_description":"Texas'' largest state park: Closed Canyon and the Hoodoos on FM 170, 238 miles of trails, a gold-tier Dark Sky Park, primitive camping and where to stay nearby.","slug":"big-bend-ranch-state-park-texas","primary_keyword":"Big Bend Ranch State Park","jsonld_type":"TouristDestination"},"hero":{"query":"Big Bend Ranch State Park Closed Canyon Rio Grande"}}'::jsonb, 66)
