insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('garner-texas', '12A', 'Garner State Park', 'United States', 'Frio River swimming and summer jukebox dances', 'future', 'verified', 'mountainValley', 'Texas', '{"family","hiking","culture","motoring","river","parks"}', '{"family-friendly","festive","rugged","historic"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Frio River swimming and tubing","source":"https://tpwd.texas.gov/state-parks/garner","accessed":"2026-10-03","si":["family","river","adventure"],"booking_route":"park entry only - day pass $8 ages 13+, reserve on ReserveAmerica or (512) 389-8900","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"With 2.9 miles of Frio River winding through 1,774 acres of scenic Hill Country terrain\"; \"Swim in the Frio River or float its waters on an inner tube, operate a paddle boat\". TPWD''s current alert: \"Swimming is permitted on the river at your own risk. No lifeguards are on duty.\""},{"name":"The summer jukebox dance","source":"https://tpwd.texas.gov/state-parks/garner","accessed":"2026-10-03","si":["family","culture","entertainment","romance"],"booking_route":"no booking - park entry; schedule on garnerstatepark.com/the-dance","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":2,"blurb":"\"Since the 1940s, young folks (and the young at heart) have been gathering at the park''s concession building on summer evenings for a jukebox dance. They still do so today.\" The concession lists Summer Dances \"May 24-Aug 10\", \"8:30-11pm\", on the \"Pavilion Dance Floor\". TPWD: \"Arrive early, as parking lots get full and gates can close as early as 8:30 p.m.\""},{"name":"Old Baldy Trail","source":"https://tpwd.texas.gov/state-parks/garner/trails-info","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - park trail, within entry","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"Old Baldy Trail\", 0.5 mi., rated \"Challenging\"; the Bridges Trail delivers \"a great view of Old Baldy at Painted Rock Overlook and the shade of the giant Ashe juniper tree\" - \"Use caution on the loose rocks and steep terrain.\""},{"name":"Garner historic cabins","source":"https://tpwd.texas.gov/state-parks/garner/fees-facilities/cabins","accessed":"2026-10-03","si":["family","culture","romance"],"booking_route":"ReserveAmerica (Texas State Parks) online or (512) 389-8900","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":4,"blurb":"17 kitchen cabins in the Old Garner area - 13 \"Cabins with Fireplace\" at $150 nightly and 4 without at $130 (one ADA), each with \"Kitchen sink, Microwave, Refrigerator, Stove without oven\", a bathroom with shower and two double beds; \"No linens, blankets or towels provided\"; \"A 2-night minimum reservation is required on all cabins\"; \"No pets\". The CCC built \"a lodge and cabins\" here between 1935 and 1941."},{"name":"Garner State Park campsites","source":"https://tpwd.texas.gov/state-parks/garner/fees-facilities/campsites","accessed":"2026-10-03","si":["motoring","family","river"],"booking_route":"ReserveAmerica (Texas State Parks) online or (512) 389-8900","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":5,"blurb":"Some 347 sites across Old and New Garner: 12 pull-through full-hookup sites in Shady Meadows ($35; \"No tents are allowed, and there is no shade or tree cover\"), 137 water-and-50-amp sites in Rio Frio and Live Oak ($26), 39 electric sites in Oakmont ($26), 35 30-amp sites ($22), and 124 water-only sites ($15-$20; RVs \"20 feet or less\"), all plus entry. \"Live Oak Camping Area is closed January and February.\""},{"name":"Garner screened shelters","source":"https://tpwd.texas.gov/state-parks/garner/fees-facilities/shelters","accessed":"2026-10-03","si":["family","hiking"],"booking_route":"ReserveAmerica (Texas State Parks) online or (512) 389-8900","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":6,"blurb":"21 shelters in Pecan Grove (Old Garner, $35) and 16 in River Crossing (New Garner, $30), plus entry: \"Electricity\", \"Light and outlet inside\", \"Picnic table inside\", fire ring with grill and water spigot outside; up to 8 people; \"No RVs are allowed at the shelters\"; \"No pets\"."},{"name":"CCC combination building and dance pavilion","source":"https://tpwd.texas.gov/state-parks/garner/history","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"none needed - within park entry","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"CCC Company 879 developed Garner between 1935 and 1941\"; \"The CCC utilized native limestone and hewn bald cypress to construct this building and dance pavilion. The building overlooks the river, and is the centerpiece of the park.\" The park \"opened June 1, 1941, and was named for John Nance ''Cactus Jack'' Garner\"."},{"name":"Crystal Cave Trail","source":"https://tpwd.texas.gov/state-parks/garner/trails-info","accessed":"2026-10-03","si":["hiking","family","adventure"],"booking_route":"none needed - park trail, within entry","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"\"Crystal Cave Trail\" (0.6 mi.), \"Challenging in several places, the trail provides access to one of the park''s natural wonders\": \"Don''t forget a flashlight as you enter this 30-foot deep cave. Enjoy the slightly cooler temperatures, and help us protect the cave''s namesake.\""},{"name":"Frio Canyon Trail and the park trail network","source":"https://tpwd.texas.gov/state-parks/garner/trails-info","accessed":"2026-10-03","si":["hiking","family","culture"],"booking_route":"none needed - park trails, within entry","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"Explore 16 miles of trails, some leading to bird''s-eye views\": the Frio Canyon Trail (2.9 mi.) - \"Experience the vastness of the Frio Canyon while hiking or biking this relatively flat trail\" - the Ashe Juniper Trail (2.5 mi.), Foshee (1.7 mi.) and the Old Entrance Road (0.8 mi.), \"built in the 1930s by the Civilian Conservation Corps as part of the original park entrance.\""},{"name":"Garner Boat House rentals","source":"https://garnerstatepark.com/boat-house","accessed":"2026-10-03","si":["family","river","adventure"],"booking_route":"walk-up, cash only, at the Boat House","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":10,"blurb":"The park concession rents a \"1 Person Kayak\" ($15 per hour), \"2 Person Kayak\" ($20), \"Paddle Boat\" ($20), \"Stand Up Paddle Board (SUP)\" ($20) and \"iFloat\" ($10); \"Must be 18 years old to rent, bring a valid ID\", \"Cash Only\", \"No Refunds\"; open \"7 Days a Week\" in summer, closed December-January. TPWD adds that the park loans \"fishing gear for use in the park.\""},{"name":"Fishing the Frio without a license","source":"https://tpwd.texas.gov/state-parks/garner","accessed":"2026-10-03","si":["family","river","wildlife"],"booking_route":"none needed - within park entry; loaner gear from the park","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"Try your luck fishing the Frio - no license needed to fish from shore!\" and \"We also loan fishing gear for use in the park.\" The Park Store stocks \"fishing supplies\"."},{"name":"The Garner Grill","source":"https://garnerstatepark.com/the-garner-grill","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-up, cash only","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":12,"blurb":"The concession grill: \"Everything is made fresh when you order it-no warmers or stale food here\"; burgers of \"1/3lb meat on a sourdough bun from a Houston bakery\", including an Axis deer burger; summer \"11am-4pm\", \"Open Daily\" from Memorial Weekend; cash only."},{"name":"Garner ice cream and gelato shop","source":"https://garnerstatepark.com/ice-cream-shop","accessed":"2026-10-03","si":["family","culinary"],"booking_route":"walk-up","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":13,"blurb":"\"Hand dipped Gelato in a variety of delicious flavors. Gelato shakes and sundaes also available\", plus \"Fresh Fudge Made fresh in house\", \"Candied Pecans made fresh throughout the day\" and popcorn; \"Summer Hours-Open Daily 11am-11pm\"."},{"name":"Garner Park Store","source":"https://garnerstatepark.com/park-store","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["shop","gear"],"draw_rank":14,"blurb":"\"Groceries, grillin'' meats, snacks, coffee, cleaning supplies, RV, toiletries, swim gear, fishing supplies, drinks\" plus Lodge Cookware and Case Knives; summer \"8am-10pm DAILY\", \"usually open daily through December, weather and visitation permitting.\""},{"name":"Stinkin'' Sweet Candy Golf","source":"https://garnerstatepark.com/stinkin-sweet-candy-golf","accessed":"2026-10-03","si":["family"],"booking_route":"walk-up","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":15,"blurb":"The park''s mini golf, \"Newly renovated for 2023! Rental fee includes one round of 18 holes\": first round $7 per person (4 and up), second round $4, ages 3 and under $2; a candy shop of \"old school, crazy, gross and funny treats\" alongside."},{"name":"Trail water, a quart an hour","source":"https://tpwd.texas.gov/state-parks/garner/trails-info","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":16,"blurb":"TPWD''s own kit advice for Garner''s trails: \"Drink plenty of water. Your body quickly loses fluids when you''re on the trail. Bring a quart (32 oz.) of water per hour of activity.\" July''s average high is 97 degrees."},{"name":"Sun, insect and footwear kit","source":"https://tpwd.texas.gov/state-parks/garner/trails-info","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":17,"blurb":"TPWD on Garner''s trails: \"Know your limits. Prepare for sun and heat. Wear sunscreen, insect repellent and appropriate clothing/hiking shoes.\" Most trails are \"rugged, rocky and cover a wide variety of terrain and elevations.\""},{"name":"Flashlight for Crystal Cave","source":"https://tpwd.texas.gov/state-parks/garner/trails-info","accessed":"2026-10-03","si":["hiking","family","adventure"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":18,"blurb":"TPWD: \"Don''t forget a flashlight as you enter this 30-foot deep cave.\""},{"name":"Lost Maples State Natural Area","source":"https://tpwd.texas.gov/state-parks/lost-maples","accessed":"2026-10-03","si":["hiking","wildlife","family"],"booking_route":"day pass via ReserveAmerica (Texas State Parks) or (512) 389-8900","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":19,"blurb":"Vanderpool: \"Lost Maples protects a special stand of Uvalde bigtooth maples\"; \"The show varies, depending on weather conditions. Check our Fall Foliage report (starting mid-October).\" \"October and November are our busiest times. We reach capacity daily.\" Named by TPWD on the Garner page among \"Other TPWD parks nearby\"."},{"name":"Briscoe-Garner Museum","source":"https://briscoecenter.org/briscoe-garner-museum/","accessed":"2026-10-03","si":["culture","senior"],"booking_route":"not read","commission_status":"unknown","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":20,"blurb":"Uvalde: \"dedicated to sharing the remarkable lives and legacies of two of the most influential 20th century political leaders from the Lone Star State: Vice President ''Cactus'' Jack Garner and Governor Dolph Briscoe\" - the namesake of the park. Run by the Briscoe Center (UT Austin); hours and street address not on the page read."},{"name":"Neal''s Lodges","source":"https://www.nealslodges.com/","accessed":"2026-10-03","si":["family","river","motoring"],"booking_route":"own website BOOK NOW, reserve@nealslodges.com or (830) 232-6118","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":21,"blurb":"Concan: \"founded in 1926 and is a family-owned and operated vacation hideaway on the beautiful spring-fed Frio River\" - \"81 cabins, 10 lodges, 17 condos, 45 RV hook-ups, and 16 tent sites\", \"River access exclusively for Neal''s guests\", a country store and Neal''s Dining Room; \"CLOSED THE MONTH OF JANUARY\". 20970 Hwy 127, (830) 232-6118."},{"name":"Happy Hollow Frio River Outfitters","source":"https://www.onthefrio.com/","accessed":"2026-10-03","si":["river","family","adventure"],"booking_route":"phone (830) 232-5266 / text (830) 279-5990; lodging via own online reservation link","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":22,"blurb":"32580 US-83, Concan: rents tubes and kayaks with a river shuttle - Fri-Sun 10 AM-5 PM (\"shuttle until 3 PM\"), Thursday 11 AM-2 PM, Mon-Wed \"By Appointment\" - and lets River Houses and Riverfront Bungalows. (830) 232-5266."},{"name":"Camp Riverview","source":"https://friocampriverview.com/","accessed":"2026-10-03","si":["motoring","family","river"],"booking_route":"Campspot reservation system from the own site","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":23,"blurb":"1636 County Road 350, Concan: \"Full Hook Up, 30/50 amp\" RV sites, tent sites and \"Efficiency, one and two bedroom cabins that sleep up to six comfortably\", with Frio River floating, a playground, laser tag and a camp store; reservations run on Campspot. (830) 232-5412."},{"name":"Pitmaster RV Park","source":"http://www.campspot.com/c/cabins-in-texas/near-concan","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Campspot marketplace","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":24,"blurb":"Listed on Campspot in Concan (\"4 miles\" on its near-Concan page): \"featuring 50 spacious full-hookup sites, tent camping, and unique lodging options such as a covered wagon and a Native American teepee.\""},{"name":"Stars Over Texas RV Park-Frio","source":"http://www.campspot.com/c/cabins-in-texas/near-concan","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Campspot marketplace","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":25,"blurb":"Listed on Campspot in Concan (\"6 miles\" on its near-Concan page): \"Nestled in the scenic Frio River Canyon...51 RV Sites- that are surrounded by the Biggest Shadiest Oak Trees & all sites are less than 100 yards from the SOT Country Club.\" Cabins and RV sites."},{"name":"Riverbend on the Frio","source":"https://www.riverbendonthefrio.com/","accessed":"2026-10-03","si":["motoring","family","senior"],"booking_route":"RMS Cloud booking engine (bookings.rmscloud.com) from the own site","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","move"],"draw_rank":26,"blurb":"32710 N US Hwy 83, Concan: \"Standalone Cabins,\" \"Small Motels,\" \"Deluxe Motels,\" \"RV Slots,\" and \"RV Rentals\"; \"Extended monthly stays\" are offered \"October 15 through March 1\" for Winter Texans. (830) 232-6616."},{"name":"Seven Bluff Cabins & RV Park","source":"https://www.7bluffcabins.com/","accessed":"2026-10-03","si":["family","river","motoring"],"booking_route":"own website Book Now","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":27,"blurb":"4251 County Road 348, Concan, on the Frio River at Seven Bluff Crossing: \"20 cabins and 17 RV sites to choose from\"; listed by the Frio Canyon Chamber under tube and kayak rentals. +1 (830) 232-5260."},{"name":"Frio Pecan Farm","source":"https://www.friopecanfarm.com/","accessed":"2026-10-03","si":["family","river","group"],"booking_route":"phone only, 830-232-5294","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":28,"blurb":"144 Ranch Rd 337 East, Leakey: \"17 log cabins\" that \"Sleep up to 6\" and \"17 Vacation Homes\" that \"Sleep 8 to 24\", with the Frio River running through the property; \"Reservations cannot be made online. Please Call the Office at 830-232-5294 to book\"."},{"name":"Frio Rentals","source":"https://friorentals.com/","accessed":"2026-10-03","si":["romance","family","river"],"booking_route":"WebRez (secure.webrez.com) from the own site","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":29,"blurb":"Cabins, lodges and bungalows \"deep in the heart of the Frio Canyon\" near Leakey - one property \"A 5 minute drive from Garner State Park\" - with hot tubs, pools and river access; \"Four separate bungalows containing seven private rooms\". (830) 232-4781."},{"name":"Speakeasy Resorts - The Highball and The Moonshine","source":"https://speakeasyresorts.com/","accessed":"2026-10-03","si":["group","family","romance"],"booking_route":"own website /book-your-stay/","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":30,"blurb":"\"FRIO RIVER • CONCAN, TX\" \"Luxury Home Rentals\" \"close to Garner state park\": The Highball \"Sleeps up to 25\" (5 bedrooms, 3,800 sq ft, \"Heated Pool & Spa\", arcade games); The Moonshine \"Sleeps up to 24\" (4,300 sq ft on over 2 acres). 210-313-4972."},{"name":"Seco Ridge Campgrounds","source":"https://www.hipcamp.com/en-US/d/united-states/texas/leakey/glamping","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":31,"blurb":"Utopia, on Hipcamp: \"Private, family-friendly campgrounds in the Texas Hill Country. Great views, and just minutes from Garner State Park and Lost Maples State Natural Area\" - primitive tent sites and a Bunkhaus."},{"name":"Hampton Inn Uvalde","source":"https://www.visituvalde.org/stay","accessed":"2026-10-03","si":["family","senior","motoring"],"booking_route":"hilton.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":32,"blurb":"Listed by Visit Uvalde (the city''s visitor bureau) at \"2714 E Main St, Uvalde, TX 78801 • (830) 278-1300\". Uvalde is the gateway town TPWD points visitors to (\"Visit the Uvalde Visitors Center\"). Hilton''s own page was not fetched, so nothing else about the property is stated here."},{"name":"Holiday Inn Express & Suites Uvalde","source":"https://www.visituvalde.org/stay","accessed":"2026-10-03","si":["family","senior","motoring"],"booking_route":"ihg.com (brand booking; not fetched)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":33,"blurb":"Listed by Visit Uvalde at \"2801 E Main St, Uvalde, TX 78801 • (877) 666-3243\". IHG''s own page was not fetched, so nothing else about the property is stated here."},{"name":"House Pasture Cattle Company","source":"https://www.housepasture.com/","accessed":"2026-10-03","si":["culinary","entertainment","family"],"booking_route":"not read","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":34,"blurb":"\"Restaurant, Full Bar, Live Music\", \"Located in the heart of Concan, Texas\" at \"3064 CR 348 ( River Road )\"; seasonal - the page notes it is \"closed for the off-season\" and reopens Memorial Day weekend. (830) 232-6580."},{"name":"Neal''s Dining Room","source":"https://www.nealsdiningroom.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"not read","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":35,"blurb":"20720 TX-127, Concan: the dining room of Neal''s Lodges (founded 1926), \"within walking distance from most cabins\" per the Lodges'' site; menu, specialties and desserts on its own site."},{"name":"Bent Rim Grill","source":"https://friocanyonmotorcyclestop.com/bent-rim-grill/","accessed":"2026-10-03","si":["culinary","motoring","entertainment"],"booking_route":"walk-in; groups and catering by phone","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":36,"blurb":"657 West Ranch Road 337, \"½ mile west of Highway 83, Leakey\": \"Ride to Eat, Eat to Ride\" - 100% Angus burgers grilled to order, weekend breakfasts, a bar, and live music Saturdays 7-11pm. 830-232-6649."},{"name":"Gypsy Sally''s","source":"https://www.gypsysallysleakey.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"not read","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":37,"blurb":"\"Burg · Margs · TXMX\" at \"373 Market Street Leakey, Texas 78873\", with catering. 830-260-1001."},{"name":"Hippie Chick''s River Shack","source":"https://www.friocanyonchamber.com/business-directory","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"not read","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":38,"blurb":"Listed by the Frio Canyon Chamber of Commerce under Restaurants & Cafes in Concan (facebook.com/hippiechicsconcan). No own website; nothing else stated."},{"name":"Magers Family Farm & Bakery","source":"https://www.friocanyonchamber.com/business-directory","accessed":"2026-10-03","si":["culinary","culture","family"],"booking_route":"not read","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":39,"blurb":"Listed by the Frio Canyon Chamber of Commerce under Bakeries. The Magers name is the park''s own origin story: TPWD records that \"The Magers family, German immigrants who settled in this area, opened part of their land for camping in the 1920s.\""},{"name":"Leakey","source":"https://www.friocanyonchamber.com/business-directory","accessed":"2026-10-03","si":["motoring","family","river"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":40,"blurb":"The Real County seat on the Frio, home of the Frio Canyon Chamber of Commerce (\"Daily 8am-5pm\", (830) 834-5020, P.O. Box 743 Leakey), whose directory lists 15 restaurants and cafes, 17 RV parks and campgrounds and 30 cabin and resort properties across the canyon. TPWD sends Garner visitors to the Chamber \"for more information.\""}],"faq":[{"q":"How much does it cost to get into Garner State Park?","a":"TPWD lists \"Ages 13+: $8 daily\"; children 12 and under are free. A \"Texas State Parks Pass\" at \"$70 Per Year\" gives \"unlimited visits to more than 80 state parks without paying entrance fees.\"","source":"https://tpwd.texas.gov/state-parks/garner/fees-facilities/entrance-fees","accessed":"2026-10-03"},{"q":"Do you need reservations for Garner State Park?","a":"Strongly advised: \"We often reach capacity and highly recommend reservations for both camping and day use. To guarantee entry, reserve passes online or by calling the customer service center before you visit\" - (512) 389-8900.","source":"https://tpwd.texas.gov/state-parks/garner","accessed":"2026-10-03"},{"q":"Do you need a fishing license at Garner State Park?","a":"Not from the bank: \"Try your luck fishing the Frio - no license needed to fish from shore!\" TPWD adds, \"We also loan fishing gear for use in the park.\"","source":"https://tpwd.texas.gov/state-parks/garner","accessed":"2026-10-03"},{"q":"Can you kayak at Garner State Park?","a":"Yes. The park concession''s Boat House rents a \"1 Person Kayak\" at \"$15 per hour\" and a \"2 Person Kayak\" at \"$20 per hour\", plus paddle boats, SUPs and floats; \"Must be 18 years old to rent, bring a valid ID\" and it is \"Cash Only\". It opens \"7 Days a Week\" in summer and is closed in December and January.","source":"https://garnerstatepark.com/boat-house","accessed":"2026-10-03"},{"q":"What time is the Garner State Park dance?","a":"The concession lists the dance at \"8:30-11pm\", \"7 days a week starting Memorial Weekend\", with \"Summer Dances May 24-Aug 10\" and \"Spring Break Dances MARCH 8-15\". TPWD advises: \"Arrive early, as parking lots get full and gates can close as early as 8:30 p.m.\"","source":"https://garnerstatepark.com/the-dance","accessed":"2026-10-03"},{"q":"Can you take alcohol to Garner State Park?","a":"Not in public view. The Texas State Parks rules: \"Public display or consumption of alcohol is prohibited. All outdoor areas within the park are public.\"","source":"https://tpwd.texas.gov/state-parks/park-information/rules/","accessed":"2026-10-03"},{"q":"Are dogs allowed at Garner State Park?","a":"On a leash: \"keeping pets on leashes, no longer than 6 feet, at all times. Please note: Pets are not permitted in any buildings at Texas State Parks.\" Garner''s cabins and screened shelters are both listed as \"No pets\".","source":"https://tpwd.texas.gov/state-parks/park-information/rules/","accessed":"2026-10-03"},{"q":"What should I take to Garner State Park?","a":"TPWD''s trail advice: \"Prepare for sun and heat. Wear sunscreen, insect repellent and appropriate clothing/hiking shoes\"; \"Bring a quart (32 oz.) of water per hour of activity\"; and for Crystal Cave, \"Don''t forget a flashlight\". Cabins come with \"No utensils or dishes\" and \"No linens, blankets or towels provided\".","source":"https://tpwd.texas.gov/state-parks/garner/trails-info","accessed":"2026-10-03"},{"q":"When was Garner State Park established?","a":"\"The park opened June 1, 1941, and was named for John Nance ''Cactus Jack'' Garner\", a Uvalde native and US vice president from 1933 to 1941. \"CCC Company 879 developed Garner between 1935 and 1941.\"","source":"https://tpwd.texas.gov/state-parks/garner/history","accessed":"2026-10-03"},{"q":"What are the cabins like at Garner State Park?","a":"17 cabins in Old Garner - 13 with fireplace at $150 a night and 4 without at $130, plus entry - each with \"Kitchen sink, Microwave, Refrigerator, Stove without oven\", a bathroom with shower, two double beds and central air and heat. \"A 2-night minimum reservation is required on all cabins\"; \"No pets\".","source":"https://tpwd.texas.gov/state-parks/garner/fees-facilities/cabins","accessed":"2026-10-03"}],"seo":{"meta_title":"Garner State Park: Frio River, Old Baldy & the Dance | TravelWell","meta_description":"2.9 miles of Frio River, 16 miles of trails, the summer jukebox dance, cabins and campsites that fill early, and where to camp and stay in Concan and Uvalde.","slug":"garner-state-park-texas","primary_keyword":"Garner State Park","jsonld_type":"TouristDestination"},"hero":{"query":"Garner State Park Frio River Old Baldy"}}'::jsonb, 67),
  ('palo-duro-canyon-texas', '12A', 'Palo Duro Canyon State Park', 'United States', 'The country''s second largest canyon, in the Panhandle', 'future', 'verified', 'mountainValley', 'Texas', '{"hiking","motoring","glamping","family","culture","parks"}', '{"dramatic","rugged","adventurous","family-friendly"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Palo Duro Canyon","source":"https://tpwd.texas.gov/state-parks/palo-duro-canyon","accessed":"2026-10-03","si":["hiking","adventure","family","motoring"],"booking_route":"day pass via the Texas State Parks reservation system (ReserveAmerica) or at the gate","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":1,"blurb":"\"The second largest canyon in the country lies in the heart of the Texas Panhandle\"; elevation 2,759 to 3,463 feet, \"over 30 miles of trails\", hiking, biking, horseback riding, geocaching and bird watching. Adults $8 a day, children 12 and under free."},{"name":"Lighthouse Trail","source":"https://tpwd.texas.gov/state-parks/palo-duro-canyon/trails-info","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - park trail, covered by the entrance fee","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"2.8 mi. (one-way)\", \"2 hrs.\", \"Moderate\" - the park''s signature hike to the Lighthouse formation. TPWD warns that \"most heat-related injuries and deaths for people and pets occur on this trail\" and to \"take plenty of water.\""},{"name":"TEXAS Outdoor Musical","source":"https://www.texas-show.com/","accessed":"2026-10-03","si":["entertainment","family","culture"],"booking_route":"own website tickets (texas-show.com) or 806.651.2181","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":3,"blurb":"Presented \"at the Pioneer Amphitheater in Palo Duro Canyon\", 11450 State Park Hwy Rd 5; \"Show Runs Tuesday - Sunday\" in season. TPWD lists \"summer performances of the TEXAS Outdoor Musical\". Tickets and dinner details by phone 806.651.2181 or info@texas-show.com."},{"name":"Palo Duro Canyon rim cabins","source":"https://tpwd.texas.gov/state-parks/palo-duro-canyon/fees-facilities/cabins","accessed":"2026-10-03","si":["romance","culture","hiking"],"booking_route":"Texas State Parks reservation system (ReserveAmerica) or (512) 389-8900","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":4,"blurb":"Three CCC-built cabins on the rim, sleeping 4 each: Lighthouse and Goodnight (\"Located on the canyon rim with a beautiful view\", fireplace, queen bed, full futon, shower) at $125 a night, and Sorenson with two fireplaces at $150, plus entrance fee; $50 deposit at check-in; no pets."},{"name":"Palo Duro Glamping","source":"https://www.paloduroglamping.com/","accessed":"2026-10-03","si":["glamping","romance","family"],"booking_route":"own website \"BOOK NOW\" (booking engine not named)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":5,"blurb":"\"Luxury camping\" inside the park: \"Each Glaming cabin is fully furnished\" with \"air conditioning, a fridge, a coffee maker, a gas grill and fire pit (propane included), games, linens, a covered porch, hammocks, s''mores kits\". TPWD: \"you cannot reserve this site through our system.\" 806.488.2821."},{"name":"Old West Stables","source":"https://www.oldweststables.com/","accessed":"2026-10-03","si":["adventure","family","wildlife"],"booking_route":"own website \"Book Online\" or (806) 488-2180","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":6,"blurb":"Inside the park: \"Our most popular 1-hour ride is perfect for first time riders. You''ll see the beauty and ruggedness of Palo Duro Canyon State Park close up\"; groups \"never exceeding 5 riders\"; riders 6 and up, adults under 225 lbs; \"No riding experience needed!\" (806) 488-2180."},{"name":"Palo Duro Canyon electric campsites","source":"https://tpwd.texas.gov/state-parks/palo-duro-canyon/fees-facilities/campsites","accessed":"2026-10-03","si":["motoring","family","hiking"],"booking_route":"Texas State Parks reservation system (ReserveAmerica, parkId 1200105)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":7,"blurb":"Juniper (18 sites, 30/50 amp, three ADA sites), Mesquite and Sagebrush (47 sites) and Hackberry (32 sites) - water and electric hookups, restrooms with showers, Mesquite/Sagebrush and Hackberry taking \"up to 60-foot RVs\"; $26 a night plus entrance fee."},{"name":"Fortress Cliff and hike-in primitive camping","source":"https://tpwd.texas.gov/state-parks/palo-duro-canyon/fees-facilities/campsites","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"Texas State Parks reservation system (ReserveAmerica)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":8,"blurb":"18 tent-only drive-up sites in the Fortress Cliff area (\"Picnic table, Fire ring, Water nearby, Shade shelter\", no RVs) at $16, and hike-in primitive camping for 40 at $12 - \"Minimum 1/2 mile hike; bring your own water\", containerized fuel stoves only, no open fires."},{"name":"Cow Camp cabins","source":"https://tpwd.texas.gov/state-parks/palo-duro-canyon/fees-facilities/cabins","accessed":"2026-10-03","si":["family","hiking"],"booking_route":"Texas State Parks reservation system (ReserveAmerica) or (512) 389-8900","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":9,"blurb":"Four basic cabins on the canyon floor: electricity, microwave, refrigerator, A/C and heat, full bed and twin bunk; \"Restrooms with showers are nearby\"; cabin #2 sleeps 2 with ADA features; $60 a night; \"No linens provided\"."},{"name":"Givens, Spicer, Lowry and CCC trails","source":"https://tpwd.texas.gov/state-parks/palo-duro-canyon/trails-info","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - park trails, covered by the entrance fee","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"TPWD rates both \"Difficult\": the Givens, Spicer, Lowry trail at 3.1 mi and the CCC trail at 1.4 mi."},{"name":"Pioneer Nature Trail","source":"https://tpwd.texas.gov/state-parks/palo-duro-canyon/trails-info","accessed":"2026-10-03","si":["family","senior","hiking"],"booking_route":"none needed - park trail, covered by the entrance fee","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"The park''s short walk: \"Pioneer Nature: 0.4 mi.\", rated \"Easy\"."},{"name":"Palo Duro Canyon Visitor Center and park store","source":"https://tpwd.texas.gov/state-parks/palo-duro-canyon","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"none needed - covered by the entrance fee","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities","shop"],"draw_rank":12,"blurb":"The Visitor Center sits on the canyon rim; the park store sells \"books, pottery, jewelry\"."},{"name":"The Trading Post","source":"https://tpwd.texas.gov/state-parks/palo-duro-canyon","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop"],"draw_rank":13,"blurb":"On the canyon floor: \"souvenirs, snacks, meals\" (TPWD); Palo Duro Glamping sells burger kits at the Trading Post for \"$7.99\"."},{"name":"Water for every mile of trail","source":"https://tpwd.texas.gov/state-parks/palo-duro-canyon/trails-info","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":14,"blurb":"TPWD''s own kit rule: \"Bring at least one quart of water per person per mile\", with extra for pets; on the Lighthouse Trail \"take plenty of water\"; hike-in campers \"bring your own water\"."},{"name":"Sun and heat protection for the canyon","source":"https://tpwd.texas.gov/state-parks/palo-duro-canyon/trails-info","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":4,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":15,"blurb":"TPWD: \"Prepare for sun and heat\" and \"Wear sunscreen, insect repellent and appropriate clothing/hiking shoes\" - the canyon floor is where \"most heat-related injuries and deaths for people and pets occur\" on the Lighthouse Trail."},{"name":"Doves Rest Cabins","source":"https://www.dovesrestcabins.com/","accessed":"2026-10-03","si":["romance","glamping","family","hiking"],"booking_route":"own website availability tool (dovesrestcabins.com/rates-and-availability/)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":16,"blurb":"\"The #1 And Only Private Vacation Homes Overlooking Palo Duro Canyon State Park\": 20 cabins in four groups (Longhorn Ranch, North Rim, West Rim incl. SkyHouse and Lighthouse, Wildlife) with electric fireplaces, hot tubs, propane grills, full kitchens and Wi-Fi, some with EV chargers; \"a few minutes from the main entrance\", 16 miles from Canyon."},{"name":"Canyon Rim RV","source":"https://www.hipcamp.com/en-US/state-park/united-states/texas/palo-duro/cabins","accessed":"2026-10-03","si":["motoring","hiking"],"booking_route":"Hipcamp listing (own site canyonrimrv.com redirects to an unrelated domain)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":17,"blurb":"\"uniquely situated on the rim of the breathtaking Palo Duro Canyon\" with full hookups (Hipcamp listing). Its own domain now redirects elsewhere, so nothing more is stated here."},{"name":"Amarillo By Morning RV Park","source":"https://www.bigtexan.com/pages/amarillo-morning-rv-park","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Campspot (campspot.com/book/amarillobymorningrv)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":18,"blurb":"900 S Lakeside Dr, Amarillo: \"just off I-40 & Lakeside, nestled under mature trees for a peaceful, shaded stay\"; big-rig friendly full hookups, Deluxe or Premium sites, daily $75, and a free shuttle to the Big Texan RV Ranch''s heated indoor pool. (806) 373-1431."},{"name":"Big Texan RV Ranch","source":"https://www.bigtexan.com/pages/rv-ranch","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Camping.com booking portal, or (806) 373-4962","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":19,"blurb":"1414 Sunrise, Amarillo: full hookups at all sites, \"Heated indoor pool\", sauna, \"3 Fenced dog parks\", \"Free coffee and bagels in the morning\", and cabins with an \"authentic old west experience with modern comforts\"; daily RV rate $85. (806) 373-4962."},{"name":"Amarillo RV Resort","source":"https://www.hipcamp.com/en-US/state-park/united-states/texas/palo-duro/cabins","accessed":"2026-10-03","si":["motoring","glamping"],"booking_route":"Hipcamp listing (own site not read)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":20,"blurb":"\"spacious RV accommodations and well-appointed cottages for vacationers and travellers\" (Hipcamp listing); The Dyrt lists it as a full-service resort with RVs, cabins and glamping."},{"name":"Amarillo KOA","source":"https://thedyrt.com/magazine/local/awesome-camping-near-amarillo-texas/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"koa.com (not fetched - HTTP 403)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":21,"blurb":"Listed by The Dyrt as offering \"RVs and glamping accommodations\", 5 miles from Amarillo. koa.com refused the fetch (HTTP 403), so nothing else is stated here."},{"name":"Hampton Inn & Suites Canyon","source":"https://hotelguides.com/attraction-maps/texas/map-hotels-near-palo-duro-canyon-state-park-tx.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"hilton.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":22,"blurb":"Listed by HotelGuides at \"3101 4th Avenue, Canyon, TX 79015\", \"14 miles\" from Palo Duro Canyon State Park. Hilton''s own page was not fetched (brand sites return 403), so nothing else is stated here."},{"name":"Holiday Inn Express & Suites Canyon","source":"https://hotelguides.com/attraction-maps/texas/map-hotels-near-palo-duro-canyon-state-park-tx.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"ihg.com (brand booking; not fetched)","commission_s